/* 令和元年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r01.committeeSessions.push(...[{"id":"r01-20191111-7","meetingId":"r01-cm11","date":"2019年11月11日","dateIso":"2019-11-11","committee":"厚生委員会","time":"午後 １時００分～午後 ６時２０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を82件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和元年陳情第４３号 高齢者への補聴器購入費用の助成を求める陳情","agenda":"令和元年陳情第４３号 高齢者への補聴器購入費用の助成を求める陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はこの加齢性難聴を課題として捉えて対応していくということが、区としても求められているのではないかなと思います。加齢性難聴に対しての区の認識と、課題と捉えることについてはどう考えられているのかということについて、まずお聞かせいただきたいと思います。","respondent":"大串福祉計画課長","answer":"そういった補助のありようと、それからそれを使われるであろう方の実態といったものの整合性といいますか組み合わせが、一つ大きな課題になるのではないのかと認識しております。","voiceIndex":6,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"？２０１７年度国際アルツハイマー病協会国際会議が認知症の３５％は、予防可能な９つの原因より起こると考えられていると。その中で難聴が９％を占めて、最大の危険因子になっているということも発表したわけなのです。こういう報告、また国際会議の中でも認知症の最大の危険因子が難聴だという発表、こういうものを、区としてどう受けとめられているのか、その点についてもお聞かせいただきたい。","respondent":"大串福祉計画課長","answer":"先ほども申し上げましたが、そういった視点も含め、調査、検討させていただければと考えているところです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"認知症予防の観点からも、早期での補聴器使用を進めることが重要だというのは、耳鼻科の先生の中でも一致した見解があると思います。そういうところでも早期の着用が必要だということで、耳鼻科の先生も含めてそういう方向というのは出しているので、そこのところは区としてもやはり取り組むことが必要なのではないかなと思いますが、その点はいかがでしょうか。","respondent":"大串福祉計画課長","answer":"専門家の意見、知見というのは非常に大きなところだというふうには認識しております。そうした中でさまざまなまた違う角度からのご意見等も中にはあろうかと思いますので、そうしたところを踏まえた上で検討を重ねていきたいと考えております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"補聴器の早期使用の点についても、区としてはさまざまな意見があるという考え方ですか。これは多分一致できるのではないかと思います。加齢性難聴の方が補聴器を早期に着けることで、さまざまな効果を生み出していく。だから、補聴器を早期に着けるということがとても大事なのだというところでは、認識は同じということでよろしいでしょうか。","respondent":"大串福祉計画課長","answer":"そうした意味では、予防の観点、ご本人のお気持ち、あるいは着ける、着けないといったご判断も大きな問題になってこようかと考えています。そういったところを含めて、総合的に判断させていただければと考えております。","voiceIndex":12,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、そこのところは認識を一致させていただきたいなと思います。難聴に早くに気づいて、早くに補聴器を着けることがとても大事である。微妙な調節をしながら、リハビリをしながら、その人に合う補聴器にしていくといったことはその後のことなのですが、補聴器を早期に着けることが加齢性難聴にとっては必要なのだ、大事なことなのだと。そこのところでは一致しているということで、よろしいでしょうか。","respondent":"大串福祉計画課長","answer":"今おっしゃっていただいたことも含めて、総合的に判断していきたいと思います。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"本当にこれは耳鼻科の先生もとても強調していることです。ここのところが、早期補聴器の使用がいいのかどうなのかも総合的に判断するということになると、区の認識がそれでいいのかということを問わなければならないのですが、ドクターの立場で、そこら辺のところをお聞かせいただくというのはできないでしょうか。","respondent":"大串福祉計画課長","answer":"再三申し上げていますように、早期がいいのか、あるいはもう少し進んだ段階でいいのかといったところも含めて、総合的に判断していきたいと考えています。","voiceIndex":16,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところはぜひとも認識していただきたいと、強く要望しておきたいと思います。そこのところは、ぜひそういう認識を持っていただきたいということを強く申し上げておきたいと思います。２３区の中でも８区がもう既に補聴器の購入費補助を行い、補聴器を早期に着用するという方向で啓発も行っています。実態をつかむというところでは、どういうふうにやっていくのかということもお願いしたいと思います。","respondent":"大串福祉計画課長","answer":"そうした中で、どのような形で助成といいますか補助することが一番効果的なのかといったところについて、見極めを行った上でと考えているところです。","voiceIndex":18,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今、補聴器購入費補助が東京都の包括補助の対象になっています。もし品川区がそういう補助制度をつくるとしたら、その包括補助で２分の１を都が補助する仕組みがあるということです。もし品川区が購入費補助を行うということになれば、この東京都の包括補助が使えるのではないかなと思いますが、その点についてもお聞かせください。","respondent":"大串福祉計画課長","answer":"補助をするかどうかということを検討します。その上で特定財源等見込まれるものがあれば、そういったものも活用していきたいと考えているところです。","voiceIndex":20,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"はい、もう一つだけ。この問題では、ＷＨＯでも補聴器を早期に着けるということを推奨しているのです。４１デシベルの中等度の人から補聴器を着けることを推奨しているということなのです。ＷＨＯでもそういうふうに推奨しているということなので、これはぜひ早期着用というところで、このことをもう一つつけ加えて申し上げておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"補聴器の購入なのですが、難聴の重度・中度・軽度とあって、身体障害、聴覚障害を受けていると、補聴器の補助がたしかあったと思います。それから、お子さんについては、品川区も中程度まで補助を、助成と言ったらいいのでしょうか、あったかと思います。品川区で今それぞれ難聴の重度・中度・軽度は、どのくらいの人数がいらっしゃるかというのを把握していらっしゃいますでしょうか。推計値でも構いません。","respondent":"松山障害者福祉課長","answer":"聴覚障害の方の全数は把握していますが、補聴器を使っている方でというふうに限定しますと、やはりかなり調査しなければ出てこないということです。","voiceIndex":25,"id":"exchange-010"},{"speaker":"あべ委員","kind":"質問","question":"聴覚障害の方の全数がわかるということのようで、その数字をください。それから、補聴器を着けている中の重度・中度ということではなくて、品川区民の中で把握されている聴覚障害の中での級の割合がわかれば教えてください。","respondent":"松山障害者福祉課長","answer":"令和元年度、今年４月１日ですが、７８４人ということになっております。補聴器は補装具での中で支給していますが、例えば平成３０年度に支給した延べ件数にしますと、いろいろなタイプがありますが、合計で１４３件という実績は把握しています。","voiceIndex":27,"id":"exchange-011"},{"speaker":"あべ委員","kind":"質問・要望","question":"品川区内で中度・軽度で、どの程度聴覚の障害と言ったらいいのでしょうか、難聴であるかということの推計値を出していくというところが、これを考えるにはまずとても大切なことだと考えています。日本の補聴器使用率は約１３％で、諸外国に比べても非常に低いということで、補聴器を普及させなければいけないというのは、これはもう品川区だけでなくて全国的な課題でもあると思います。","respondent":"大串福祉計画課長","answer":"難聴ということに関しても、区として、どういった形で予防あるいは進行をとめることができるかといったところについては、さまざまなご意見を伺いながら周知・啓発を図っていきたいと考えております。","voiceIndex":29,"id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"今すぐにお答えいただけるのは、かなりざっくりしたところだと思いますが、ちょっと難聴の問題というのも、ぜひ品川区で一つのテーマとして取り上げていただければなと思うのですが、ここはお答えいただけますでしょうか。","respondent":"大串福祉計画課長","answer":"関係する部署等が出てこようかと思います。そちらとの連携を図りながら、一つテーマとしてということで、さまざま課題はありますが、そういった中でも難聴といったところにもフォーカスを当てていければと考えています。","voiceIndex":31,"id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今いろいろお話を聞いていまして、これから実態把握と普及・啓発等を進めていくということだと思いますが、今までに品川区では、難聴の方や聞こえという部分で啓発等は特にしてはこなかったのか。高齢者クラブやシルバー大学といった、対象になるような団体での講習会・交流会といったことに広げられたところはなかったのか。そこを伺いたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"会議には関係者だけでなく、外部の方を招いて何かお話をしていただくなど、周知・啓発をしていただくといった機会も多々あります。そういった方にはそのようなご案内を事前にさせていただいているところです。","voiceIndex":34,"id":"exchange-014"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"実態把握にしても、どういう立場で把握していくかというのがとても大事だと思います。ですので、難聴の問題を早期に対応することで、認知症も鬱も社会的孤立も防ぐ可能性があるということを伝える。先ほど研究者の論文等もお伝えがありましたが、ぜひ品川区としてはそういった立場で実態調査、そして普及・啓発をしていただきたいと思いますが、いかがでしょうか。","respondent":"大串福祉計画課長","answer":"先ほども申し上げまして、さまざまなご意見等あろうかと思います。そうした中、ご意見をさまざま伺わせていただきながら、どういった形が一番有効なのかというのは判断させていただければと考えております。","voiceIndex":36,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"先ほど国際アルツハイマー病協会でのことをご紹介しました。オレンジプランの中でも、難聴が危険因子の一つということで挙げられています。認知症の予防という点からも、難聴に対しての早い時期での対応というのがとても大事になると思います。認知症のところでの補聴器早期着用についての啓発は、区の取り組みとしてはされているのかどうか。その点について、お伺いします。","respondent":"寺嶋高齢者福祉課長","answer":"少なからず認知症に効果があること、生活のしやすさに対して寄与するものにつきましては、これからも情報収集に努めて、必要なものにつきましては対策として取り組んでいくことが、これは補聴器に限らずですが。","voiceIndex":39,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これが学会で発表されたのが２０１７年なので去年、一昨年という状況、またオレンジプランが出されたのもちょっと前なので、そういう点では、早期に補聴器が大事なのだという具体的なその辺のところがされているかどうかというところを教えていただきたいと思います。その具体的な状況を教えていただきたいと思います。","respondent":"寺嶋高齢者福祉課長、松山障害者福祉課長","answer":"１点目の認知症の取り組みの中で補聴器が重要であるということを啓発しているかどうかということにつきましては、具体的に補聴器を着けるとよくなります、改善されますといったご案内はしておりません。身体障害者手帳の交付を受けた方の内、耳鼻科の医師の補聴器が必要だという診断書に基づいて、こちらのほうは補助しているものです。ですから、個別性が高いと認識はしております。","voiceIndex":41,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"基本的には聞こえるが、かなり聞き取りにくい。そういう点では、本当にこういう成果が上がったり、議会の中で取り上げられたりということを機会に、ぜひとも区としてもこの問題に向き合っていただいて、補聴器補助をしていただいたり、それだけではなく補聴器が早期に着けられるような啓発やさまざまな支援の体制というのをぜひとっていただきたいということで、要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-018"},{"speaker":"渡部委員","kind":"質問・要望","question":"議論を伺っていて、このような陳情が挙がっている中で、さまざまな考え方があると思うのです。であれば、例えば補聴器の問題に関しても、では全員に対してなのか。どういう状況なのか。場合によっては、これというのは僕らが議員なわけだから、国に対して議会で要望を上げることかもしれない。ただ、実際さまざまお困りの方もいらっしゃる中で、どういうふうにしていかなければいけないか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-019"},{"speaker":"西村委員","kind":"質問・要望","question":"今、渡部委員がおっしゃったように大変課題もたくさんあると思いますので、継続でお願いしたいと考えています。先ほど課長からもありましたように、現在の実態がつかめていないということ。は根拠、情報が求められると思いますので、一足飛びには難しいというところにポイントがあると思います。調査を進める必要があるため、継続でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-020"},{"speaker":"若林委員","kind":"質問・要望","question":"私の会派も継続でお願いしたいと思います。区の今の総合的な実態把握も含めて考えていきたいというところで、課題がちょっと余りにも多過ぎる。例えば買った人の２５％ぐらいが使っていない。これは相当な課題です。実際に、公的に支援すると。しっかり見極めていただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"結論を出すということで、そして採択ということでお願いしたいと思います。２５％というのも、専門のドクターを通して、補聴器というのはどういうものだよという説明をあらかじめきちんと受けて、そして認識を持った上で補聴器を購入して訓練していくというやり方というのは、もうつくられているものなのです。私は啓発も含めて、足を踏み出していくということがとても大事だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-022"},{"speaker":"あべ委員","kind":"質問・要望","question":"私もこの件について継続でお願いしたいと思います。先ほどもありましたが、他の自治体でも非課税世帯２万円というのが一つのスタンダードな助成のラインなのです。そうすると、たとえ助成をするにしても、実効性ある助成とはどういう仕組みであるのか。そういったことについて見ていくという意味も含めて、継続でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-023"}]},{"id":"topic-02","title":"令和元年陳情第４５号 障害者が安全に利用できる心身障害者福祉会館の整備を求める陳情","agenda":"令和元年陳情第４５号 障害者が安全に利用できる心身障害者福祉会館の整備を求める陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１つは、災害時にエレベーターを使うことができないということで、先ほど車いすを使われている方が９名ということですが、ちょっとあそこの構造がよくわからないのですが、２階からはスロープがあるけれども、その上からはスロープというのはないという構造なのでしょうか。そして、３階、４階の場合は、階段を担架でおろすということになるのでしょうか。その点を教えていただきたいと思います。","respondent":"松山障害者福祉課長","answer":"どちらかの階段を使って、布担架あるいは、電動車いすですと重量が多くて難しいとは思いますけれども、通常の車いすであればそのままおりるということも可能です。は布担架ということであれば、車いすから担架に移乗させて、安全を確認しておりる体制をとっているです。","voiceIndex":57,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"建物の耐震というところでは倒壊の危険性は低いということだったのですが、耐震の基準は満たされているのかどうかというところです。ＩＳ値というのもここ（令和元年陳情第４５号）に出てきています。ＩＳ値というのは、私は１以上というふうに思っていたのですが、こういう建物の場合のＩＳ値というのは、幾つ以上というところで基準として出されているのか。その点についてもお聞かせください。","respondent":"松山障害者福祉課長","answer":"心身障害者福祉会館の場合は、全ての階におきまして、ＩＳ値は０.６以上というふうに全てクリアされております。次に診断方法です。平成２２年１月に心身障害者福祉会館の耐震診断を行いました方法としましては、２次診断まで実施しているものです。","voiceIndex":59,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"２次診断までされて、その上で全てクリアしているというところでは、この心身障害者福祉会館は安全な建物だということで確認されているということでいいわけですね。この陳情を見て、公表や、調査結果を示して説明していただいたほうがいいのではないかなという思いがしたのですが、そういう点ではいかがでしょうか。","respondent":"松山障害者福祉課長","answer":"心身障害者福祉会館の場合につきましては１,５９９平米となっておりますので、特にくくり出しまして公表する予定はございませんが、安全性についてはきちんと耐震診断を行いまして、実際に訓練につきましてもご利用者を含めて一緒に参加して、毎月やっているということです。","voiceIndex":61,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"２次診断までされて、そういうデータが出ているわけですから、大丈夫ですよということを聞かれれば、通われている方は安心されるのではないかと思います。ぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-027"},{"speaker":"あべ委員","kind":"質問","question":"前回の委員会でもありましたが、この心身障害者福祉会館が建て替え可能だとわかったのは、区民から指摘いただいたということで、改めてありがたいなと考えています。今回も大変真っ当な指摘をいただいております。この施設は、福祉避難所になる計画はあるのでしょうか。","respondent":"松山障害者福祉課長","answer":"心身障害者福祉会館は、二次避難所の扱いになっております。","voiceIndex":65,"id":"exchange-028"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、ちょっとうろ覚えなのですが、今各階のＩＳ値が０.６以上ということではあったのですが、避難所になる場合というのは、もう少しレベルが高かったのではないかなと。ここなどは１.０とかいう数字、違ったでしょうか。０.７でしたか。その辺はいかがなのでしょう。","respondent":"松山障害者福祉課長","answer":"東京都の福祉保健局のほうでも民間への補助金の支給条件が０.７以上となっておりまして、心身障害者福祉会館の場合については０.７以上も全ての階においてクリアされております。","voiceIndex":67,"id":"exchange-029"},{"speaker":"あべ委員","kind":"質問","question":"０.７以上というのもクリアされているということでお伺いいたしました。そういったことを考えると、この心身障害者福祉会館も今すぐにではないにせよ、やはり建て替えをすると同時に機能を充実させ、また安全性や災害時の対応などもブラッシュアップしていく必要があるかと思うのですが、現段階で区として、それはどのようにお考えなのでしょうか。","respondent":"松山障害者福祉課長","answer":"要はサービスを継続することというのは非常に大事であると区としては認識しております。今すぐ何か検討しているわけではございませんが、将来にわたって、やはり機能面あるいは老朽化の面、サービス継続の面から総合的に判断する必要があると考えております。","voiceIndex":69,"id":"exchange-030"},{"speaker":"あべ委員","kind":"質問・要望","question":"まさに今おっしゃったサービス継続というのは、とても重要かつ難しい問題だと思います。そういった意味からも、余り先延ばしにせず、具体的な計画をできるだけ早く考え始めていただければと思います。最後は要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-031"},{"speaker":"渡部委員","kind":"質問","question":"本日結論を出すということで、会派としては不採択でお願いします。今、課長からも説明がありましたが、建て替えるとなると、それ相応の準備も必要になると思います。総合的に判断されて、建て替えるときには陳情いただいた方がおっしゃっているようなことを留意して建て替えればということで、ただ、今の今ではないということでしょうから、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-032"},{"speaker":"西村委員","kind":"意見","question":"結論を出すで、不採択でお願いいたします。こちらの会派としましても耐震診断を実施していただいているということと、あと基準が満たされている、あとは災害時に車いす利用者の方も安全に避難ができると認識していると課長もおっしゃっておりましたので、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-033"},{"speaker":"若林委員","kind":"質問","question":"安全に利用できる心身障害者福祉会館についての説明をお聞きしましたので、不採択で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"耐震診断で２次診断までされていて、ＩＳ値が０.７以上あるということは今のご説明でわかりましたが、この方もそういう状況を求めてきたにもかかわらず、説明がされてこなかったということでこういう陳情も出されましたし、また、今の心身障害者福祉会館が本当にあのままでいいという状況では決してなくて、本当に使いやすい心身障害者福祉会館にというところでは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-035"},{"speaker":"あべ委員","kind":"意見","question":"本日、結論を出すということで、不採択でお願いします。今お話がありましたように、早急にというのは今の区の状況に合わないだろうと受けとめました。ただ、長期的には、この心身障害者福祉会館の建て替えが必要であるということは、区ももう既に認識されていると思いますので、その中できちんと計画を立てて、よいものをつくっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-036"}]},{"id":"topic-03","title":"令和元年陳情第４６号 一元化した指定管理による障害児者総合支援施設の管理運営を求める陳情","agenda":"令和元年陳情第４６号 一元化した指定管理による障害児者総合支援施設の管理運営を求める陳情","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"１個だけ教えてください。代表番号に電話したら電話に出る人がいるわけで、誰が出ているのですか。","respondent":"築山障害者施策推進担当課長","answer":"今現在、区から受付業務を委託しております委託業者の職員が出ております。","voiceIndex":87,"id":"exchange-037"},{"speaker":"渡部委員","kind":"質問・要望","question":"わかりました。内容全体としては、もうよくわかる話ですのでそこに入ることもございませんし、一元化した指定管理による管理運営を求める陳情ということなのですが、とりあえず私たちも議決で公募のことをやってきている中で、この陳情自体は一旦不採択にするのですが、例えば電話対応は、委託させているのは委託させているのだけれど、そこの人間として出させなければだめ。そこは直してください。","respondent":"築山障害者施策推進担当課長","answer":"委員にご指摘いただきました点につきましては、館の管理運営ということで研修をして、改善を図ってまいりたいと思います。","voiceIndex":89,"id":"exchange-038"},{"speaker":"あべ委員","kind":"質問","question":"そのこともあって利用者の方々になかなかスマートなサービスができないとすると、先ほどおっしゃったような共同事業体という形をとらなかった理由というだけでは、ちょっと区としても責任がとれないのではないかというふうに、やはりこれは区立の施設で区の事業ですから、共同事業体解散の形になってしまったことも、その条件というのも、やはり最終的には区が責任を持つべきことだと感じます。","respondent":"築山障害者施策推進担当課長","answer":"それぞれの事業で収益に落差等が出ると思いますが、そういったものの采配が難しいといった課題がありました。建物管理をするに当たって、どこが代表として実施していくのかといったところの難しさもございました。","voiceIndex":92,"id":"exchange-039"},{"speaker":"あべ委員","kind":"意見","question":"最初は４法人あった。なので、やはりそれも含めて区の責任というのをどのようにお考えになっているかということ。とりあえずの今回の契約期間は３年間ですが、ぜひ区が力強くこことの関係をまずは保って、そして信頼関係を向上させて、安定したサービスを始められる。そのための第１歩がうまくいっていないからこそ、電話のやりとりもうまくいかないというようなこともあると思います。","respondent":"築山障害者施策推進担当課長","answer":"最初のご質問にありましたが、区の責任というところでは、当初のプロポーザルのときに、建物管理の実施部分について、公募の段階からどこが実施するのか等を明確に確認した上ですべきだったのですが。","voiceIndex":94,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このフリーユニティーという法人というのは、たしかこういう形は初めてということであったわけですけれども、そういう初めてのことだけに、議会の中でもかなりいろいろと確認のやりとりというのはあったと思います。ただ名前だけなのか。そこら辺のところはどうなっているのかも教えていただきたい。１０月というところでは、私は引き続いてこの事業者にやっていただきたいという思いなのです。","respondent":"築山障害者施策推進担当課長","answer":"３年後の体制につきましては、現在どういった形で実施していくか、検討している段階です。","voiceIndex":97,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"言ってみれば、一番初めのプロポーザルで応募して選定された事業所が、そういう一般社団法人フリーユニティーという形になったものではないのですか。その事業者が３年後も引き続いて事業を続けていくためには、どんな課題をクリアすれば引き続いてやってもらえるのかというふうなところとしては、どんなものがあるのか。そこら辺の仕組みも含めて教えていただけたらと思います。","respondent":"築山障害者施策推進担当課長","answer":"当初にはなかった法人という形になっております。３年後のことということで委員からご意見をいただいておりますが、こちらにつきましては、適正な一体的な管理運営ができる施設ということで、現在実施方法について検討しています。","voiceIndex":99,"id":"exchange-042"},{"speaker":"渡部委員","kind":"質問・要望","question":"障害児者の方が待っていた施設ができ上がって、それぞれさまざまなご期待がある中で動き出しているわけですから、とりあえず先ほどから説明いただいているような感じで進められるのを私たちも認めてきているわけだから、それはそれでやっていただきたい。全然内容と違うところでクレームになってもおもしろくないし、そこでけちがつくのも嫌ですから。この内容自体は不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-043"},{"speaker":"西村委員","kind":"意見","question":"結論を出すで、不採択でお願いいたします。区民の方々がせっかく期待を持ってできた施設ですので、安心して使っていただけるようにしたいという思いはありますが、一元化した指定管理による効率的で効果的な管理運営についてということに関しましては、現在検討中ということですので、不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-044"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。今日の答弁でもありましたように、３年後、当初から、いわゆる一元化をした効率的で効果的、また最良、最善の運営者が、法人が、またサービスできるように、ぜひ頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"結論を出すで、趣旨採択でお願いしたいと思います。新たな事業者も公募して、検討するとかということではなく、今のこの事業者が継続できるという形をぜひ研究、検討していただいて、事業者と意思疎通を図りながら、ぜひやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-046"},{"speaker":"あべ委員","kind":"質問・要望","question":"繰り返しになりますけれども、３年後という話もありましたが、それぞれの事業者は各地で非常に評価の高いところでもありますし、私たちもとても期待しているところです。そこが３年後にもし逆に手を引くというようなことがあれば、今後品川区のこの分野で良質な事業者がなかなか入ってこなくなってしまうのではないかということも少々危惧しております。同じ熱量で取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-047"}]},{"id":"topic-04","title":"建物明渡等請求事件の結審","agenda":"建物明渡等請求事件の結審","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"結審してよかったなと思います。お疲れさまでした。１点確認したいのが、この被告３名です。別の見方から言えば、福祉的な配慮が必要な相手かどうか。追い出されてホームレスになったりでは困りますので、どういう状況か、話せる範囲で教えてください。","respondent":"宮尾高齢者地域支援課長","answer":"ですので、詳しい状況まではつかんではおりませんが、こういう受け入れる体制はあると、相談はお受けできるということは、３人の中のお一人にお伝えをしているという状況です。","voiceIndex":114,"id":"exchange-048"}]},{"id":"topic-05","title":"「しながわ健康プラン２１」中間・評価見直し（素案）およびパブリックコメントの実施","agenda":"「しながわ健康プラン２１」中間・評価見直し（素案）およびパブリックコメントの実施","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"見直しの作業、どうもお疲れさまでした。大変な作業だったと思います。評価のところなのですが、１３ページ目、先ほど数字が減っているけれど割合が増えたからＡというお話がありましたが、そういう考え方でいいのかなと。お考えをお聞かせください。そこをまずどのように区として考えていらっしゃるかということをお伺いしたいと思います。これは後半どのように変えていくつもりであるのか教えてください。","respondent":"高山健康課長","answer":"確かにマスコミの報道などの影響のほうがはるかに大きいのではないかというのは残念ではあるのですが、そういう意味で申しますと、例えばですが、品川栄養士会とも協力しながら、特に来年度に向けては働き盛りの層に向けた。","voiceIndex":120,"id":"exchange-049"},{"speaker":"あべ委員","kind":"質問・要望","question":"そこをどう変えていくかということで、もう知識ではないのではないかなと思います。今後もう少し重点的にいろいろなことを書き込んでほしいなと考えています。例えば啓発のところ、学校の中で心の授業と言ったらいいですか。区の施策としては、では、それに対してどうするというのがないので、そうした依存症などについても、ぜひ後半で頑張ってもらえればと思いますが、いかがでしょうか。","respondent":"高山健康課長","answer":"依存症の関係で、例えばこの３２ページで申しますと、主な取り組みの中で精神保健講演会といったものの中で、委員がご紹介になったような他の依存、ギャンブルなども含めた依存に関する対応についても取り上げていく内容ですので。","voiceIndex":122,"id":"exchange-050"},{"speaker":"あべ委員","kind":"提案","question":"そういう意味では、区でいろいろな事業をするというだけではなくて、地域の中に拠点をつくっていって、その中でさまざまな健康についての知識や行動、一緒にやっていけるような体制というのも今後つくっていかれたらどうかなと思います。これは、最後、提案といいますか意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":124,"id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それだけに、この目標値というのは、どのように検討して出されたのかというのをちょっと教えていただきたいのと、ここでは庁内検討委員会と書かれていますが、この検討委員会というのはどういうメンバーだったのかについても、ここの中にメンバー表がないので教えていただきたいと思います。","respondent":"高山健康課長","answer":"もう一つなのですが、前期５年の策定時と現在の値を比べますと、おおむねばらつきといいましょうか改善の度合いを見たときに、５％以上厳しくした場合と５％以上緩くした場合を判断して、その上で検討した結果、おおむね５％程度で判断すれば。","voiceIndex":126,"id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その点をお聞かせください。前のときもそうなっていましたが、PLAN、DO、CHECK、ACTION、ＰＤＣＡのサイクルということですが、庁内検討委員会がこれもやるということなのでしょうか。なかなか品川区は説明会をやるという方針を持たないのでどうなのかわかりませんが、少なくとも健康推進委員の方々には説明をしてご意見を伺うことも必要なのではないかなと思いますが、いかがでしょうか。","respondent":"高山健康課長","answer":"個別の話としては、さすがに計画の検討ですので事業の中身の具体までのお話ではございませんが、少なくともこの計画を推進するフェーズ、段階におきましては、そのような計画策定にかかわったということも一つ事業を考えていく上で大変有用なことであろうと考えております。","voiceIndex":128,"id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"健康に関しては、本当に多くの皆さんが関心が高いですし、また健康寿命を伸ばしたいと皆さんが思っているところです。そういうご意見も踏まえた上で、より充実というところでよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":130,"id":"exchange-054"},{"speaker":"若林委員","kind":"質問・要望","question":"５７ページに第６章、プランの推進体制というのがあって、庁内の関係部局間の連携というのがあります。健康推進部を中心に、最後スポーツ関連部局等を含めとありますが、どこからどこまでの連携、関係部局なのか、もうちょっと具体的に教えていただきたい。","respondent":"高山健康課長","answer":"そのほかにもさまざま事業を進めていく中では関連というのは出てくるかと思いますが、今回いろいろな区の取り組みを洗い出す中では、いろいろな課の取り組みというのも見えてまいりましたので、そういった部分はしっかり今後もかかわる形で進めてまいりたいと考えています。","voiceIndex":132,"id":"exchange-055"},{"speaker":"若林委員","kind":"質問","question":"そうすると、今回の重点目標の中で、喫煙、たばこ対策というのがあります。やはり今のお話を伺っても、いわゆる地域振興部や都市環境部なのかな。せっかく今回こういうしながわ健康プラン２１という今後５年間の後期計画をつくるに当たって、これまでの議会、質疑、議論を踏まえて、このプランの策定に当たって、ここはしっかり根拠を持たせようというお考えはなかったですか。","respondent":"高山健康課長","answer":"この計画の性質上、そういう部分の根拠づけとしての意味づけというのですか、意義づけについてはこれにおいては書かれておりませんが、健康増進計画以外の部分で、やはり庁内のしかるべき部門で連携する必要があるという認識は持ってありますので、そういった意味では。","voiceIndex":134,"id":"exchange-056"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"１点だけ、歯と口の健康のところです。３７ページです。ここにはそういう仕組みなども書いていただいて、こういうふうになるからこの口の中の健康というのは大事なんだと思ってもらえる書き方、示し方をしてほしいと思います。健康を守っていくための計画ですよということがわかる具体的なものにしていただきたいと思います。健康プランが、そういったことが示せるものなのかを伺いたいと思います。","respondent":"高山健康課長","answer":"直接は関係ございませんが、例えば８ページをご覧いただきますと、８ページの医療費という欄には、いろいろ検討する必要の中では、歯科という医療費の内訳なども載せてみたりしております。","voiceIndex":137,"id":"exchange-057"}]},{"id":"topic-06","title":"品川区がん対策推進計画（素案）およびパブリックコメントの実施","agenda":"品川区がん対策推進計画（素案）およびパブリックコメントの実施","exchanges":[{"speaker":"あべ委員","kind":"提案","question":"全体によくできたものだと思いますが、幾つか質問と提案をさせてください。品川区でもある程度その辺は参考にされたかどうかということ。自己負担が増えてもいいから麻酔をという声もありますが、その辺はどうお考えでしょう。患者のケアのところなのですが、今ＮＴＴ東日本関東病院と昭和大病院のがん相談支援センターは、何人ぐらいのご利用があるのでしょうか、教えてください。","respondent":"高山健康課長","answer":"２点目の胃の内視鏡の麻酔の件につきましては、検診を立ち上げるに当たっていろいろと協議を医師会とする中で、使用については、もちろん負担軽減という意味では有効ではあるのですが、麻酔事故なども含めて、いろいろな検診実施上の課題もあるということから。","voiceIndex":144,"id":"exchange-058"},{"speaker":"あべ委員","kind":"質問・要望","question":"これはなぜ伺ったかというと、委員にも入っていらっしゃるマギーズ東京、先日見せていただきました。もう一つマギーズでは、患者ご本人だけではなくて、がんに悩むご家族の方、あるいはがんでご家族を亡くされた遺族の方の相談の場といいますか、心の内を話す場としても機能しているやに伺いました。区としてはどのようなかかわりを持って、このセンターについて考えてらっしゃるのか、教えてください。","respondent":"高山健康課長","answer":"例えばそういったものを個別の通知の中で活かしていくというようなことで、受診率の向上については引き続き取り組んでまいりたいと考えております。","voiceIndex":146,"id":"exchange-059"},{"speaker":"あべ委員","kind":"質問・要望","question":"がん相談支援センターなのですが、私も今回これを読むまで、この病院に通っている以外の方も通えるというのは知らなかったのです。ぜひそうしたことも含めて区としてご案内いただければなと思いますし、それを含めて機能を少しずつ足していただければと思います。あれは江東区にあるのですが、江東区とは連携をして、江東区の事業という形でも一部されていると聞いております。以上、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"本当にがんがこれだけ死因の第１位を占めて、そして早期発見・早期治療でかなり死亡率を減らせるはずであるにもかかわらず、がん検診の受診率が伸びないというのが一番の課題だと思います。そういう点では、私はこの計画がとてもいい中身でありますし、また、そういうふうな思いをさせるにもとても役立ててほしいなという思いがしたのです。","respondent":"高山健康課長","answer":"この受診率を上げていくということを、我々としてはまず目標を立てて、しっかりと進めていくということが第一段階だと考えておりますので、それについては先ほどの周知の仕方、そして必要性の訴え方につきましてしっかりと研究する中で。","voiceIndex":150,"id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私も先ほどの２つの拠点病院で、病院の中にがん相談支援センターがあるというのを知らなかったのですけれど、そういうところも含めて、やはり知らせていくというところを、とてもしていただきたいなという思いがしています。品川区が説明会をやらないというのを、ちょっとここで取り払って、ぜひそういう機会として、啓発の機会として、これを使っていただきたいというところで改めて要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-062"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"がんという疾病から区民の命と健康を守るために、こういう計画がつくられているということだと思います。そういった自治体と医療機関との連携をさまざま総合的に推進するという形がとても強く求められているのではないかなと思っています。要は、そういった方々の声を聞く場をつくって反映された計画になっているのかお聞かせいただければと思います。","respondent":"高山健康課長","answer":"そういった意味では、この計画をつくって５年後ということではなくて、しっかりとこの計画についてはそういった意見なども踏まえながら、例えば相談の場所や拠点の確保といった具体的な施策として展開していく中で必要な情報は、今後も収集してまいりたいと考えております。","voiceIndex":154,"id":"exchange-063"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ですので、そういった声を反映できるように、アンケートなどはぜひとっていただきたいと思いますが、いかがでしょうかということ。５１ページ一番下の表のところに、国の目標５０％を目指しつつもということですが、５０％にはとても遠いなという感じがします。国も５０％というふうに出すということは、それに届きそうな自治体があるのでしょうし、あるいは国の目標が高過ぎるのか。そこを伺いたいのです。","respondent":"高山健康課長","answer":"アンケートの手法をとるかということに関しては、やはり事例なども研究する中で、今後、把握の方法については研究、検討してまいりたいと考えております。","voiceIndex":156,"id":"exchange-064"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ほかの委員からもありましたので、引き続きいろいろ工夫をして検診の受診率を伸ばしていっていただきたいと思います。やはり品川のがん検診の無料化です。一足飛びに無料にというのはなかなか難しいかもしれませんが、ぜひ検討していただきたいですし、こういった計画を出すわけですから、やはり命を守る、がんを予防するというところから進んでいくべきではないかなと思いますが、いかがでしょうか。","respondent":"高山健康課長","answer":"やはりこの辺は負担増の関係もありますので、一定の検討をしていく必要はあるとは思いますが、委員ご指摘のような経済的な部分が受診率を下げていくことに直ちには結びつかないというふうには考えているところです。","voiceIndex":158,"id":"exchange-065"},{"speaker":"若林委員","kind":"確認","question":"確認だけ。４４ページに科学的根拠に基づくがん検診の実施で、国の指針にないがんについては、減少、廃止していくと。現行値が６。これがいわゆる国の指針にないがん検診。これをできれば０にしたり、１個でも２個でも多く。６つというのは、具体的に、すみません、教えてください。","respondent":"高山健康課長","answer":"同じページで申しますと、（１）の1)です。国の指針を踏まえた検診の見直し、有効ながん検診の実施の中の現状と課題というところをまず見ていただきますと、２行目の「一方」と書かれているところです。肺がん検診から始まりまして、乳がん検診です。","voiceIndex":161,"id":"exchange-066"}]},{"id":"topic-07","title":"品川区自殺対策計画（素案）およびパブリックコメントの実施","agenda":"品川区自殺対策計画（素案）およびパブリックコメントの実施","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"もちろん同様なご意見があってこれが出てきたのでしょうけれども、それでも、やはり私もこの週末、周囲の方にも伺いましたけれども、これは違うのではないかという方々が非常に多かったです。今からで恐縮ですけれども、これはぜひ見直していただきたいと思います。一言ご感想など。同じ２７ページのこの基本理念、緑で囲った上のところの２つ目の段落ですけれど、これは何か言葉が重複していないですか。","respondent":"鷹箸保健予防課長","answer":"ただ、一般的には周産期の女性が特に非常に大きな問題となっているので、この取り組み方については、なぜここをターゲットにしたかという説明が確かに弱い部分を感じますので、もう少し考えていきたいと考えています。新規事業が少ないという点については、ご指摘のとおりです。","voiceIndex":167,"id":"exchange-067"},{"speaker":"あべ委員","kind":"質問・要望","question":"新規事業が少ないというよりも、これまでやっていることを挙げてもらって書くだけでは、なかなか対策として前に進んでいかないのではないでしょうかということです。３０代の女性のところはご答弁ください。そうした意味では、せっかくこの自殺対策計画ができるわけですから、その中でグリーフサポートということをきちんと文字で打ち出していただければと思いますが、いかがでしょう。","respondent":"鷹箸保健予防課長","answer":"丁寧な１つの相談が、全て自殺予防に役立っているということの認識をまず持ってもらうということはかなり重要と思います。既存事業の見直しの中で、改めてその重要性に気づいてもらったということもあります。","voiceIndex":169,"id":"exchange-068"},{"speaker":"あべ委員","kind":"質問","question":"大変長くなってしまいましたけれども、やはり非常に大きな問題ですし、この中にもあるように品川区は全国でも自殺率が高い自治体であるというふうに指摘もされておりますので、質問させていただきました。減らす方向で今後も施策を展開されることを期待して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私も自殺対策の基本理念が「いのちの『わ！』しながわ」というのは、これも本当にちょっとどうなんだろうというのをまず思ったし、自殺対策のところで公助、共助、自助という考え方で取り組むというのが、これでいいのかという思いがしたのです。ここを見ると、ライフリンクの清水さんの講演を聞いているわけではないですか。それが１つです。そしてまた、それをどうやったら救えるのか。何かあれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-070"},{"speaker":"渡部委員","kind":"質問・要望","question":"「『わ！実際、では、これをやったからといって、品川区が自殺者を絶対なくすのだと言い切れるかというと、僕は言い切れるものではなくて、行政ができる範囲で最大限のことをやるし、地域の人にもこういうふうにやっていただきたいというのが、これで僕はいいと思うのだけれど、考え方が違ったら違いますよと言ってほしいし、そうですよというのだったらそうですよとぜひ言ってほしいです。","respondent":"鷹箸保健予防課長","answer":"自助については、先ほどの鈴木ひろ子委員のご質問ですけれど、例えば３２ページの区民一人ひとりが取り組めることとして、悩みを抱え込まないで相談するとか、相談窓口を知るとか。","voiceIndex":179,"id":"exchange-071"},{"speaker":"渡部委員","kind":"意見","question":"その中で当然原因も探しているし、警察などさまざまなところとの協力の中でやっていきますけれど、では、そこに外野がどう入る、外野というか周りがどう絡めるか。そのような中で、どうやって行政や地域がかかわっていくかということを、指針として、品川区の考え方として出すのは、僕はこれはこれでとてもいいことだと思いますし、これ以上のことはなかなか難しいのかなと。すみません。長くなりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":181,"id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"お互いにそういうことはこういうふうにやったらいいんじゃないの、自分でもこういうふうに努力することが必要だよというのでなくて、追い込まれている人に対してもっとやさしく支援するという中身のものにしていただきたい。追い込まれるその原因をどうやってなくしていくか。自殺しなくてもいい社会を、地域をどうつくるかということが一番大事だと思うのです。","respondent":"鷹箸保健予防課長","answer":"今の鈴木ひろ子委員のご説明で大変よくわかりました。自助という言葉に対して、我々はそういうイメージを持って使っていなかったので、みずからと周りに対して自己責任などというつもりは全くありませんでした。","voiceIndex":182,"id":"exchange-073"},{"speaker":"西村委員","kind":"質問・要望","question":"すみません。今の鈴木ひろ子委員の意見と重なってしまうのですが、公助、共助、自助という言葉は、よく防災のときに使うかなと考えています。これだけ悩んでいる方たちがいる中で、どこに相談すればいいのかとか、関係機関、地域が取り組めることにつながっていくのかというのが、もう少し見えるように周知をしていただいたり記載していただきたいなと思いますが、いかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"４８ページの中高年女性の支援については先ほどもご説明したところですが、確かにここは重点施策として取り上げているのですが、具体的な支援策について、この素案をまとめるまでの間にはちょっとこれ以上取り組めずに。","voiceIndex":185,"id":"exchange-074"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ですので、やはりこの計画には、そうした自殺者を生み出さない地域や社会をつくってほしいという当事者の皆さんの願いでつくられた、ようやくできましたということも言われていましたので、そういうもとでの計画だと思います。相談できないというのが６２.６％あるのです。ですので、やはりこうした調査もしながら、対策を、計画をつくっていくべきではないかなと思うのですが、いかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"自殺に特化した、区民を対象としたアンケートは、品川区で現在のところまだ実施していないので、簡単に比較することはできませんし、自殺を考えた方でないとそのアンケートができないということもあるので、今後のアンケートの必要性については。","voiceIndex":188,"id":"exchange-075"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"やはり自殺念慮、自殺を考えるという方が、性的マイノリティーの方には多いと思いますので、そうした部分もぜひ書き込んでいただきたいなと思います。貧困と格差を拡大してきた経済政策や社会保障や医療の改悪をやめて、全ての国民が憲法２５条の健康で文化的な最低限の生活を営む。ですので、そうした今の政治がつくり出してしまっている現状というのに対して、区の認識はいかがでしょう。","respondent":"鷹箸保健予防課長","answer":"冒頭にご指摘いただきました性的マイノリティーについては、そういったご事情を抱えた方がさまざまな生きづらさを抱えているということについては、事務局としては十分認識しております。","voiceIndex":190,"id":"exchange-076"}]},{"id":"topic-08","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっとそのところを教えていただきたいのですが。すくすく赤ちゃん訪問事業というのは、生後４か月未満の赤ちゃんが対象です。これは、はがきを健康課へお送りくださいということでありますが、はがきを出した方だけということなのでしょうか。訪問される割合というのはどれくらいになっているのか、教えていただきたいです。ちょっとその点を教えていただきたいと思います。","respondent":"仁平品川保健センター所長","answer":"このネウボラネットワークの考え方的には、あらゆる機会を捉えて相談・面談を行って支援を行っていくという形になっておりますので、大きく捉えれば、ネウボラネットワークの中の一つの事業と言えるかもしれません。","voiceIndex":199,"id":"exchange-077"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうふうにかなりのリスクを抱えた方というのは、本当にこれから児相もつくっていくのに当たって、いろいろと連携してフォローしなくてはいけないという部分なのかなと思いました。そういう点では、病院としても、そのまま受け入れざるを得なくて、受け入れて出産する場合もあるというのも聞いていますが、必ず病院からは連絡が来る、ほとんど来るということで捉えていいかということだけ確認をします。","respondent":"仁平品川保健センター所長","answer":"区としては、なるべく訪問を受け入れていただきたいと思っているのですが、出生通知にも書いてはあるのですけれども、やはり伺いますと、２人目、３人目なので、もう区から得る情報もないということで。","voiceIndex":201,"id":"exchange-078"},{"speaker":"あべ委員","kind":"確認","question":"絞って伺います。ネウボラネットワーク、いろいろ伺いたいこともあるのですが、まずはこういうものができてよかったなと考えています。それから、要支援が複数あるとそれもハイリスクになるのかなと思いますが、そういう捉え方はされていますでしょうか。これが１点です。もう一つ、一応確認です。その方も漏れなく把握されていると考えてよろしいですよね。","respondent":"仁平品川保健センター所長","answer":"要支援が複数あった場合にハイリスクというのは、余りがちがちには考えておりません。要支援以上に、これはフォローに入らなくてはいけないという場合には、ハイリスクという扱いをする場合もあります。途中で変わるのかというお話です。","voiceIndex":204,"id":"exchange-079"},{"speaker":"あべ委員","kind":"確認","question":"何かの事業を申し込まないと変化がわからないというのではなくて、そこの見通しがつく項目も幾つかあると思うので、それについては出産から時間を経たずに、やはり状況の変化がないか確認するということもぜひやっていただければと思うのですが、いかがでしょうか。","respondent":"仁平品川保健センター所長","answer":"状況の確認です。出生通知を出す方については、訪問の受け入れの段取りを決めて対応してまいります。それ以外に先ほどお話しさせていただきましたが、出生通知のない方は架電をいたします。","voiceIndex":206,"id":"exchange-080"},{"speaker":"あべ委員","kind":"提案","question":"ドゥーラなども２０時間、４０時間と増やしていただいているわけですが、それも例えば訪問される保健師などの判断で個別に増やすこともできないだろうかというふうに、これは提案にとどめておきますが、そうした形で、相談だけではない、具体的なサービスというのも必要に応じて柔軟に提供できるようにしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":208,"id":"exchange-081"},{"speaker":"西村委員","kind":"質問・要望","question":"ドゥーラについて伺いたいのですが、しながわサポートプランの中にドゥーラの説明があるのかなと思いまして、一文でもあるのかなと思ったのですが、見落としていたらすみません。教えてください。お母さんたちから、ホームページが大変見づらいという声が届いております。なかなか予約をとるまで気が回りませんので、もう少し予約がとりやすいような改善をお願いしたいと思いますが、いかがでしょうか。","respondent":"仁平品川保健センター所長","answer":"日帰りですが、こちらも今現在実施場所が１カ所でして、非常に利用希望の方が多く、月の上旬には大体その月の予約が埋まってしまうような現状になっております。","voiceIndex":210,"id":"exchange-082"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3548#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":91106,"voices":214}},{"id":"r01-20191111-8","meetingId":"r01-cm11","date":"2019年11月11日","dateIso":"2019-11-11","committee":"建設委員会","time":"午後 １時００分～午後 ５時００分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"今の最後のステップのことなのですけれども、ステップ２の日程というか、大体どれぐらいの時期なのかというのを教えてください。","respondent":"鈴木都市計画課長","answer":"ステップ１の区内を地域分けして点数で効果的な地域を見て評価していくというところを現在いろいろ日程調整していますが、１２月には第２回目検討会の中でステップ１の地域の評価というところをご議論いただく予定です。","voiceIndex":6,"id":"exchange-001"},{"speaker":"たけうち委員","kind":"意見","question":"陳情としていろいろな地域の方からいろいろなご希望が出てきて、我々も、全部が全部細かく地域を知っているわけではないのですが、やはりそういうことはあるだろうなとは思いながらも、ただほかの地域においてもそれぞれの方がそれぞれのご事情の中で不便さを感じているという中で、今品川区でも一生懸命こういう形で地域の選定をこれからやられるということですので、しっかり見守っていきたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-002"},{"speaker":"吉田委員","kind":"質問・要望","question":"今の質疑の中で、結局ステップ１の地域の評価の中である程度地域が絞られてしまうということなのでしょうかというのが１点と、それから、前回の陳情を審査したときに、本当にさまざまな地域の方たちがコミュニティバスを求められていて、それは当然の願いだと思うのですけれども、コースを幾つか決めていくということについては、この検討会とか区の中でやるだけでなく、また個別に意見を聞くだけではなく。","respondent":"鈴木都市計画課長","answer":"このステップ１から２なのか、あるいは２から３の段階なのか、ちょっと今検討中ですが、地域の方々にお声を聞く場は、しっかり議論していただく場は設けようと思いますが、区内全体、全域で一堂に会してというのはなかなか難しいかなという考えで今検討している状況で。","voiceIndex":9,"id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはりほかの地域の状況も知るというような場面はぜひ必要なのではないかなと思いますが、何か工夫、今ほかの自治体でも、この間もご紹介しましたけれども、住民協議会というような形で無作為抽出の人たちに集まっていただいて、いろいろなテーマを設定して議論をしているというような仕組みも既に採用している自治体もありますし、もちろん最終決定は議会であり、品川区であるわけですけれども。","respondent":"鈴木都市計画課長","answer":"ただ、やはり地域に愛され、品川区民の方に愛されて乗っていただくと、利用していただくという意味では、地域の声を聞くというのは大事ですので、そうした意味では、今回無作為ですが、アンケート結果ですとか、そうした区民の声の反映の仕方をしっかり用いながら。","voiceIndex":11,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"今はできないというふうにおっしゃっていますけれども、これからステップを幾つか踏まないといけないわけですから、その中でできるだけお互いの地域の人たちが理解し合えるような仕掛けというのもぜひ検討していただきたいと思います。これは要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"前回もちょっと伺ったのですけれども、アンケートは１,０９４票ですか、世帯でみればもう少し少なくて８１１通ということで、この地域別内訳についても伺ったのですけれども、満遍なくという話もありましたけれども、具体的に例えば２５ページの右に、地域別にニーズがどうあるかという分析をされているわけですけれども、それぞれの地域の回答数の内訳について改めて伺いたいのですけれども。","respondent":"鈴木都市計画課長","answer":"アンケート結果のホームページ等での公表ですが、第１回の地域交通検討会の資料は既にホームページ上でも公表しています。","voiceIndex":14,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、何といいますか、ちょっと何でこういうのを伺うかといいますと、その地域にお住まいの方々のニーズをどうルート検討に反映させていくかというのが大事だと思うのですね。回答数が幾つかというのをお伺いしたいと思います。生活実感から来る要望だと思うのですけれども、この三つの地域について、区は現時点でどのような分析をされているのか伺いたいなと、それぞれ伺いたいなと思います。","respondent":"鈴木都市計画課長","answer":"陳情いただいた八潮ですとか西品川ですとか北品川等々の区としての認識ですが、それぞれの地域といいますか、今こういう品川区内全体のアンケート結果ですとか、あるいはバスの勢力圏の話ですとか、あるいは区民の移動データ等々の整理をしているところでございまして。","voiceIndex":16,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"よろしくお願いしたいと思います。こういった具体的なニーズというのは、今後の検討や試行ルート選定の検討などに当然反映すべきだと私は思うのですけれども、アンケートやこれから実際に新たに行っていく地域のニーズの把握に加えて、こういった陳情で寄せられた具体的な声をぜひ受けとめていただいて、検討に反映していただきたいと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"これはある程度地方の都市のように、そうした施設が１カ所に集約しているような形であれば、そうしたバスルートもあると思いますが、品川区内には、公共施設のほうもバランスよく点在していますし、そうした意味で。","voiceIndex":18,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、いろいろな要求を反映していったら、多種多様な要求は全部反映しきれないというのは、それはそういうのはあるかもしれませんけれども、まずはそういう切実なところから始めて、それを十分に検証していって、いろいろな地域に反映して広げていっていただきたいといいますか、それがやはりコミュニティバスでやる以上、住民の方々が求めていることですし、移動・外出の支援、そして移動の権利。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-009"},{"speaker":"松本委員","kind":"意見","question":"一つのルートを選択してということだと思うのですけれども、ほかの自治体を見てみますと、例えば五つとか六つとかでまずやってみて、基準を満たさなかったら廃止とか、あるいはいろいろ見ていると、運行ルートも変わるみたいなことがよくあるようなのですけれども、１回実証実験をやってからの流動性というか、どのくらいそのあたりのニーズが、１回やってみて、変わってくるニーズもあると思いますし。","respondent":"鈴木都市計画課長","answer":"試行運行して、これはしっかり本格実施していって大丈夫だとか、あるいはさらにちょっとこういった視点を加えて本格実施していきましょうとか、やはり中身的には本格実施をするには、非常に効率がいい、あるいは効率的ではないとか。","voiceIndex":21,"id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"本日結論を出してください。不採択でお願いします。理由を述べますが、地域交通検討会ですか、この検討会も既に立ち上げられて、８月に行われました。この検討会で、まさに今私たちがこの委員会で議論した内容を行っているところでありまして、この入れる、入れない、そしてまた後の陳情にもかかわってくることですけれども、この委員会で一定程度の方向性を見出す、方向性を出すべきではないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本日結論を出すということでお願いをします。事業者も検討会に入っていて、ここら辺のところを伺うと、その話ももちろん議論をしていきますというご回答もいただいているわけでありますから、そういう今ある既存の路線バスの再編、それからコミュニティバス、そういうことも踏まえてしっかりそこは点数化、効率的、公正に、いろいろな形で議論していただいて、一定の方向を出していっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-012"},{"speaker":"たけうち委員","kind":"確認","question":"理由については、先ほど確認したとおり１２月末、１２月中には一定程度地域が絞り込まれていく中で、いろいろな地域からのご意見が出ている、これについては一つ一つを決して否定するわけではございませんが、今後こうした地域も含めてさまざまな地域の絞り込みをやっていく中で、先ほど来あるとおり委員会でこれを採択してしまうと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回議会のほうに具体的に各地域から出ているわけですけれども、まさに議会としてはそういう地域から上げられた要望というのを真摯に検討して、こういった要望があるのだということを一定議会として判断していくといいますか、それはまさに議会の私はやるべき仕事だと考えていますので、内容についても地域の声が反映している切実なものだと思いますので、私はこれを採択すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-014"},{"speaker":"吉田委員","kind":"意見","question":"生活者ネットワークとしては、趣旨採択を主張したいと思います。この検討会が始まっているにもかかわらず、やはりこういう陳情がたくさん出てくるということは、そこに自分たちの地域の意見を反映してほしいということだというふうに理解します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-015"},{"speaker":"松本委員","kind":"意見","question":"本日結論を出すで、趣旨採択でお願いいたします。今いろいろな方がおっしゃられたとおりで、これを採択することによって予断が出るというところもありつつ、いろいろなご意見が出ていることについて何もしないというのも、これはちょっと私も明確に自分の中に結論が出ているところではないのですけれども、全く不採択というのもちょっと抵抗がありますので、趣旨採択ということでお願いできればと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"私としましては、ぜひ採択としたいのですけれども、いろいろ皆さんのご意見を聞く中で、やはり私は議会としてこういう地域から具体的なコミュニティバスに対する要望が上がっているということは、やはりしっかり受けとめる必要があると思います。それを反映するためにも私は採択をしたいのですけれども、少しでも反映させるために趣旨採択というお声も多いので、趣旨採択に変えさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-017"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、先ほどと同じ流れですので、趣旨採択を主張しますが、大変大事な内容が書かれていますので、ぜひその趣旨を検討に反映させていくべきだと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-018"},{"speaker":"吉田委員","kind":"意見","question":"本日結論を出すで、趣旨採択を主張いたします。理由は、先ほどと同じです。項目については、まさにこれから議論すべきです。ただ、この陳情の趣旨はぜひ採択として趣旨採択を主張したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-019"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、先ほどの議論を踏まえて趣旨採択を主張します。ぜひ今後の議論に反映すべき趣旨だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-020"}]},{"id":"topic-02","title":"大崎駅周辺地域および西五反田三丁目地区のまちづくり","agenda":"大崎駅周辺地域および西五反田三丁目地区のまちづくり","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"改めてかなり多くの再開発等の計画がめじろ押しだなということを感じましたけれども、大崎駅周辺地区のまちづくりの区の推進体制はどうなのでしょうか。担当職員というのは何人いるのでしょうか。担当区域として、資料に目黒、五反田、大崎と出ていますけれども、これはひとくくりで担当しているという感じなのでしょうか伺いたいというのがまず１点です。","respondent":"稲田都市開発課長","answer":"大崎駅周辺地域は、この都市再生緊急整備地域に指定されまして、緊急的にまちづくりをしっかりと進めていくという国の方針に従いながら指定されたものでございまして、それに従いながら現在もこの地域周辺等々のまちづくり、再開発等々をやってきているです。","voiceIndex":74,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"先ほど言いましたように、案をつくる段階でしっかりと周辺の住民の方の声を入れませんと、風害、日照、インフラ、防災等々、建物が与える影響が余りにも甚大なので、私はまさに公聴会を開催する必要があるというふうに思うのですけれども、今回のこの東五反田二丁目第３地区でその必要があると私は思うし、それを認めるべきだと思うし、公聴会を開催する考えがあるのか伺いたいなと思います。","respondent":"稲田都市開発課長","answer":"都市再生緊急整備地域の具体的な緩和というふうに申されていますけれども、これはこのような国の制度の中で指定されているというところで、優先的ではないのですけれども、そのような地域だというところで、東京都も認識しながら進められているものでございまして。","voiceIndex":76,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"ここで１点だけ確認したいのは、先ほど公告縦覧の話がありました。続けて、２の東五反田二丁目第４地区についても伺いますが、これは「東京都マンション再生まちづくり制度を活用し」とありますけれども、これはどんな制度なのでしょうか。区内のほかの活用事例があるのでしょうか。区として今後この制度の活用を進めていくという考えなのかどうか伺います。","respondent":"稲田都市開発課長","answer":"都市計画法第１６条の説明会ですが、これは先ほども言いましたけれども、権利者の方にしっかりと理解してもらうということで開くものです。公告縦覧に関しましても、権利者の皆様方を対象に行っているものです。","voiceIndex":78,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"８とＪＲについてもちょっとお伺いしますが、この８の大崎駅東口第４地区ですけれども、地元まちづくり連絡会という話もありましたけれども、ちょっとよくわからなかったので、これはどういう連絡会なのか。この連絡会の中にＪＲは入っているのでしょうか、伺いたいと思います。大崎駅東口第４地区の西側のほうの再開発準備組合、もしくは協力企業にＪＲ東日本は入っているのかどうか、これも伺います。","respondent":"稲田都市開発課長","answer":"そういう中におきましては、地域として一つで考えていかないといけないだろうというところで区も入りまして、東西両方の連絡会をつくって、しっかりとまちづくりに対応していこうかというふうに進めてきているものです。","voiceIndex":80,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"８のところはちょっと細かくて申しわけないのですけれども、事務事業概要では緑一色に塗られていたのですが、この資料では先ほど課長がおっしゃったように３棟のマンションの区域の色が抜かれているのですけれども、その理由というのですかね、何か状況の変化でもあったのかというのをちょっと細かいのですが、お伺いしたいと思います。主にどういう方がいらっしゃるのかというのを伺います。","respondent":"稲田都市開発課長","answer":"大崎駅東口第４地区は、事務事業概要では、おっしゃるとおりべったり塗ってあるところです。大崎駅東口第４地区の地域としては、新しいビルも含んだ形でのエリアというふうには考えているというところですが、実際の再開発準備組合は東側と西側に分かれるというところです。","voiceIndex":82,"id":"exchange-025"},{"speaker":"安藤委員","kind":"意見","question":"ですので、こうしたまちづくりの転換を私はすべきだと思うし、住民参加のまちづくりと環境にも持続可能な、そうしたまちづくりの転換を進めるべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":84,"id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"さまざまなこれらの再開発の中で、これは必ず区のいろいろなほかのインフラサービスとかに影響するものだと思うのです。そういうようなことを、区としてはあくまで要望しか出せないものかもしれませんけれども、そういうことはどの段階で、どういうふうになっていくのか、ぜひ教えていただきたいと思います。","respondent":"稲田都市開発課長","answer":"事前の詳細な設計に入る前、あるいは準備組合とかで検討されるときには区の担当者も行っておりますので、こういう点がチェックポイントだよというようなことで話し合いもされながら進めているという状況です。","voiceIndex":85,"id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"もう１個が、説明会のことなのですけれども、さまざまな立場の意見を聞いてほしいというのは生活者ネットワークとしても求めておりますが、別に反対とか賛成とかではなく、自分たちは必ず影響を受けるのに、何でその説明が、説明というか、情報の開示が遅いのかというご意見がある。求められないのだったら、区がかわりにそれをやるということはないのか、その辺についても伺いたいと思います。","respondent":"稲田都市開発課長","answer":"区のほうとしても、そういう説明をやってくださいよというような話はしてきておりますので、そういう形で今までもやってきましたし、これからもやっていきたいというふうに考えております。","voiceIndex":87,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"一定の基準にのっとってやってらっしゃるというふうには思うのですけれども、結果としてそれが何か説明が足りないというふうに見えるのが現状なのだと思います。基本的にはやはり今住んでいる方たちの意見が反映されるようなまちづくりであってほしいし、情報開示はなるべく早くしていただきたいと、最後は要望にさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-029"}]},{"id":"topic-03","title":"東京港青海ふ頭（江東区）における「ヒアリ」の確認","agenda":"東京港青海ふ頭（江東区）における「ヒアリ」の確認","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"国と都による青海ふ頭およびその周辺との追加調査等が予定されているというふうな今後についての説明がありましたけれども、八潮をはじめ、品川区でも追加の調査の要望を出すべきだと思うのですけれども、いかがでしょうか。","respondent":"小林環境課長","answer":"２点目の「ストップ・ザ・ヒアリ」という環境省がつくりましたパンフレットですが、委員ご指摘のように非常にわかりやすいパンフレットというふうに区としても認識しています。","voiceIndex":94,"id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"ぜひこういう事態があるのだということを知っていただくためにも周知のほうは引き続きよろしくお願いしたいと思います。それと、八潮は対岸ですからちょっと気になると思うのですけれども、半径２kmにこだわらずということもあったので、環境課としては品川区全域を見渡して、ちょっとそういう被害というのですか、拡散というのですか、そういった危険性についてはどのように認識をされているのか伺います。","respondent":"小林環境課長","answer":"先ほど申し上げましたように、区内で発見された大井ふ頭につきましても、今まで国のほうでしっかり調査を行ったところですが、今後につきましても、国や都と情報交換しながら区として必要な場所があれば。","voiceIndex":96,"id":"exchange-031"}]},{"id":"topic-04","title":"「資源・ごみの分け方・出し方」の配布および年末年始のごみ収集","agenda":"「資源・ごみの分け方・出し方」の配布および年末年始のごみ収集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"３点お伺いします。外国語版の活用方法はどんな感じなのかというのを伺います。２点目は、この目的が分別行動の促進、ごみ減量とありますけれども、ちょっと改めて現在の区のごみの減量の目標はどうなっていましたか、伺いたいと思います。どのようにそちらのほうはこういったパンフレットだとか周知を強めていくお考えなのか、３点目として伺いします。","respondent":"工藤品川区清掃事務所長","answer":"そういった意味では、１人当たりのごみ量、１日当たりのごみ量という部分を把握しておりまして、それを前年よりも削減していくという取り組みをしています。３点目です。排出抑制の取り組みです。","voiceIndex":104,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"私としてはちょっと目標をどこにするかというのは置いておいても、前年度に比べるとこれぐらい減らすという議論があってもいいのかなというふうに考えているのですけれども、区として現在としては先ほどの１人当たり、１日当たりで前年よりも減らしていくという目標にされているというのは何か理由があるのか、それだけお伺いします。","respondent":"工藤品川区清掃事務所長","answer":"減量目標値という部分におきましては、今ちょうど私ども第３次となる一般廃棄物処理基本計画を策定しておりまして、そちらのほうをもってしっかりと数字等を管理しているです。今後発生抑制という部分、ごみ減量という部分をしっかりとしてまいりたいというふうに考えております。","voiceIndex":106,"id":"exchange-033"}]},{"id":"topic-05","title":"五反田水辺が結ぶプロジェクト 五反田リバーステーションオープニング記念式典","agenda":"五反田水辺が結ぶプロジェクト 五反田リバーステーションオープニング記念式典","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２点お伺いしますけれども、１４日にオープニング記念式典ということなのですが、その後、五反田リバーステーションの具体的な活用や事業展開というのはどんなふうになっているのか改めてお伺いします。２点目は、桟橋の災害時の活用という説明をしてきたと思いますけれども、そちらについてはどのような検討が行われているのかお伺いします。","respondent":"松本河川下水道課長","answer":"災害時につきましては、東京都の防災船着場に指定されていることから、災害時にはそういった活用も考えているところです。","voiceIndex":115,"id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"質問","question":"２点伺います。１点目は、これができて非常に期待しています。社会実験とか東京２０２０大会時の活用とか、それは考えられていると思うのだけれども、ここを起点にすると、２点間の問題とか、いろいろな話があるのをどうクリアするのかというお考えを持っていらっしゃるのか。それからもう一点は、水上タクシー等のこともこれから必ず出てくる。","respondent":"松本河川下水道課長","answer":"あわせて、仕掛けですが、こちらにつきましてもいろいろあろうかと思います。先ほども言いましたように、文化観光課も含めまして、いろいろな課と対応しながらいろいろ仕掛けていきたいなというふうに考えているところです。","voiceIndex":119,"id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"一つだけ要望しておきます。五反田ふれあい水辺広場のところは、今、いろいろプロポーザル等されていると思っていますけれども、私はそれではなかなかうまくいかないような気がしてなりません。そこら辺のところも含めて、ぜひより良い活用ができるようにお願いだけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-036"}]},{"id":"topic-06","title":"水辺のライトアップ（かもめ橋）","agenda":"水辺のライトアップ（かもめ橋）","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"２点確認なのですが、ライトアップは期間限定なのでしょうか。それと、工事請負契約で総務委員会においてというお話でしたが、年間のランニングコストはどれくらいなのか、あと、整備工事の費用は幾らだったのかお伺いします。","respondent":"松本河川下水道課長","answer":"あわせて、まだ試算ベースですが、年間９０万円ほどかかる予定としております。最後に、整備工事費ですが、こちらは起工額が１億２,９４０万５,０００円に対しまして、落札額が１億２,５４０万円となっております。","voiceIndex":126,"id":"exchange-037"}]},{"id":"topic-07","title":"台風第１９号（１０月１１日～１３日）における対応について、および(7)台風第２１号と低気圧の影響による大雨（１０月２５日）における対応","agenda":"台風第１９号（１０月１１日～１３日）における対応について、および(7)台風第２１号と低気圧の影響による大雨（１０月２５日）における対応","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"自主避難施設と高潮だとか土砂災害の場合の避難場所、この名称というのですか、この違いと運営体制にも違いはあるのでしょうか。","respondent":"中島防災課長","answer":"一方、避難準備・高齢者等避難開始あるいは避難勧告などに基づきまして開設するのが、正確に言いますと、指定緊急避難場所というものでございまして、あくまで災害が発生するおそれがある場合に、避難場所として区が開設をするものです。","voiceIndex":132,"id":"exchange-038"},{"speaker":"たけうち委員","kind":"質問","question":"なぜそういう質問をするかというと、今回施設によっては１００名近い方が来られて、マンパワーの問題で、誘導や案内等についていろいろな課題があったとか、そういうお声も聞いている中で、施設によっては地域の町会長とか住民の方が心配されて、やはり地元ですのでよく知っているから、いろいろなことでご協力したいのだけれども、そこに来ている職員の方もおそらく遠慮されてというか。","respondent":"中島防災課長","answer":"とはいっても、実際に避難をされてこられた方々に連携というかご理解をいただきながら、そういう避難場所の運営というのは可能な面もあろうかと思いますので、そのあたりは今後あり方を考える中で、どういう形がいいのか、ちょっと今の段階ではわかりませんけれども。","voiceIndex":134,"id":"exchange-039"},{"speaker":"たけうち委員","kind":"質問・要望","question":"たしかに、そんなときになぜ私たちがという方もいらっしゃるかもしれないし、いや、もっと私たちを入れてやったほうが、来た方は顔を知っているのだから安心するのだからというところもあったと思うのです。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-040"},{"speaker":"松本委員","kind":"質問","question":"今ちょっと自主避難所の話が出たので少しお伺いしたいのですけれども、この自主避難所というのは、いろいろホームページを今回実際に見たのですけれども、ちょっとお話も出ていましたが、災害基本対策法という法律的な根拠がある避難所と違って、ある意味任意的にやられているということなのだと思います。","respondent":"中島防災課長","answer":"ただ、それが十分伝わっているかは、自主避難施設そのものがまだおそらくほかの区も含めて開設例も少ないところですので、そのあたりのところは、基準もさることながら、しっかりと周知に努めていきたいと考えています。","voiceIndex":137,"id":"exchange-041"},{"speaker":"松本委員","kind":"質問","question":"自主避難所の周知はそれでお願いできればと思います。一つやり方としてはツイッターとかで発信していただけると、これは満杯になったというよりも、今どのくらい充足率があるかということも、区でやるのは難しいかもしれないですけれども、ある程度やっていただくのもいいのではないかなというふうに思いますが、いかがでしょうか。","respondent":"中島防災課長","answer":"確かに今回は定員がいっぱいになるということはなかったのですが、ほかの区の事例も今回いろいろ教訓がございまして、そういう中で、やはり早い情報開示、定員になる前に情報開示していくことの必要性を感じておりますので。","voiceIndex":139,"id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"たしか電話でちょっと伺ったら、１％ぐらいしかいっぱいになっていなかったみたいな話もあるみたいなので、この調節池にどのくらい入っていたのかというところと、あと、これをむしろ開示して、水位の状態も開示していただけると助かるのかなと思いますが、いかがでしょうか。","respondent":"中島防災課長","answer":"目黒川に関しましては、荏原調整池が２０万m3入るということで、現状避難準備の水位といたしましては５万m3で、さらに水位の上昇が見込まれる場合になります。確かに今回そこまで至らなくて、２,０００m3ぐらいの水量が荏原調整池に入っていた。","voiceIndex":141,"id":"exchange-043"},{"speaker":"大沢委員","kind":"質問","question":"自主避難施設ということで、先ほどほかはあまりまだ行われていないということですけれども、これに関しては、行政サービスの一環であるということでお話をいただきました。この部分で、開設の手引きというか開設のマニュアルみたいなものというのはあるのでしょうか。何を判断しながら、どんな基準をもって判断をし、開設に至るのか何か明確な決まりとかマニュアルのようなものはあるのでしょうか。","respondent":"中島防災課長","answer":"基準というよりもまだ実際の台風の進路等を見まして、判断をさせていただいているです。","voiceIndex":143,"id":"exchange-044"},{"speaker":"大沢委員","kind":"質問","question":"先ほどのご答弁の中で、近隣の方、地域の方からの声を聞いて自主避難施設を開設したというお話がありましたが、今のご答弁と若干矛盾するようなところがあると思いますけれども、いかがでしょうか。","respondent":"中島防災課長","answer":"ちょっと私のほうの説明が悪かったかもしれないのですが、地域の声につきましては、自主避難施設の運営の際に、いろいろと現場でのお声を聞きながらということで、ちょっとお話をさせていただいたというつもりでございまして。","voiceIndex":145,"id":"exchange-045"},{"speaker":"大沢委員","kind":"質問","question":"あくまでも気象情報等々の情報を入手し、これを開設していくということであって、地域の方の声を吸い上げるというようなことは、物理的とか時間的状況を見ても、地域の方にとても余裕があるとは思えないので、ちょっとこのような質問をさせていただいたのですけれども、区のほうで判断をされて自主避難施設、これは５カ所ということですけれども、小中一貫校に開設されていますけれども。","respondent":"中島防災課長","answer":"今回開設しました５校の義務教育学校につきましては、同じ時間に開設させていただきました。同じ自主避難施設を翌日の８時３０分にシルバーセンターにも開設させていただきまして、そちらのほうでも今回対応させていただきました。","voiceIndex":147,"id":"exchange-046"},{"speaker":"大沢委員","kind":"質問・要望","question":"行政サービスの一環ということでありますから、やはり場所によって開設時期がばらつくとか、行政サービスであるがゆえに均一化したサービス提供のタイミングとかというのが必要だと思うので、そこのところをきちんと意識されながら運営をしていっていただきたいのですけれども、どのようにお感じになりますでしょうか。","respondent":"中島防災課長","answer":"運営につきましては、しっかりマニュアルを作成しまして、あまりマニュアルに頼り過ぎてもよくないのですが、やはり均一的な、標準的な対応が少なくともできるように配慮していきたいと思います。","voiceIndex":149,"id":"exchange-047"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけ。こういうことは、次、また次と来ると思っています。そういう対応があるとやはりあれなので、そこは行政側がまず間違って来ているのだけれども、それをきちんとそこへ誘導する、そういうところまでやってくださいということが、それは先生なのか用務の方かは別としても、そういう連携は必ず図っておいてもらいたいと思うのですけれども、そこら辺のところでお考えがあれば教えていただきたい。","respondent":"中島防災課長","answer":"今回災害対策本部ということで、所管を問わず全庁を挙げて取り組みをしていますので、しっかりとそういう情報共有、学校の教員でありますとか、教職員とも認識いたしまして、きちんとした案内、誘導等ができるように努めてまいりたいと思います。","voiceIndex":151,"id":"exchange-048"},{"speaker":"高橋（伸）副委員長","kind":"質問","question":"台風第１９号のときに、避難開始と避難勧告が２回発令されていると思うのです。今回そういうことがあったのかどうかお聞きしたいと思います。","respondent":"中島防災課長","answer":"災害対策本部のほうに今何を放送したのかという問い合わせはいただいております。その都度内容についてお伝えをしていますが、やはりスピーカーで音声を流した後に一定程度そういうお問い合わせがあったということは確認しています。","voiceIndex":153,"id":"exchange-049"},{"speaker":"高橋（伸）副委員長","kind":"質問","question":"私の自宅の目の前にも子局があるのです。なので、職員の方がそのときの対応で男性なのか女性なのかはあると思うのですけれども、どういうふうにアナウンスをしなさいという指示をしているのかどうかということをお聞きしたいと思います。","respondent":"中島防災課長","answer":"しゃべるスピードなども調整できる機能もありますので、スピードをゆっくりにしているところではあるのですけれども、いま一度放送のスピードなども含めてよりよい伝達法を確認させていただきたいと思います。","voiceIndex":155,"id":"exchange-050"},{"speaker":"吉田委員","kind":"質問・要望","question":"台風第１９号は１２日になってから、８時に警戒レベル３で避難準備・高齢者等避難開始発令ということなのですが、この高齢者等避難開始の発令の仕方というのを確認させていただきたいと思います。品川区の場合どうしたかというよりも、どの程度そういうふうに、なかなか発令をしても避難の行動に移らないというような方たちに対して、何か考えていらっしゃることがあったら伺いたいと思います。","respondent":"中島防災課長","answer":"ただ、そういうツールだけではなかなか難しいので、区としましては、広報車を回したり、そういう形の呼びかけも補完して行っているところです。","voiceIndex":157,"id":"exchange-051"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ検討していただきたいと思います。大変だと思いますけれども、ぜひご検討いただければと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":159,"id":"exchange-052"},{"speaker":"安藤委員","kind":"質問・要望","question":"１８カ所は最終的にどこが開設されて、５８４名の方というのは、どういうふうな人数だったのかというのがわかるように資料を提供していただく必要があるのではないかと思うのですけれども、ちょっと答えられる範囲で答えていただきたいのと、資料的にはぜひ出せないかということを委員長にお願いしたいと思うのですね。それが１点目です。","respondent":"中島防災課長、あくつ委員長","answer":"１８カ所の施設で避難者が５８４人とご説明させていただきまして、資料の提供については検討……。資料の要求については、委員会で諮ることになっているのですが、特に支障がなければ、今お答えしていただいてもいいかと。シルバーセンターにつきましては、先ほどちょっと答弁が説明不足だったかもしれませんが。","voiceIndex":160,"id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後に１点、避難所の場所なのですけれども、浸水や高潮のハザードマップの浸水想定区域内に立地してしまっているのが、少なくとも私が気づいたのは日野学園と南大井シルバーセンターもそうなのではないかなと思うのですけれども、ここについては一定こういった台風や水害の際の避難先として再検討が必要なのではないかと思うのですけれども、区のお考えはいかがでしょうか。","respondent":"中島防災課長","answer":"実際雨の降り方等も見ながら基本的にはその場で高いところに避難をしたり、あとは万が一浸水のおそれがあるような場合は、早い段階でさまざまな手段を用いましてほかの近くの避難場所への移送等も行っていく必要があるというふうに考えております。","voiceIndex":164,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"避難した場所がいっぱいだったり、あるいはそこが浸水してしまったり、浸水のおそれがあったりとかいうことで、また違うところに避難するというようなこともほかの自治体などではあったというふうに伺います。そういったことで、そこも含めて今回のことというのを本区に限らず、他自治体の事例も参考にしながら検討していっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-055"}]},{"id":"topic-08","title":"令和元年度 区内一斉防災訓練の実施","agenda":"令和元年度 区内一斉防災訓練の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"災害対策本部運営訓練のことなのですけれども、区民避難所との連携、物資等の輸送とありますけれども、具体的にどのような訓練を行うのか教えてください。","respondent":"大森災害対策担当課長","answer":"その参集職員が防災区民組織の避難所の受け付け等をやっていただく方と連携しまして、学校のほうに被災者の情報等を入力するようなシステム等がありますので、そういったところで被災者情報等を入力、また避難所等で不足する物資等、そういった情報を入力、それから無線。","voiceIndex":171,"id":"exchange-056"},{"speaker":"安藤委員","kind":"質問","question":"それとも訓練なので、その一部の方に来てもらうということなのでしょうか、年に１回ということなので、そういう意味では極力全ての参集を予定されている方に参集していただくというのは私は重要な訓練だと思っているのですけれども、いかがでしょうか。","respondent":"大森災害対策担当課長","answer":"訓練ですけれども、そういった形で平時から連携を図るようにしておりますので、その方々を中心としまして、参集動員計画で決まっている８名から１０名の方はもちろん区の災害本部の訓練ではなくて、それぞれの避難所のほうに行っていただいて、訓練に参加して。","voiceIndex":173,"id":"exchange-057"},{"speaker":"大沢委員","kind":"質問","question":"質問ではないのですけれども、表に「Ｒ元」と書いてある。「Ｒ元」というのは、令和元年だと思うが、ちょっとつり合いからするとおかしいので直してもらいたいのですが、どうですか。","respondent":"大森災害対策担当課長","answer":"大変失礼しました。ご指摘のとおり表現としてちょっとつり合いがとれない部分が項目としていますので、「令和元年度」という形で訂正をさせていただければと思います。","voiceIndex":176,"id":"exchange-058"}]},{"id":"topic-09","title":"本日は、まちづくりの進め方","agenda":"本日は、まちづくりの進め方","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料の３の地区計画位置図で、地区計画のさまざまな種類があるのですけれども、このそれぞれの違いというのですかね、ちょっとそちらをお伺いします。","respondent":"高梨木密整備推進課長、稲田都市開発課長","answer":"私からは、図で示されている地区計画の種類について説明をします。そのまちづくりの方針に従ってにぎわいや駅周辺の経済活動や、そういう拠点地区の目標等々がありますので、その辺を考えながら地域の皆様方、権利者の皆様方が、いろいろと検討していきます。","voiceIndex":183,"id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"ここについて今どのような仕組みになっているのか、区としてはそういった方々の意見というのを入れていくつもりがあるのか、私は入れていくべきだと思いますけれども、そこについてお考えをお伺いします。","respondent":"高梨木密整備推進課長","answer":"その周辺、区全体を含めた周辺の方々に対しては、その次の段階、地区計画の案となった段階で、こちらの趣旨の説明を行うことで意見をいただく場をつくり、そういった意見も取り入れながら、当該地区の地区計画についてはつくり上げていく。","voiceIndex":186,"id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"実態としては、素案で地区内の方が意見を出された、その後、案になって出てきて、案についての説明がされていますが、周辺地域の方の話を聞いても、それが実際に決定される段階では、ほぼ修正されないという実態がありますので、私は先ほど来申し上げているように、その地区内の権利者に大きな影響を及ぼすルールであったとしても、それがつくられた、でき上がった。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-061"},{"speaker":"たけうち委員","kind":"質問","question":"先ほど緑の誘導容積型地区計画は東八潮とおっしゃったのですけれども、地図を見ると大井三丁目かな、小さいところがあるのですけれども、この場所はどこですか。","respondent":"高梨木密整備推進課長","answer":"先ほど私の答弁に誤りがありますので修正をします。誘導容積型地区計画は東八潮のほか、大井一丁目だと思うのですが、こちらの地区計画でも定めがあります。","voiceIndex":189,"id":"exchange-062"},{"speaker":"たけうち委員","kind":"質問","question":"今、高いマンションが建てられていますか。一本橋のところですか。わかりました。以上で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":193,"id":"exchange-063"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"基本的に用途地域は今変更がないではないですか。大きい平米数のほうが、いざ売るとすると価値が下がってくる。そういうことということも踏まえると、議論をして地域の方から聞くときに、事務局として事実を言うのはいいのだけれども、そこら辺の周りの調査というのをぜひしてほしいと思うのだけれども、そこら辺の考えを教えていただきたい。","respondent":"高梨木密整備推進課長","answer":"例えば１１０m2の土地ですと宅地としては二分割できませんよといったところはお示ししているところなのですが、そのデメリットといったところについてまた協議会の中等でわかりやすくお示ししていきたいと、このように考えております。","voiceIndex":194,"id":"exchange-064"},{"speaker":"石田（秀）委員","kind":"質問","question":"例えば用途地域で僅少で４００m2でもいいけれども、８０m2の４００m2だとか、あるではないですか。そこら辺の延伸というのと、組み替えというのと、用途地域の条件より下がるというのかな、そこら辺のところの感覚というのは、それはまちの人がそうだったから、そうなったというのだけれども、そこら辺の両面をもう少し考えていただければなと思うのだけれども、それはどうお考えですか。","respondent":"高梨木密整備推進課長","answer":"例えば、公園の整備については大分進んできたので組み替えて、道路のところをやりたいですとか、そういったところについては、前例踏襲でずっと変わらないというわけでなくて、まちもどんどん年数がたてば状況も変わってまいりますので、そういったところを区としても把握し。","voiceIndex":196,"id":"exchange-065"},{"speaker":"石田（秀）委員","kind":"質問","question":"これで最後にします。ぜひそういうことを考えていただいて、いろいろなことがあるではないですか。そうすると、用途地域というのは、変えられないという理解でいいのかというのがあるではないですか。こういうのというのは、やはり地区計画なのか、行政側で今の立ち上がりのところをちょっと高くするだけで３階までいけるよとか、こういうのというのはどこがどうすれば変えられるのかを教えてもらいたい。","respondent":"高梨木密整備推進課長、稲田都市開発課長","answer":"例えば第二種高度を第三種高度に上げるためにはどうしたらいいのかということになると、手続的には高度地区の変更手続を行うということになろうかと思うのですが、それも単純に住民の皆さんがそうやりたいから、ではできるのかというと。いろいろなまちづくりをやる中におきまして、例えば市街地再開発事業等、地区計画等を立てていくと、そういう中におきましては、まちづくりの方針とか、そういうものに従いながら空地をつくったり。","voiceIndex":198,"id":"exchange-066"},{"speaker":"石田（秀）委員","kind":"確認","question":"最後に確認なのだけれども、高度地区というのは、行政がやるといったら変えられるのではないのか。それだけ確認です。","respondent":"鈴木都市計画課長","answer":"手続的には変えられることにはなってありますが、やはり、変更理由も含めて非常にハードルが高いです。","voiceIndex":201,"id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4276#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":70296,"voices":205}},{"id":"r01-20191111-9","meetingId":"r01-cm11","date":"2019年11月11日","dateIso":"2019-11-11","committee":"文教委員会","time":"午後 １時００分～午後 ２時５０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和元年陳情第４７号、ひろまち保育園閉園に関する陳情につきましては、予定表２、報告事項(4)ひろまち保育園在園児の優先転園","agenda":"令和元年陳情第４７号、ひろまち保育園閉園に関する陳情につきましては、予定表２、報告事項(4)ひろまち保育園在園児の優先転園","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"１番の項目に、閉園延長の可能性が示されていたということで、多くの方が延長の可能性があるのではないかと思っていたのではないかと思うのですけれども、この延長の可能性について、この間、区のほうで検討は行ってきたという説明がありましたが、どのような検討を行っていたのか伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"２０２０年度の新規保育園については、ある一定の確保ができるという見込みがついたところで、これまで延伸の可能性について検討してきたところです。","voiceIndex":7,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"転園することによって環境が変わり、子どもたちの成育にも影響を及ぼすということで、他の議員の方が一般質問でも言っていましたけれども、港区では職員もそのまま、新しい園をつくって転園をさせてやったという配慮があったということで、品川区では１,６５０m2を確保することが無理だとしても、やはり一部ではあっても、そういった転園がきちんとできるということを保証していく。","respondent":"吉田保育施設調整担当課長","answer":"確かに港区のようなやり方もあるとは思うのですけれども、品川区としては、ひろまち保育園そのものを動かすというのはほとんど不可能だと考えましたので、このやり方を決定した次第です。","voiceIndex":9,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間、区内での、２歳、３歳、４歳というところでの申し込み状況も、３歳を見ると４００名から５００名ぐらい申し込みをされているということで、やはりほかの方にも影響が出てしまうというようなことがあり得るのではないかと思うのですけれども、そこの新たな待機児童の問題について伺いたいと思います。来年の４月に向けた今年の優先転園の申し込みが終わったところで、入園の状況を伺えればと思います。","respondent":"佐藤保育課長","answer":"２歳、３歳、４歳の部分ですが、こちらに関しましては、ひろまち保育園の空いたスペースを利用しての定期利用、また新設園もつくっておりまして、そちらに関しましては３歳、４歳、５歳も空きがある状態ですので、待機児童に関しては十分対応できると。","voiceIndex":11,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"特に、３歳のところですね。定期利用のお話もありましたけれども、やはり定期も１年で終わってしまうということになり、また違うところを探すということになりますから、やはりそういったことがないように、同じ場所で保育することができるというのが望ましいと思いますが、いかがでしょうか。","respondent":"佐藤保育課長","answer":"１点目の大井町近辺でどうなのかですけれども、待機児童に大きく影響を及ぼすところというのは、大規模な住宅といいますか、マンションができた場合なのですけれども、大井町近辺ですと、入居日が４月以降という情報もありますので、昨年もしくはその前の勝島や東大井のように。","voiceIndex":13,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういった中で、大規模なマンションの４月前の入居はないというお話でしたけれども、それでも新しい申し込みというのはマンションができなくてもあると思うのです。関わって、ひろまち保育園の優先転園の件なのですけれども、今回、内定者１２６名、不承諾者が１１名ということで、内定者の方はどういったところに転園されて、また不承諾の方がどういった地域の方だったのか、そこを伺いたいと思います。","respondent":"佐藤保育課長","answer":"もう一方で、今、ご質問のありました不承諾の方の地域別ですが、品川地区で５名、東大井・八潮地区で５名、大井地区で１名、その他の地区に関しましてはゼロです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"要は、伺いたかったのは、入園内定された方も、お宅が近くですとか通勤途中のところ、通いやすいところにしっかり入れているのかということで、うわさでは２０希望まで入園希望の枠があったという話も聞いておりますけれども、しっかりと通えるところに入れたのか、そこを伺いたいと思います。","respondent":"佐藤保育課長","answer":"大変失礼いたしました。内定者の状況ですが、内定した方の約９割の方が第３希望以内の園に内定しておりますので、近隣もしくは希望されている保育園に内定したのかと考えているところです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"第３希望までで入れたということで、それがどういったところだったのかがわからないので何とも言えないところなのですけれども。不承諾の方が１１名いらっしゃるということになります。申し込みをされなかった方が２１名ということで、３２名の方がまだ在籍をしているというところで、この３２名の方は今後どうなっていくのか、区の対応について伺いたいと思います。","respondent":"佐藤保育課長","answer":"新２歳児から新４歳児までの３２名の方ですが、区としましては、当初からご説明しているとおり、優先転園は年度に分けて２回行いますので、令和３年４月の時点でご希望する保育園に優先的に転園をしていただくというふうに、丁寧に説明をしてまいりたいと考えています。","voiceIndex":19,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"再開発の問題ですけれども、このひろまち保育園のところは広町の再開発が予定されているということで、子育て・保育よりも再開発が優先されている、このまま強行すれば区の姿勢が問われるということも陳情に書かれておりますけれども、実際、２０２１年に閉園されるときにはまだ広町の開発は、工事は着工していないという確認と、そういった中で閉園をしていくということで、なぜこのタイミングなのか。","respondent":"吉田保育施設調整担当課長","answer":"なぜこのタイミングかというところなのですけれども、令和３年３月以降開発する予定だと、ＪＲから聞いているところと、実際、劇団四季も最近ホームページで公開されたようですけれども、２０２１年の夏以降、現在あるものは有明のほうに移るとか。","voiceIndex":21,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"判断は間違っていないとおっしゃいますけれども、やはり再開発を優先して子どもたちや保育をないがしろにしていると思われても仕方ないのかなと思います。区が区民の暮らしを、福祉、保育を守っていくという姿勢こそ必要なのではないかと思いますけれども、いかがでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"もともと５年ということで保育園の募集をしたところもあります。その開発の状況も、各種関係部門を含めて、ＪＲ東日本との話を含めて、先が見えてきたところで、私どもは当初の予定どおり５年で閉園すると決めたところです。","voiceIndex":23,"id":"exchange-009"},{"speaker":"せお委員","kind":"質問・要望","question":"私からは２つほど質問させていただきたいのですが。保育課内において、事業やサービスの内容の情報共有や周知といったものは、どのように行われていたのでしょうか。２点目ですが、転園のスケジュールですね。ぎりぎりまでＪＲと交渉されていた、話し合ってくださったのは承知しておりますが、スケジュールの決定はどのようになされたのでしょうか。お聞きしたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"スケジュール。今回、確かに短いというご批判もあるのですけれども、来年の一般の募集の前にやらなければ、当然、優先転園にならないところもありますので、それは１０月中に終わらせないと来年４月の一般の募集の対応に影響が出てしまいます。","voiceIndex":26,"id":"exchange-010"},{"speaker":"せお委員","kind":"質問・要望","question":"もしかして、保育課内で、報告・連絡・相談等が少しうまくいっていなかったところがあるかもしれませんので、これからは報告・連絡・相談をしっかりとしていただくことを要望したいと考えています。そして、スケジュールに関しましても、今後はなるべく早目にお知らせしていただくなど、園児と保護者の方のお気持ちや状況を考慮したスケジュール調整を要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"},{"speaker":"筒井委員","kind":"質問・要望","question":"この陳情の趣旨にありますとおり、「当初決定の２０２１年３月から可能な限り延長頂くよう品川区に求めてください」ということなのですけれども、お話が出たとおり、ＪＲ東日本とか劇団四季とか関係者がいる中、品川区が２０２１年３月以降の延長を決定できるものなのか。延長の物理的な可能性というのはあるのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"こちらの開発にあたりましては、都市開発課が所管になりますので、私どもとしては、２０２１年３月以降にその予定があるということであれば、そこに従う形になります。","voiceIndex":30,"id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"詳しくは都市開発課のほうだと思うのですけれども、そういった契約がなされていて、仮に、こちらの保育課のほうで“延長してください”と言っても、それは難しいということでよろしいのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"この間、私が覚えているだけで平成３０年から何回か、所管の都市開発課を通じてＪＲ東日本にはお願いをしてきたところではありますが、延長するのは難しいという回答をいただいているところです。","voiceIndex":32,"id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"そうしますと、実際難しいということなのですけれども、ただ、これも陳情にあるとおり、延長の可能性を期待されていたということです。そういったことを含めて、区としては延長可能性の示唆の程度というのは、どのくらいのものだったのか。そうした延長可能性のことを言った程度、先ほどは一切ないというご答弁でしたけれども、改めてその辺りの区の認識としてはどうなのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"ただ、広町地区のまちづくりが遅れることが想定された場合は延伸する、もともとの条件が延伸されることがあれば、広町地区のまちづくりが遅れることがあればということの話なので、今回予定どおりに５年間、２０２１年３月以降、開発が進んでいくということがありますので。","voiceIndex":34,"id":"exchange-014"},{"speaker":"筒井委員","kind":"質問","question":"その点は承知いたしましたけれども。そうしますと、先ほどご答弁されたように、再開発の予定がかなり固まってきたという段階で、早目、早目に入園されている保護者の方が納得がいくようなご説明や、またある意味、期待権というのが失われたということに対しての区からの謝罪というか、そういったものはなされたのでしょうか。説明とか謝罪のようなものがあったのかどうかというのをお聞きします。","respondent":"吉田保育施設調整担当課長","answer":"早目にできなかったのかというところは、この間、ＪＲ東日本との交渉でひろまち保育園を延長できないかというところと、引っ越しできないか、ほかの近隣のところに移転できないかというところ。","voiceIndex":36,"id":"exchange-015"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。そうした状況でありますけれども、優先転園に申し込まれた方が８６.７％いて、そのうち内定が相当数通ったということなのですけれども、優先転園を申し込まれた方というのは、区のご説明を受けて、納得されたということなのでしょうか。優先転園を申し込まれた方の気持ちとかお考えを、区はどのように把握しているのでしょうか。","respondent":"佐藤保育課長","answer":"委員ご質問の、１５８名中８６.７％、１３７名の方が納得して申し込んでいるのかというご質問ですが、個別にさまざまなご意見をいただいておりますので、すべての方が１００％納得しているかというのはあれですけれども。","voiceIndex":38,"id":"exchange-016"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。これは参考としてお聞きしたいのですけれども、このひろまち保育園のある場所は、来年から始まってしまいます羽田新飛行ルートの直下の地点にあると思うのですけれども、羽田新飛行ルートについては、ひろまち保育園の保護者の方というのはご存知なのでしょうか。区としても“羽田新飛行ルートの直下にありますよ”というご説明はされたのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"第３回定例会の時の文教委員会だったと思いますけれども、補正予算で、本年度、ひろまち保育園を含めて飛行ルートの下に入っている保育園は、国土交通省の補助金を受けて、外気を取り入れるところに防音タイプ。","voiceIndex":40,"id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"羽田新飛行ルートについて、ちょっと嫌だなとか、そうした否定的なご意見というのはあったのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"特に、直接こちらのほうにご意見だとかが届いていることは、今のところはございません。","voiceIndex":42,"id":"exchange-018"},{"speaker":"横山委員","kind":"質問・要望","question":"本日結論を出す、でお願いします。ただし、先ほどせお委員から要望等がありましたけれども、保護者の皆さんの気持ちというところは、会派としても十分承知をするところでありまして、説明の方法を統一していくですとか、先ほど風評等が多少あったということがあったのですけれども、そういったものが起きにくいようにより丁寧に、そしてわかりやすく正確な情報が伝わるように、というところ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-019"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"自民党、本日結論を出すで、結論は不採択でお願いします。内容として、もともと閉園の予定が予定どおり進んでいること、あとは転園の手続も順調に進んでいると感じていますので、これを粛々と進めていただきたいと思っています。ただ、１点だけ。可能性の示唆のところもそうですし、誤解の度合いがなるべく少ないように、これから心がけていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-020"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういった意味では、その点については、今後についてしっかりと反省をするとともに、やはり転園というのは各保護者、家庭にとって大変大きな負担となることでもありますから、可能な限りの丁寧な説明と、一人一人に寄り添っていただいての転園を進めていっていただきたいという思いがありますけれども、区として、今回、当初予定どおりでの閉園の決定をすることについてはやむを得ないと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-021"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択をしたいと思います。最初の８月２６日の報告があった際にも、私は延長すべきだということで主張をしてまいりました。待機児童の問題も解消されておりませんし、あと、新たな問題も発生してくるというところと、やはり議会として保護者の方々の思いを受けとめて、採択をしていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すで、趣旨採択でお願いします。今後はこうしたことがないように、ぜひしていただきたいと考えております。ただ、ＪＲ東日本等々の関係者がおりまして、区だけの問題となってきていないということで、延長の可能性というのは客観的にほぼゼロだということを踏まえまして、趣旨を採択させていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すということです。５年で閉園することは、それに向けてどう準備をするかというところが問題だったのではないかと思いますので、延長ということに関しては、採択することはできないと思います。ただ、ほかの委員もお話しされていますけれども、陳情の理由の1)の部分での認識の相違ということに関しては、やはり担当の部署としては、今回の件を重く受けとめていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-024"},{"speaker":"筒井委員","kind":"意見","question":"わかりました。先ほど述べましたとおり、保護者の方のお気持ちは十分受けとめますけれども、物理的に延長というのは不可能だということになっておりますので、不採択ということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-025"}]},{"id":"topic-02","title":"令和元年特別区および東京都人事委員会勧告の概要","agenda":"令和元年特別区および東京都人事委員会勧告の概要","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"人事委員会からの意見というところで、長時間労働の是正ですとか、メンタルヘルス対策についてということで書かれておりますけれども、今の品川区の現状について伺えればと思います。","respondent":"工藤指導課長","answer":"今回の意見のところにも、メンタルヘルス対策、あるいはハラスメント防止対策なども含めて記載がありますけれども、これらにつきましても、これまでの取り組みと同様、引き続き進めていきたいと考えているところです。","voiceIndex":60,"id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"出退勤システムのお話がありましたけれども、それはこの間、土日の打刻ができないということで言ってきましたけれども、それはできるようになったのか。勤務時間の実態を把握していかなければ、実際にどれだけ働いているのかということがわからないと思いますので、そこのところを伺いたいと思います。","respondent":"工藤指導課長","answer":"ご指摘いただきましたように、現状だと土日の勤務の部分がカウントできないというシステムの部分がございました。遅くとも来年度中、早ければ今年度中にもできるような体制で、今、システム改変を行っているところですので、それを進めていきたいと考えているところです。","voiceIndex":62,"id":"exchange-027"}]},{"id":"topic-03","title":"令和元年度 各種学力調査の結果","agenda":"令和元年度 各種学力調査の結果","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"一部ご紹介がありましたが、生活習慣や学習環境に関する調査についてもご説明いただきたいというか。今後でも構いませんので、ぜひ説明いただければと思います。この結果が具体的にはどういった形で活かされていくのかというところをご説明いただければと思います。","respondent":"工藤指導課長","answer":"それを授業の関連する部分で、第８学年担当の教員はそれを活かしたり、また同時に、まさに第７学年で教えている教員たちにしてみれば、その比例・反比例を学習するところで、課題が見られる部分については、より丁寧に。","voiceIndex":69,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"生活習慣のほうも各学校のほうでクロス集計はやっていくというような形になるのですかね。無答率が下がったというところもご説明がありましたけれども、ここについて分析があれば伺いたいと思います。小学生のころに詰め込み教育というのですか、そういった形で自分の知識として使えないというか、そういった形になってしまっているのかなというように思ったのですけれども、そこも含めて伺いたいと思います。","respondent":"工藤指導課長","answer":"例えば社会、理科に関する課題の部分で言いますと、やはり授業改善に資することが必要であると考えています。例えば、社会につきましても、歴史事象を学ぶ際には、なぜそのようなことが起きたのかという背景を考え、またそれを表現、説明するような授業。","voiceIndex":71,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"今のところにも関連してまいりますけれども、結果を見ると、正答数がゼロという子どもさんもいると。取り残されてしまうというか、そのままになってしまうということがないようにしていかなければならないと思うのですけれども、今後の対応ですとか、そのお子さんが誰なのかというのかをつかんでいらっしゃるのか、その支援をやはりしっかりしていかなければいけないと思うのですけれども、いかがでしょうか。","respondent":"工藤指導課長","answer":"補充につきましては、関連した単元の中で補充的に行うことも考えられますが、あとは放課後学習等、今、品川地域未来塾を学校支援地域本部中心に進めてありますけれども、そういったところで必要に応じて課題を克服する、いわゆる復習などを行っていくなど。","voiceIndex":73,"id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"義務教育ですので、取り残しというのですか、わからないまま進んでしまうということがないように、基礎の学力をつけていくということで、しっかりと対応していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-031"},{"speaker":"横山委員","kind":"意見","question":"１点だけお願いします。３ページの「ＩＣＴを活用したい」が「当てはまる」という児童・生徒の６年生の国語の選択肢別平均正答率が高いということなのですけれども、このことからどういったことが読み取れるのか、今後、どういったことに活かしていけそうなのかというところを、区がどうお考えなのか、お聞かせいただけたらと思います。","respondent":"工藤指導課長","answer":"ただ、児童・生徒のほうは、学びに向かう態度というところで、意欲的に、主体的に学べるかという部分で言えば、結果としては、コンピュータも含めたＩＣＴを授業で活用したいというふうに肯定的に回答する児童・生徒ほど正答率が高いという傾向になったです。","voiceIndex":77,"id":"exchange-032"},{"speaker":"横山委員","kind":"意見","question":"児童・生徒の学習に対する意欲だったり、主体的な姿勢みたいなところ、先ほどの無答率を減らしていくというところですとか、ＩＣＴ等の最新の機器等を活用して、いろいろ工夫していただいていると思うのですけれども。子どもたちの意欲を引き出すというところが、先ほどの社会ですとか理科の課題にも何かつなげられるところがあるかと思いますので、ぜひ授業も十分に工夫していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"第７学年に進学する際に、私立中学などを受験する方がいて、そっちの私立中学に流れてしまっていることも、原因として考えられるのでしょうか。この第２学年から第６学年と第７学年から第９学年の差が出てしまうということについて、区としてはどのようにお考えになっているのでしょうか。","respondent":"工藤指導課長","answer":"その点におきましては、小学校、義務教育学校前期課程においては、来年度から、中学校、義務教育学校後期課程におきましてはその次年度、教育要領が本格実施するというこの時期を考えますと、今、まさに移行期です。","voiceIndex":81,"id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。ぜひ授業改善をしていただいて、学力向上を図っていただきたいと考えております。特に理科の成績が低いのかなと思うのですけれども、理科が弱いという理由はどのようにお考えなのでしょうか。その改善は何かお考えなのでしょうか。","respondent":"工藤指導課長","answer":"実験に若干時間がとられる部分があって、そういったまとめの部分がなかなかうまくできていないという場合も見られますので、そういった改善も含めて進めていくことが改善につながるのではないかと考えているところはあります。","voiceIndex":83,"id":"exchange-035"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"この結果が概要で出ているのですけれども、中身について、全部を見る機会というのはどうしたらいいのでしょうか。３年生（９年生）になったときに、公立高校を受験するためには社会と理科の力がかなり求められると思うのですが、３年生になったらまた３年生の社会、理科の勉強があるので、積み残した分を３年生で繰り返すのは社会と理科は大変なのですけれども。おわかりになる範囲で結構です。","respondent":"工藤指導課長","answer":"ただ、その辺りの、例えばクロス集計の部分であるとか、そういった内容につきましても、今後、児童・生徒アンケートの内容も含み考えながら、実施時期も含めて精査をしながら検討してまいりたいと思っているところです。","voiceIndex":86,"id":"exchange-036"}]},{"id":"topic-04","title":"改修工事および特別整理に伴う八潮図書館の休館","agenda":"改修工事および特別整理に伴う八潮図書館の休館","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"資料の４の利用制限等の(2)で、エレベーターが使用できないため、困難な方には、併設児童センター経由で連絡を受け、図書館職員が１階へ降り対応するとなっていますけれども、具体的には、いわゆる介助するとか、どんな感じなのですか。","respondent":"横山品川図書館長","answer":"委員ご指摘のとおりです。区立図書館においては、ゆたか図書館、源氏前図書館がエレベーターがないところですが、ご連絡をいただいて階段を補助対応するようなことを行ってありますので、同じように八潮図書館でも対応する予定です。","voiceIndex":94,"id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"源氏前図書館なんかでも、車椅子の方なんかも職員の方が抱えて運んでいらっしゃるという感じでしたけれども、それはやっぱり人海戦術ということでしょうか。駅の階段にあるような、上に上がっていく装置があって、みたいなのではなくて、基本的に人海戦術ということでしょうか。","respondent":"横山品川図書館長","answer":"ただ、工事期間１か月の間で設置するのが困難であることと、あと、この階段を使って、毎日予約図書の移動をさせなければならないので、それを両方とも取り付けるというのも困難で、また、その際に交通で障害が生じたらいけないので。","voiceIndex":96,"id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4982#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":29368,"voices":99}},{"id":"r01-20191111-5","meetingId":"r01-cm11","date":"2019年11月11日","dateIso":"2019-11-11","committee":"総務委員会","time":"午後 １時００分～午後 ３時１７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"予算編成過程の公表","agenda":"予算編成過程の公表","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"予算編成過程の透明化を図るという対応ですので、それ自身は歓迎したいと考えています。少し伺いますけれども、予算編成過程の透明化を図る目的を改めてご説明いただきたいと思います。それと、こうした形で公表している他区の動きですけれども、２３区ではどういう動きになっているのか、そこもお知らせいただきたいと思います。","respondent":"品川財政課長","answer":"ただ、やり方自体については、大分ばらばらというか、各区でいろいろやり方が違っているというところもありまして、品川区としてもどうするかというところは、今回いろいろ検討してきたのですが、基本的には全事業を公表して、少しでも透明化を図りたいというところで、今回。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"それで、１２月上旬にホームページ上で予算額の公表ということになりますが、いわゆる区議会への報告という形をとるのか、それとも１２月中と言われると委員会の開催の日程も含めて、ホームページ上の公表とともに、区議会、もしかしたら総務委員会になるのかもしれませんけれども、報告というものはどのように考えているのか伺いたいと思います。その点についてはいかがでしょうか。","respondent":"品川財政課長","answer":"今、説明をしてしまいましたが、５００万円以上の部分などの議論もいろいろあると思いますけれども、やはりそこは予算特別委員会の中でやっていくべきだと考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"今の部分に関連するかもしれないのですけれども、差額の５００万円以上の場合は理由を表記するということだったのですが、この５００万円の根拠をお知らせください。ホームページでの記載がＰＤＦということだったのですけれども、これは視覚障害の方たちが読み取ることはできるかというところを確認させてください。","respondent":"品川財政課長","answer":"そういう面ではほかの区とレベルを合わせておくということを考えて、今回については５００万円という形にしております。それから、ＰＤＦの視覚障害の方への対応については、検討材料として考えします。","voiceIndex":9,"id":"exchange-003"},{"speaker":"田中委員","kind":"意見","question":"この予算編成が公表されるということは、目的とする透明化を図るためという部分や情報公開の部分で一歩進んだなということでとても歓迎したいのですけれども、やはり視覚障害の方たち、どの方たちからも見られるようになってほしいと思うのでよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"それで、質問したいなと。これはどうしてこうなったのだとか、どうして増えたのだとか、それが短い１行でも２行でもいいから書かれていないと、やはり質問したくなる。それで、質問しようとして、「いや、細かい点はお答えできません」となれば、結局、透明性というものはなくなってしまうではないですか。その辺について、少しご見解をお聞かせください。","respondent":"品川財政課長","answer":"これは、いろいろ考え方があるかなと思います。これも他区でやっているところを見れば、やはり事業の説明から出している区もあれば、一覧表でやっている区もあるという形で、これは後々、公表の仕方の統一化が見えてくるのではないかなと予想されるところがあります。","voiceIndex":12,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"公表ということで、すごく区民に開かれたというか、このように予算がついているのだというのは、確かにそれはそれで透明性の一部は前進されていると思うのですが、やはりどうしてもそれを見て疑問を感じる。聞きたい。長くならないようにやるというのは難しいと思うのですけれども、何か検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"西本委員","kind":"意見","question":"個別事業の説明はできないものがある、問い合わせには対応できないものがありますということなのですが、大体どういうものが説明できて、どういうものが説明できないというのをある程度指針があるのかなということです。なぜかというと、私が知らないのにプレス発表をすると。本来であれば、プレス発表の前に審議をすべきだと思うのです。予算案が何なのか。それをどういう形で表現するのか。","respondent":"品川財政課長","answer":"詳細の説明のところについては、当然、予算審議前に事項別見積書なども公表しておりますので〔同日後刻に「公表しているのは事項別明細書」と答弁訂正あり〕、そこを見ながらという形で、今のところ、基本的にはそのような考えです。","voiceIndex":15,"id":"exchange-007"},{"speaker":"西本委員","kind":"確認","question":"確認しますが、詳細については、私たちは事項別見積書を見られると思うのですけれども、区民の方が要求されれば、そこまでは出しますよということでよろしいのですか。最終決定は３月です。そして、このデータは、ここの位置づけのものなのですというように、はっきりと示していってほしいなと思うのです。本当に誤解されると思うので、その辺はいかがですか。","respondent":"品川財政課長","answer":"事項別見積書については、現時点でも閲覧等が可能〔同日後刻に「公表しているのは事項別明細書」と答弁訂正あり〕となっておりますので、当然、情報の公開の要求があれば、それに対応していくです。","voiceIndex":17,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"予算編成の流れは、区民の方たちはわからないと思うのです。「当初予算編成の流れ」というものなのですけれども、この文言も一般の方々は多分わからないと思います。それで、最終決定ではなくて、最終というのは、議会の予算審議の中で審議がされて、３月に議決という形になりますというところを明確にしていただきたいなと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、西本委員が指摘した点は、聞いていてとても大事だなと思いました。この決定の流れは議員が見れば多分わかるのかもしれないけれども、確かに住民から見ると、少し予算案と議決と執行の関係性というのはわからないという前提で、ここはご答弁もありましたけれども、解説なりわかりやすさを工夫していただきたいと要望だけしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-010"},{"speaker":"つる副委員長","kind":"質問・要望","question":"本題のところとは違いますが、ＰＤＦのところの確認で、先ほど質疑があって、検討というご答弁がありました。実際、今回、品川区から見ればスタートということで、非常に大事な視点だと思います。そのあたりについて、しっかりと対応をしていただきたいという視点でご答弁をお願いしたいと思います。","respondent":"品川財政課長","answer":"この代わりになるものとなれば、基本的には音声サービスという形になると思います。そうすると、対応として、多分一定の期間がかかると思いますので、それがどれぐらいかかるかというところを考えながら、やっていかなければいけないと現在考えております。","voiceIndex":23,"id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"少し確認というか、要望というか、お伺いしたいのです。事項別見積書のお話が先ほどあったのかなと思います。事項別見積書も、当初予算の「要求額」、「予算案」のところで項目として一緒に見られるようにはなるのか。事項別見積書もあったほうがわかりやすい、区民の方により情報が伝わるかなと思ったのですけれども、その辺の検討はどのようにされたのかということを伺いたいと思います。","respondent":"品川財政課長","answer":"事項別見積書のところですけれども、これを始めるにあたって、いろいろ実施している区などを見て考えたところで言いますと、とかく今、半分以上の区がやっていますけれども、事項別見積書を出しているというのは、私の調べた限りではないというところがあります。","voiceIndex":25,"id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"わかりました。ただ、やはりもう少し詳しく知りたいなと思う方はいると思うので、そういった場合に、先ほどご答弁の中にもありましたとおり、事項別見積書をどこかで見ることができるのですよね。区政資料コーナーなどで見られる。見られないですか。どこに行ったらそれが見られるかということが、注意書きでも書いてあったらいいかなと思ったのですけれども、いかがでしょうか。","respondent":"品川財政課長","answer":"基本的に公表している部分については、予算案として確定した部分として公表しているというものですので、閲覧ができる、できないというところは、あくまでそこの段階のものです。予算要求時点でのものというところは、現在のところ出しているところはございません。","voiceIndex":27,"id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"私が求めているのは、今答弁いただいた見られる場所などを記載していただけたら、区民の方が見に行けるかな、区民の方にとってわかりやすいかなということを伝えたくて、ご説明あった１文を記載してほしいなと思っていますが、いかがでしょうか。","respondent":"品川財政課長","answer":"これは、あくまで予算編成過程のものですので、予算案のもので出してしまうと、それは非常に混乱を来してしまうので、それを公表する考えはございません。","voiceIndex":34,"id":"exchange-014"}]},{"id":"topic-02","title":"令和元年職員の給与等に関する報告及び勧告の概要","agenda":"令和元年職員の給与等に関する報告及び勧告の概要","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"職員の平均年間給与では、約２万２,０００円の増とありますけれども、これは職種や級や号によってはマイナスになるところもあるのか。そこを単純に伺いたいというのが１つです。今回の勧告の中で何か改善というか、議論があったのか。そこもあわせて伺いたいと思います。","respondent":"黒田人事課長","answer":"２点目の人事委員会の考え方ですが、先ほどご説明しました１ページ目の４の「本年の公民較差算出」というところで、昨年度の議論では、行政系人事制度について、今まで８層制だった職員階層を６層制に見直したことによりまして、職員ですと１・２級の職員を統合して１級の職員。","voiceIndex":41,"id":"exchange-015"},{"speaker":"須貝委員","kind":"質問","question":"５０人以上の企業に対してチョイスして、平均の給与、特別給、ボーナスを出していると思うのですが、その辺の５０人以上というのでは、民間企業の実態の給与、実態の特別給というのを把握することがだんだんできなくなってきているのかなと少し思うのです。その辺、あくまで人事委員会が決めたことなのですが、区としてはどのように思っているのですか。少しご見解をお聞かせください。","respondent":"黒田人事課長","answer":"今年の人事委員会の調査、勧告ですが、月例給が下がっておりますのは、先ほども少しご説明したとおり、人事給与制度を改正した際に、８層制から６層制に変えたとき、８つの層があった職層が６つになった関係で、前の給与表でこういう表記だったものが。","voiceIndex":43,"id":"exchange-016"},{"speaker":"須貝委員","kind":"意見","question":"特に、今、区内の民間事業者が実態として、恐らく企画のほうでも把握はしていると思うのですが、私はそんなにいいと思えないし、まして、このボーナスは６年連続上昇するわけです。実際、これだけボーナスも上がっているのだよという考え方を持って、認識をして見ているのかどうか。そこに対して、もう一回、見解だけお聞かせください。","respondent":"黒田人事課長","answer":"あくまでも特別区内の民間企業の実態調査をして比較していますので、品川区の事業所と比べるとどうかというところは、この調査からは、なかなか導き出せないのかなと考えています。","voiceIndex":45,"id":"exchange-017"},{"speaker":"須貝委員","kind":"意見","question":"それで、先ほども申し上げましたけれども、またボーナスが上がるということになれば、やはり区民感情としても、区民の皆様の理解を得られるかどうか、私は非常に疑問に思いますので、一応意見として、今回申し上げさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"月の給料が下がるということです。特別区は人事委員会の調査に基づいて、統一した考えのもとでやっているとは言いつつも、今後、これに従っていかなければいけないのですか。再任用だから仕方ないよねという形なのか、いや、やはり能力給という形になってくると、それに見合った給料体系というものが、当然必要になってくるのではないかと思うのですが、その辺の考え方はいかがですか。","respondent":"黒田人事課長","answer":"当然、区によって財政規模もいろいろ違う中では、人材確保という面では、２３区一体となって採用も含めて任用制度を定めているという中で、いわゆる労使交渉も２３区と特別区長会という形で進めております。","voiceIndex":51,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"退職金にかかわるというところにおいては、４７．７カ月となると、小さい額でも結構大きな額になります。そうすると、できればベースアップという考え方をしていただきたい。再任用については、教員なども既に国の流れで、多分７０歳近いところまでいくのではないですか。そういうところもあるので、やはり健康状況もあると思うのですが、人材確保という意味、それから、人材育成を考えると、いいのかどうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-020"}]},{"id":"topic-03","title":"水辺のライトアップ整備工事（かもめ橋）請負契約","agenda":"水辺のライトアップ整備工事（かもめ橋）請負契約","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"毎回、予定価格について伺っているのですけれども、いつもこの根拠を出せるところまでは出してほしい、説明資料の中に記してほしいということを求めているのです。そういった、この契約が正しいかどうかの判断材料になるのではないかなと思うのですけれども、説明資料を作成するにあたって、内訳の記載について、どう考えられたのかというところを伺いたいです。","respondent":"立木経理課長","answer":"予定価格は、事前公表している関係もあります。例えば事後に細かく内訳等を公表することによって、他の入札案件等への影響も考えられますので、こういった形で予定価格総額ということで出させていただいているところです。","voiceIndex":58,"id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、議会での説明ということで、契約にかかわる報告ですので、予定価格がこのように積算されてこの額になったということが、これでは全然わからないので、そういった資料作成をしていただきたいなということを求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"請負契約という報告で、金額が妥当かどうかという視点もあるのですけれども、品川区内では、この間、このようなライトアップ事業をさまざま展開してきて、大井町駅前や西小山などでやって何年かたちますが、やはり区民から聞こえてくる声は大きく２つあります。その辺について、少しご見解を伺いたいと思います。２つ目は、これは全額一般財源なのかどうか。その割合など、歳入と言ったらいいのでしょうか。","respondent":"柏原企画調整課長","answer":"一方で、どのぐらいお金をかけたらいいのか、それでどう効果を出すかというのは、まさに我々がいろいろ検討しなくてはいけない部分もありますし、どこまで何をというのは、今の段階で、細かくこれはここまでというのはありませんが、例えば、長期基本計画の実施計画の中で。","voiceIndex":61,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"大井町は年間で５,０００万円ぐらいかかっています。今回は１億２,０００万円ということで、さまざまな住民の声も聞きながら、こうした事業の展開についていろいろ検討していただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-024"},{"speaker":"西本委員","kind":"確認","question":"確認だけです。これを落札したところと、予定価格の差が４００万円ぐらいあるのです。４００万円の差があるということは当たり前のことなのか。それによって、同じ項目、仮に人件費が片やＡ社が１００万円であって、Ｂ社が２００万円だという形で、これは１００万円でも妥当なのかなと捉えて決めているのか。そういう詳細にわたっての比較をしながら落札をするという形になっているのでしょうか。","respondent":"立木経理課長","answer":"こちらは制限付き一般入札ですので、予定価格内で最低制限価格を上回った金額で一番安い札を入れた事業者が落札という形になります。その際には、やはり総額で見ておりますので、もちろんそれぞれ事業者が積算し、積み上げてきた中での金額を札入れという形になってあります。","voiceIndex":64,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"ただ、その中身については、決定した後ですか。決定したところに、詳細にわたってチェックを入れるということでよろしいのでしょうか。しかし、５社までくると、やはりきっちりと積み上げをしているという調査がなされた上での落札になっていればいいのですけれども、少し心配になる部分があるのです。やはり４００万円というのがかなり差があるので、いいのかなと疑問を持ったのですけれども、いかがですか。","respondent":"立木経理課長","answer":"落札の仕方につきましては、委員がお話しされたとおり、予定価格以内の最低制限価格以上で最も安い金額が入ったところになります。その札入れしていただいた金額で適用があるものに関しまして、落札者として決定するということになっております。","voiceIndex":66,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"先ほどの最低制限価格というのは、事業者のほうには公表されているのでしょうか。","respondent":"立木経理課長","answer":"最低制限価格は非公表となっていますので、事後でも公表はいたしません。これを公表してしまいますと、そこに全て入札額が集中してしまって、結局くじ引きで、それこそ適切な金額で積算されているかどうかが担保できませんので、非公表という形になっております。","voiceIndex":68,"id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"それで、今回入札金額が出ているわけですが、翌年は、その資材を組み立てる作業や資材の購入がないから、翌年にライトアップを設置するときは、値段的には相当安くなるのですかということを教えてください。そして、この資材の保管です。保管は、今回入札した会社が保管して、管理・維持しているのでしょうか。教えてください。","respondent":"立木経理課長","answer":"工期は令和２年３月１９日ということで、一応年度内に完了する工事となっておりますので、これで、また来年度、追加工事が出るということではございません。一度つけてしまえば、あとはランニングコスト、維持費だけということになるかと思います。","voiceIndex":70,"id":"exchange-028"},{"speaker":"須貝委員","kind":"質問","question":"毎年つけるのではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"つけない。例えば西小山は西小山で……。すみません。勘違いした。教えてください。","respondent":"立木経理課長","answer":"こちらの工事で据えつけてしまうものでございまして、期間が終わったら取り外すということではなく、常設、そのまま固定してまいります。ですので、ランニングコストは電気代と、定期的なメンテナンス等ぐらいかと思います。","voiceIndex":73,"id":"exchange-030"}]},{"id":"topic-04","title":"ふるさと納税（寄附金）事業の新たな展開","agenda":"ふるさと納税（寄附金）事業の新たな展開","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"全然イメージが湧きにくいのですけれども、「区の魅力・取組みを広くＰＲし、応援していただけるための機会を増やす」ということは、つまり、何かポスターでもつくるのですか。東急グループのふるさと納税というサイト自体を私がよくわからないのですけれども、寄附をしたらどんな体験や何が返ってくるのか、イメージがよくわからないのでもう少しご説明いただきたい。","respondent":"伊東税務課長","answer":"一緒になってそういう開発の検討を進めていこうです。","voiceIndex":81,"id":"exchange-031"},{"speaker":"中塚委員","kind":"確認","question":"広報媒体を増やす、情報誌に掲載する。要するに、品川区がやっているふるさと納税事業をＰＲするということなのですか。改めて確認したいと思います。ふるさと納税はいろいろ議論がありますけれども、品川区の今の財政力を思うと、これで積極的に歳入を増やさなければいけないという状況はないと思います。先ほどの質問のところだけお願いします。","respondent":"伊東税務課長","answer":"それにプラスアルファとして、紙媒体にもいろいろとＰＲをしていただける形になりますので、その辺の中身についてはこれから検討しますけれども、そのようなことを含めてＰＲをしていくという形です。","voiceIndex":83,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"「東急グループのふるさと納税」と検索したところ、「ふるさとパレット」というものがあって、「地域から探す」で「関東地方」とやったら、「東京都品川区」だけが出てきたのですけれども、なぜこの話が出てきたのか。ここに掲載されるようになったのか。品川区だけなので、何でかなと疑問に思ったので、そこを伺いたい。","respondent":"伊東税務課長","answer":"予算的なところに関しては、同じようにトラストバンクおよびヤフーと契約していますけれども、先ほど言った７％と１％という中ですので、現状の予算の範囲内で十分できるというところで、今回、実施したところです。","voiceIndex":85,"id":"exchange-033"},{"speaker":"田中委員","kind":"意見","question":"今のご答弁だと、ずっとホームページに載っている状態だけでは、特に使用料は発生しないということの理解でわかりました。ちなみに、先ほど、体験型返礼品の検討ということで、東急とのオリジナルをつくっていくことを検討していくというお話があったと思うのです。体験型のイメージがつかないので、今の議論の中でどのような感じかなというイメージがもしあればお知らせいただければと思います。","respondent":"伊東税務課長","answer":"体験型ということでは、品川区にある資源を活用していかなければいけないです。相手があるので、なかなか難しいところはあるのですけれども、一応、１案としては、屋形船のクルーズやしながわ水族館のナイトアクアリウムプランなど、そのようなイメージ。","voiceIndex":89,"id":"exchange-034"},{"speaker":"須貝委員","kind":"提案","question":"もったいない気がします。それより、もしやっていただけるなら、ふるさと納税の限度額というものを国、総務省に提案していただいて、例えば年間５億円なのか、１０億円なのか、それ以上のふるさと納税は品川区では使いません、持っていきませんということをしないと、これは本当にお金の取り合いになってしまうと思うのです。それだけ少し意見を言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"「周知方法」で、「品川区ホームページにて」というのは、どこを見ればいいのですか。今、見ているのですけれども、どこを見ていいかわからないのです。どこに書いてあるのですか。","respondent":"伊東税務課長","answer":"まだ詳細なＰＲ文は載っていないかと思うのですけれども、これから順次返礼品の制作者といいますか、つくっている方から見たＰＲという部分など、さまざまな形でアップするという形です。","voiceIndex":92,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"このふるさとパレットというところが、東急のサイトになるということですか。東急のところがつくって、そこを開くと出てくるのですけれども、全然わからないですね。非常にわかりにくいなと思うのです。なので、トップからいくと、まず「ふるさと納税」というところがあるので、そこをクリックします。東急とどのような話をされていますか。","respondent":"伊東税務課長","answer":"ちゃんと意識して品川区というふうに入っていけば、当然すぐそこにたどり着けるのですけれども、そうではない方が多い中では、いろいろな広告媒体、駅や中刷りやさまざまな広告媒体からそちらにいくということも、１つ今まで以上に掘り起こしができるのではないかというところで。","voiceIndex":94,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"非常にいろいろなところで目につくよという仕掛けをしましょうということだと思うので、そういう意味で大切なことかと思うのです。もう少し東急といろいろやっているよという宣伝のような形ができるといいのかと思いますけれども、今後やっていただきたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-038"},{"speaker":"大倉委員","kind":"質問","question":"こういうどんどんアピールしたいものは、品川区の観光や地元の人たちに愛されているものがブラッシュアップされていないと、相手方にアピールできないというか、こういうものはどうですかと売り込んでいかないと、言い方はわからないですけれども、東急が自分たちの使いやすいものを使ってやって、それは本当に品川区の魅力としてアピールするのだったら。","respondent":"伊東税務課長","answer":"シナモロールは３割ぐらいというところでやっていますので、今後、体験型をやる場合には、当然３割ぐらいの形を見ていかないと、どうしても返礼品として太刀打ちできないというか、勝負できないという形になろうかと思いますので。","voiceIndex":97,"id":"exchange-039"}]},{"id":"topic-05","title":"ふるさと納税（寄附金）の返礼品追加","agenda":"ふるさと納税（寄附金）の返礼品追加","exchanges":[{"speaker":"西本委員","kind":"意見","question":"３万円を寄附すると、この３体なのですが、これは何％以内と決められています。３０％でしたか。例えば３万円の３０％というと９,０００円になります。今のキャラクターがありますが、大きいほうのぬいぐるみは１,８００円です。これで魅力がどれだけ発信できるのかなと、少し不安なのですが、その辺はどういう議論の中でこれをつくり、それをふるさと納税品の返礼品にしようとされたのか。","respondent":"伊東税務課長","answer":"ただ、それだけのコスト云々という話になるかもしれないですけれども、寄附者から見れば、制度はご存じのとおり２,０００円の負担ということになりますので、単純に考えれば２,０００円で返礼品がもらえる。","voiceIndex":104,"id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"１６０件ということは、やはりファンの方がいらっしゃるのです。１つ、返礼品が増えたねという程度で抑えるしかないのかな。これをやっていくと、毎年どんどん加算されるような状況が増えていってしまったら、本当に品川区の財政に負担がかかってしまうので、やはりそういう状況だということを区長をはじめ、議長がいろいろなところで発信していただきたいなと考えています。その辺はいかがですか。","respondent":"伊東税務課長","answer":"いろいろ物を申しながら、一方では受け入れのほうも少し考えながら、自分の形を推し進めつつ、しばらくはやっていかなくてはいけないかなと思っているところです。","voiceIndex":106,"id":"exchange-041"},{"speaker":"大倉委員","kind":"質問・要望","question":"できれば、３０％にしてほしいというよりは、少し値段が下げられるのだったら、先ほどの話ではないですけれども、大井町などの体験も含めて、割と金額が今より少し安くできるようなものがあったらしていただきたいなと思ったのですけれども、いかがでしょうか。","respondent":"伊東税務課長","answer":"ただ、体験型に関しては、そうはいっても一定程度はお金がかかると思いますので、それによって５万円にしたり、２万円にしたり、物によっては何万円以上のものに関してこういう品物なり、体験的なものを送るというのはセット可能ですので、それは今後。","voiceIndex":108,"id":"exchange-042"}]},{"id":"topic-06","title":"みずほ銀行品川区役所出張所の業務形態の変更","agenda":"みずほ銀行品川区役所出張所の業務形態の変更","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"今の報告は、要するにみずほ銀行から品川区にそういう報告があったということでいいのか、品川区からみずほ銀行にお願いをするということはあり得ないとは思うのですけれども、そこを１点確認したいと思います。","respondent":"齋藤会計管理者","answer":"私どもとしても、利便性を損ないますので、何とかこの形態でということで、繰り返しお願い、ご協議は申し上げておりましたが、いかんともしがたいということでございました。","voiceIndex":114,"id":"exchange-043"},{"speaker":"中塚委員","kind":"意見","question":"やはり区民サービスを思うと、出張所という機能が続くことが望ましいと思いますし、みずほ銀行がそうだと言われれば、どう抵抗していいのかわからない部分はありますが、残念ですと述べておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":116,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"恐らく職員の方々の利用が多いのではないのですか。銀行口座を開設したりされると思うのですけれども、逆に一般の区民の人たちというよりは、職員の方々がここを使って、私も１個持っていますけれども、非常に利便性が悪くなるなと思うのです。その辺の影響をどう考えていますか。いろいろ議論があったのでしょうけれども、職員の方々はかなり不便になるのではないかなと思ったのですけれども、いかがですか。","respondent":"齋藤会計管理者","answer":"おおよそ９５０口座ぐらいあるようです。ただ、休眠口座もあって、実際に送ってみないとどれだけ返ってくるかがわからない部分もあるようです。","voiceIndex":117,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"これは、議会の私たちにも関連するかなと思うのですけれども、１つの要求として、通帳が満杯になったときに、つくってくれるものがあるではないですか。あの通帳をつくれるＡＴＭというのは難しいですか。わざわざ行かなければいけないのですよね。近くの大井町などに行けば、そういうＡＴＭはありますけれども、そういうものがあるとうれしいなと思うのです。そういう要求は難しいですか。","respondent":"齋藤会計管理者","answer":"少し協議をさせていただきたいと思います。","voiceIndex":119,"id":"exchange-046"},{"speaker":"須貝委員","kind":"質問","question":"私も結構振り込みなどで窓口を利用するので、そういうときに困る方がかなり多い。今までそこにあったサービス機能がなくなるということは、本当に大変です。例えば口座を変更するときに、これは局長に聞かなければいけないのですけれども、政務活動費や名義を変えるなど云々あったときに、大井町支店でもいいのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2148#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":36990,"voices":126}},{"id":"r01-20191112-14","meetingId":"r01-cm11","date":"2019年11月12日","dateIso":"2019-11-12","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時０８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"区組織と関連団体に関すること","agenda":"区組織と関連団体に関すること","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"私が誤解しているのかもしれませんけれども、区の助成事業のところなのですが、２億７,５５２万５,０００円、これが助成金ということなのですよね。この助成金は、事業全体にかかっている費用の何％ぐらいなのでしょうか。","respondent":"古巻文化観光課長","answer":"平成３０年度で言いますと、財団の会計資料から正しく読み取れているかというのが難しい部分があるのですけれども、事業全体の金額が４億５,６００万円という報告を受けておりますので、そのうちの２億７,０００万円ほどが助成金として区から支出されているという状態です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"わかりました。それで、逆に助成金なしの事業というのは、ほかにあったりするのでしょうか。","respondent":"古巻文化観光課長","answer":"指定管理の部分については助成金の対象外という形ですので、建物の維持管理であったり、そのあたりは指定管理として行っていただいているという形になってあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"外部団体、民間というところ、公益財団法人という中で、よく言われることですが、区は労務体制であるとか財政状況には立ち入れない部分もあるという中で、品川区では数年前から労務監査、労務チェックというのですか、今、チェックをやっていると思うのです。指定管理団体にもその適用を今現在はしているのでしたか。そこについてお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"文化振興事業団におきましては、現段階ではチェックはまだ入っていないですけれども、順次やっていく予定です。","voiceIndex":10,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"指定管理の発注元として、そういったこともぜひ行っていただきたいと思いますが、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"おっしゃるとおりでございまして、指定管理の部分については、労働環境チェックということで、今どういう形で、ルーチンといいますか、全指定管理者に対してそういったチェックができるかという制度設計をしているところでございまして、来年度ぐらいから。","voiceIndex":12,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"よろしくお願いします。指定管理のシートというのが委員会に出てきて、所管の委員会の中でチェックはさせていただいているのですけれども、労務管理、労務監査、チェックについては、それは恐らくまだ議会には出てきていないですし、内部資料的なものなのかもしれませんが、できればそれも今後、体制が整ってからで結構ですので、議会にもお示しいただきたいと思いますが、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"指定管理のその部分に関しましては、労働環境チェック、プラス、いろいろなチェックといいますか、やっていきたいと思っていますので、トータルの中で、そういったチェックした内容についても、当然議会にもご報告させていただきながら進めていきたいと思ってあります。","voiceIndex":14,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は６月のこの委員会で、それぞれの公益財団法人について、退職後、ＯＢは何人いらっしゃるのですかと伺ったところ、文化振興事業団については１３名ということだったのですけれども、そのうち、部課長経験者、区の幹部職員の経験者は何人なのかを伺いたいというのが１点です。それと、現在の事務局長は元幹部職員であったのか、そういう経験があったのかどうかも伺いたいのが２点です。","respondent":"榎本総務部長","answer":"ＯＢという話がありまして、今現在、区の管理職経験者が入っているのは、４名、公益財団法人の管理職として入っております。それで、昭和６１年からどうなっていたかということですけれども、昭和６１年のときには、たしか総合区民会館は直営で区がやっておりました。","voiceIndex":17,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"現在の事務局長は、今４名の元幹部職員の方が再就職されているということですが、事務局に入っているのかどうか、お伺いしたいので、もう一度お願いします。","respondent":"榎本総務部長","answer":"事務局についても、全員ではありませんけれども、係長級のＯＢの方が何人か入っているということです。それから、事務局長は名前を言ったほうがいいですか。今現在の事務局長は、中山武志です。","voiceIndex":19,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"質問が不明瞭で申しわけありませんでした。文化振興事業団の役員名簿を拝見しますと、理事長のところに元副区長、あと副理事長には現職の副区長が入っています。公益財団法人というのはかなり厳しい審査も経て認定されるということもありますし、公益財団法人という性格そのものがかなり公益性が強いところだと思いますので、そこら辺をお伺いしたいと思います。","respondent":"榎本総務部長","answer":"文化振興事業団も含めて、区のＯＢが行っているところについては、区の再任用と同じような基準でというふうに区からはお願いをしているところですけれども、それぞれ団体の特性がありますので、団体の中で判断をしていると思いますが、それはわずかなものと考えております。","voiceIndex":21,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"わかりました。実績について伺いたいと思います。２点目は、第９条に、交付した後に事業の報告書を出してもらって、区が実績報告を調査して、交付決定の内容と条件に適合しないと認めるときは是正の措置を命じることができるというのがあるのですけれども、この第９条の是正のための措置についても、実際にこういう実績はあるのかどうか、伺いたいと思います。","respondent":"古巻文化観光課長","answer":"その結果として、何か是正が必要になってくるものというのは、特に今まで事例はないと認識しております。","voiceIndex":23,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"今は実績はないということですけれども、区からこういうことはやめろとか、そういう口出しも逆にしやすいということになってしまったりとか、そういう不安というのはやっぱりあると思うのですが、そこら辺に関しては私はあってはならないことだと思いますし、独立性とか目的を達成するために、一定の天下りの見直しのルールをつくったりとか。","respondent":"榎本総務部長","answer":"使用料、利用料金の徴収についても、財務会計の透明性がとれる、きちんと信頼できるところにお金が入るわけですから、そういったものも組織の中できちんとできるような形の組織に指定管理として任せていくということですので。","voiceIndex":25,"id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問","question":"職員数のところで、３２名、区からの派遣が３人、そして元管理職が４名入られているということで、内訳を聞きたいのですけれども、理事長、事務局長は元管理職の方ですよね。もう２名の元管理職はどこにいらっしゃるのかというのと、あと、３２名の方がそれぞれ何人ずつ、どこにどう配置されているのかというのを伺いたいと思います。","respondent":"榎本総務部長","answer":"それ以下、係長級については、係長を置いてある組織と置いていない組織がありまして、係長を置いてある組織につきましては、４人の係長がＯＢで入っています。それから係長を置いていない組織についても、ＯＢが係員として何人か入っているという形です。","voiceIndex":27,"id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"ＯＢのところは、ありがとうあります。その上で、それぞれのところ、３２名の職員の方の配置の内訳をお聞きしたいなと思います。","respondent":"古巻文化観光課長","answer":"それから文化振興課ですけれども、まず文化企画係が係長含めて５名の体制です。文化振興係が係長含めて３名の体制。それからメイプルセンターは、館長がおりまして、館長含めて５名の体制ということで、職員についてはそういった形になっております。","voiceIndex":29,"id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"魅力的なまちづくりに寄与するということを目的にされているので、こうしたものを壊してしまう、できなくなるようなまちへの変化に対して、文化振興事業団としてはどのようにお考えなのか、伺いたいと思います。","respondent":"古巻文化観光課長","answer":"文化振興事業団としてというのはちょっと難しいのですけれども、当然まちの形はどんどん変わっていくものですから、それに応じて変化に柔軟に対応していく、そういったことも重要かと思っていますので、恐らく文化振興事業団ができた当時から。","voiceIndex":31,"id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"きゅりあんについては、防音工事ができないというようにも聞いています。ですので、こうした面からも、まちの変化に柔軟に対応していくということですけれども、壊すことにつながることに関しては、ぜひ区としても文化振興事業団としても、区民の文化芸術を守っていく、魅力的なまちづくりに寄与していくというこの目的を達成する立場で、引き続き運営を進めていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"確認","question":"その上で確認なのですが、指定管理の中で、総合区民会館が、平成２８年、平成２９年、平成３０年、数字が１００万円、３００万円、６００万円と大幅に変わってきている、この辺の要因は何なのかという点と、それから逆に、荏原平塚のほうは、上がり下がりはありますけれども、平成３０年度、平成２９年度、前年度よりも５００万円減ってきている、ここら辺の理由をまず教えてください。","respondent":"古巻文化観光課長","answer":"いわゆる指定管理料が減っているという形です。ＵＮＩＴＥ ＨＥＡＲＴ ＦＥＳＴＩＶＡＬとか、そういった大きなイベントがあった関係で利用料収入が増えて、指定管理料が減っているという流れになっていると認識しております。","voiceIndex":35,"id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問","question":"利用料収入ということで、この後、年度別にどうなっているのですかと聞こうと思ったのだけれども、今の答えだと個別に出ていないという感じがしたのですが、今年度予算の利用料収入２億３,６００万円という額で、そうすると、今、年間の支出２億４,２００万円というのが大体そこら辺の数字を見ているのか。そこら辺も数字が今のとちょっと違うかなという感じがしていたので、後で数字はまた教えてください。","respondent":"古巻文化観光課長","answer":"補助金として３億２,０３５万５,０００円になっておりますので、内訳としては、文化振興事業の補助金として１,６００万円ほどと、いろいろな広報関係が１,６００万円ほど、メイプルセンターが１億１,８００万円、Ｏ美術館、区民ギャラリーが３,９９０万円。","voiceIndex":37,"id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ただ、あの事業は文化振興事業団が後援に入っていて、たしか予算が組んでいる……、まちづくり系のほうの予算ということになるのかどうかわからないですけれども、事務局は文化振興事業団がやったのではないかと私は思ったのですが、違っていたら訂正してもらっていいのですけれども、そこら辺が今の答弁だと気になるのですが。","respondent":"古巻文化観光課長","answer":"そういった形で、今年度、区の執行体制がわかりづらい部分があったので、予算のつき方が予算書に明確にあらわれてきていない部分もあり、文化観光課の内訳には載っておりませんが、全体の中で組み上げて予算を執行しているような状況だという認識です。","voiceIndex":39,"id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"職員数なのですが、この中に品川区で管理職をされていた方が大体毎年何名ぐらいいらっしゃるのか。そして、区から派遣で３人いらっしゃるということですが、これは例えば区の職員の中でそれぞれ役職を持った方がこちらに派遣されているのでしょうか。お聞かせください。","respondent":"榎本総務部長","answer":"区からの派遣職員３人のうち、１人が管理職です。２人は係員で、若い職員です。なので、係長とか、そういう形にはなっておりません。３２名のうち、区のＯＢの管理職については、理事長含むと４名です。","voiceIndex":42,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとお聞きしたいのですが、今言われた方以外の方の採用は、品川文化振興事業団でやっているのですか。それとも品川区で担当されているのですか。","respondent":"榎本総務部長","answer":"事業団の固有の職員については事業団でやっております。それからあと、管理職等については、事業団からの要請を受けて、区で調整をして、配置できるかできないかということがありますので、その辺を調整の上、配置するという形になります。","voiceIndex":44,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"それぞれ、事業団というものが存在しているなら、そこで大半の方はここの事業団で採用している、それにもかかわらず、さらに区からまた正規職員の方をここに派遣するというのは、なぜそういうふうにしなければいけないのか、疑問に思うのですが、その辺について教えてください。","respondent":"榎本総務部長","answer":"何年かしますと区の組織に戻ってもらって、そういう事業の経験を活かした上で、いろいろと活躍してもらうという意味で、期間限定の派遣をしてということで、ずっと文化振興事業団にいるという形ではありませんので、そういう形での派遣の形態です。","voiceIndex":46,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"品川区の中にそういう部署がなければ話は別ですけれども、あるのにもかかわらず、ここにわざわざ派遣して、さらに勉強してこいというのは不思議なような気もするのですが、実際、大半の区の文化振興、観光もそうですけれども、区の部局でそれぞれやっているわけではないですか。そこで何で派遣するのかなと疑問に思うのです。ちょっと不思議な気がするのですが、もう１回ご答弁を。","respondent":"榎本総務部長","answer":"それで、実は係員２名派遣していると言いましたけれども、たしかこの前までは１名だったのですが、なかなか引き継ぎができないということで、たしか最近の要請で２名にしたばかりなのですけれども、行く行くは、人事当局としてはこれを少なくしていきたいと考えていますが。","voiceIndex":48,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"大まか、よくわかりましたが、ややもすると、結局こうやって派遣して、品川区の庁舎の中の職員定数を超えないために、わざわざ外へ出しているような対応にも見られかねないので、私は各事業団でそれぞれ人を育てていただいて、品川区のために尽くしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-022"},{"speaker":"こんの委員","kind":"質問","question":"参考までにお伺いしたいのですけれども、災害時の対応について、文化振興事業団ではどのように災害時の対応、例えば帰宅困難者が出た場合に、きゅりあんだとかスクエア荏原だとか、そうしたところを帰宅困難者に避難所として開設するなんていう場面ももしかしたらあるかもしれない。文化振興事業団として全体であるものなのか。区との連携はどうされているのか。その辺を参考までにお伺いしたいと思います。","respondent":"古巻文化観光課長","answer":"災害時の対応ですけれども、施設といたしましては、まずきゅりあんは帰宅困難者対策におけます一時滞在施設として、区と協定に基づいた施設の開放を行っていただくような形をとっております。","voiceIndex":51,"id":"exchange-023"},{"speaker":"こんの委員","kind":"確認","question":"イメージとして、こことかこみゅにてぃぷらざ八潮とか、こうしたお客様が細かく活動されているところでの対応というのは非常に難しいところがあるかなと思うのですが、そこら辺のところ、細かいことですが、対応マニュアルなどがあって、そこも訓練をされているのか、確認させてください。","respondent":"古巻文化観光課長","answer":"帰宅困難者対策ということで、スクエア荏原ですけれども、こちらは文化観光課それから文化振興事業団だけの考え方で進めていくというよりは、区全体の防災計画の中での位置づけが重要かと思いますので、区の帰宅困難者対策の中で必要なことについて検討して。","voiceIndex":53,"id":"exchange-024"},{"speaker":"こんの委員","kind":"質問・要望","question":"ありがとうございました。確認をすべきところは確認をしながら進めてくださるということですので、区と事業団との関係で、災害時の対応も確認させていただきましたので、より一層確認をしながら、危機管理体制をお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-025"},{"speaker":"大沢委員","kind":"質問・要望","question":"先ほどから文化観光課長がご答弁されてありますが、そもそも文化振興事業団、文化振興なのですけれども、文化振興課長のご答弁というか、ご出席というか、文化振興ではなくて、文化観光の切り口でのやりとりをしていいものか。そこの理由を教えていただきたい。","respondent":"古巻文化観光課長","answer":"文化振興事業団に関しましては、庁内の所管は文化観光課ですので、そういった立場で私が本日出席さていただきまして、ご説明、また、必要に応じて答弁をさせていただいているです。","voiceIndex":57,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"１点、区からの派遣についてやりとりがあったので、確認させていただきたいのですけれども、文化振興事業団に対する助成に関する条例の第４条に職員の派遣というのがあって、区長は事業団の要請に応じ、その業務に従事する者として職員を派遣することができるということが書いてあるのですけれども、これは文化振興事業団からの要請があって送っているということではないのですかというのを聞きたいのと。","respondent":"榎本総務部長","answer":"それから給料につきましては、現役の職員については区で給料を出しております。それ以外のＯＢについては、事業団の職員ですので、事業団が支給するという取り決めになっております。","voiceIndex":61,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6078#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":18439,"voices":66}},{"id":"r01-20191113-18","meetingId":"r01-cm11","date":"2019年11月13日","dateIso":"2019-11-13","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ３時５８分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"先ほど視察の中で、いろいろな話の節々で、組織委員会からなかなか情報が入ってこないという話をよく耳にしまして、そういうところで品川区として、狭間にあったといいますか、どのような形で情報提供していく方向に持っていくのか、お考えをお聞きしたいと思うのですけれども、お願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今回のまちづくりの協議会がいろいろ取り組んでいる内容につきましては、私どもが、区のほうから負担金を出しているということもありますので、いろいろ情報交換をしながら、一緒に進めているところです。","voiceIndex":7,"id":"exchange-001"},{"speaker":"小芝委員","kind":"質問","question":"それは具体的にどのぐらいの人数の職員の方が、どのぐらいの期間で出向、派遣といいますか、されているのでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"たしか１０か１１だったと思うのですが……、１１人です。","voiceIndex":9,"id":"exchange-002"},{"speaker":"小芝委員","kind":"質問・要望","question":"引き続き情報収集に努めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"しながわ文化プログラムの新たな観光まちづくり事業で、寺ｃａｆｅ、宿泊、寺小屋事業などについて先ほど勉強させていただきましたけれども、このほかで品川区で考えている文化プログラムというのはあるのでしょうか。例えば、２６号線のお神輿のように、またお神輿をやるとか、何かそういったものというのはお考えはありますか。","respondent":"古巻文化観光課長","answer":"文化プログラムに関しましては、さまざま、今年度も行っておりますけれども、例えば、しながわ文化プログラムというよりは、国の指定の公認プログラム的なもので言うと、品川薪能がありまして、これは来年度も予定しておりますし、また。","voiceIndex":12,"id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、委員長のほうから、６９件の文化プログラムのご紹介をということでお伺いさせていただきました。逆に、小さい中で、地域から盛り上がっていくオリンピック・パラリンピックというのが、いよいよ１年を切った中で、大事かと思います。数がすぐ出るかどうか、申しわけありません。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"地域として盛り上がりを見せているところがどのぐらいあるかということだと思うのですが、今、具体的な数というのは出ていないのですが、ただ、私どもがしながわ文化プログラムということで認定をしているという、これはイベントごとにしているのですけれども。","voiceIndex":17,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"助成金があるないにかかわらず、その文化プログラムの認定というのはできるかと思いますが、そこはまた地域の盛り上がりというところでぜひ推進をしていただきたいというところと、１つ、八潮地域の中から、八潮地域が今、会場周辺が整備されつつありまして、いよいよ機運が高まってきている反面、実際、会場の周辺は、やはり閉鎖されてしまうということで、閉鎖というか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"もう一つ、８月のホッケーのテストイベントの際には、地元ということで、八潮太鼓の子どもたちと大人の方に演奏していただきまして、非常に評判がよくて、すてきなこけら落としになったというようなお声をいただいておりますので、今後も地域の方にご協力をいただきながら。","voiceIndex":19,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"今日、視察をさせていただきまして、寺ｃａｆｅですとか、宿坊のお話ですとか、いろいろ伺いました。その中で、品川区としてはどのようにかかわっていらっしゃるのか。寺ｃａｆｅのほうでは３００万円、区のほうの予算でやられているということでしたけれども、そこの予算の面と、区としてのかかわりのところで伺えればと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"もう一点の、品川宿の観光まちづくり事業についての品川区のかかわりです。寺ｃａｆｅは、先ほど説明の中で３００万円というお話があったと思うのですが、全体で１,５００万円寄附をいただいたもの、それをそのまま負担金としてお渡ししています。","voiceIndex":23,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"品川宿の取り組みのほうでは、そうすると、お金のほうは１,５００万円、旧東海道品川宿周辺まちづくり協議会のほうに渡してあって、だから、そちらでどう使うかというのは決めていくということになるのですかね。わかりました。実証実験をどうしていくということと、今後、改善して、本格的な事業にしていくということなのか、伺えればと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"モニターといいますか、無料で宿泊をしていただいて、足りないところを聞いたり、もっとこういうところをこうしてほしいですとか、余計なサービスは切ってしまうですとか、そういった作業をしまして、来年度につなげるという予定になっております。","voiceIndex":25,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、区がこの事業にどうかかわっていくかというところは、ご答弁あったのでしょうか。少し見えなかったので、どういう形で実証実験の結果を踏まえて、どうやっていくのかということも含めてなのですが、そういったところをお聞かせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"定期的に相談し合いながらといいますか、まちの会議にオブザーバーで参加することもありますし、こちらには報告に来ていただいているという状況です。","voiceIndex":27,"id":"exchange-009"},{"speaker":"筒井委員","kind":"質問","question":"区としてこうあってほしいというイメージがあれば、教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"しながわ文化プログラムのマークをチラシにつけて、バッジをつけて、みんなで連帯感を持って臨んでいきましょうというような、そんな思いを込めているところです。","voiceIndex":30,"id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。結構幅広く、緩いという言葉も出ましたけれども、では、今まで申請してこられた方に対して、お断りしたとか、そうした断ったケースというのはあったのでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"お断りしたケースは、私が記憶している中ではございません。","voiceIndex":32,"id":"exchange-011"}]},{"id":"topic-02","title":"コロンビア共和国のホストタウン登録","agenda":"コロンビア共和国のホストタウン登録","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ホストタウンになると何が変わるのかというか、何ができるようになるのか、そこを伺えればと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"お墨付きをもらうということが１つと、ほかの地域の方についても、知らしめると言ったら変ですが、大きくＰＲすることにもなりますので、一つ認められたという認識でいていただければと思います。","voiceIndex":38,"id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"品川区が認められたというのは、具体的にオリパラの、パラ・パワーリフティングの視察に行きましたけれども、要は、障害者に優しいとか、いろいろおっしゃっていましたけれども、そういう取り組みが評価されて、品川区が認められたものなのでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ホストタウンに申請するときに登録要件が幾つかございまして、その国との今までのかかわりですとか、交流の実態、それから、東京２０２０大会時の交流の予定、そういったものが認められるところで、まちとしてバリアフリーが進んでいるとか。","voiceIndex":40,"id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"資料の最後のほうに、今後もホストタウンとして事前キャンプ実施の支援を行うとともに、子どもたちや地域住民との交流などを行うことでという予定といいますか、それが書いてありますけれども、今、具体的に何か既に計画されていることとかがあれば、教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"やはり気になる交流のところなのですが、聞くところによりますと、試合前というのは皆さんぴりぴりしているといいますか、なかなか交流は難しいのではないかという話を聞くところもあります。","voiceIndex":42,"id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"選手との交流に関して言えば、選手ご自身の体調とかスケジュールが当然優先されると思いますけれども、よく事前キャンプを誘致したり、そして、ホストタウンになったりすると、そこの地域の人たちがその国への理解をすごく深めていって、歴史とか食べ物とか文化とか、そういうことをすごく深く理解するようになって、もし何か国際試合があったとしても、今回に限らず。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"確かに今回、ラグビーのワールドカップの中でも、子どもたちが国歌を歌ったり、私も見ていてすごく感動して、私もコロンビアの国歌を覚えなければいけないと思っているのですけれども、これは行事に参加できた子どもたちだけではなくて。","voiceIndex":44,"id":"exchange-015"},{"speaker":"つる委員","kind":"確認","question":"今回のコロンビアの件について、まず、財政的な支援、基本、いろいろ交流事業とかはハードとかソフトとか、さまざまなメニューがあるのですけれども、資料を見る限りは、全てにおいて交付税措置ですみたいな形になっていて、そういう意味での国からの財政的な支援というのは、品川区、２３区を含めてそうでしょうけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員ご指摘のとおり、財政的な措置は一切ございません。","voiceIndex":47,"id":"exchange-016"},{"speaker":"つる委員","kind":"質問","question":"当然、ポストオリパラ後とかいろいろとある中で、その辺の継続性というのでしょうか、そういったところを、財政的支援が見えないので、その後について品川区としてどういう方向性が考えられるのかというところと、コロンビア以外に品川区としてホストタウンとして、申請ベースだと思うのですが、それをしているのかどうかというところと、あと。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"品川区としては、事前キャンプを受け入れるのはコロンビアだけですし、事前キャンプをこれ以上受け入れる予定は今のところ、施設的な関係もありますが、ございませんので、そういった方向で今のところ考えているところです。","voiceIndex":49,"id":"exchange-017"},{"speaker":"つる委員","kind":"質問","question":"英語少し通じます商店街でも、商店街で経年でやってきていますし、中国語もやっていると思うのですが、それは別の課だと思うのですけれども、オリパラ課としても、今回こういう形で、当然、他課とも連携しながら、スペイン語をどう区民の方に周知していくか。このあたりについて、予算の関係もあるのかもしれませんけれども、お答えになれる範囲で伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"リーフレットはあるのですが、もちろんそれだけで足りているとは思っておりませんので、どういう形でできるか、また、スペイン語も、なかなかステップ１から学ぶというのも難しいので、簡単な会話のフレーズを覚えるようなことをしてみるですとか。","voiceIndex":51,"id":"exchange-018"},{"speaker":"つる委員","kind":"質問","question":"ですから、学校、いわゆる子どもたち、児童・生徒対象、それから、区民というところでいろいろな機会ができるのかと思いますし、逆に半年間のぎゅっとした期間で、そういう新たな品川区としての１つの国との関係性というのを構築できるいい機会になるのかと思いますし、参考までに、スペイン語というのは、別の機会でもお伝えすることがありますけれども、世界で見れば。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"しかしながら、まだ何日にどの選手が出るかというのが、難しいところなのです。決勝に絶対に行くだろうとか、その辺の憶測といいますか、期待値も込めて用意するというのもあるのかと思いますが、そこのところはこれからいろいろ検討させていただきたいと思っているところです。","voiceIndex":53,"id":"exchange-019"},{"speaker":"つる委員","kind":"質問","question":"細かいところですみません。そのチケットの活用方法というのは、区としては、いわゆる職員の方が行って代表選手を応援するというイメージなのか、それとも、区民に何かしらのタイミングで募集をして、応募いただくのかとか、その辺はベクトルが区民に向けているのか、いろいろそういった都合もあるので、職員とかで代表選手を応援していくのかという、そのあたりがわかれば教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"これはもちろん区民が主役ですので、区民の方向けということで、職員は自分でチケットを応募してということになります。","voiceIndex":55,"id":"exchange-020"},{"speaker":"つる委員","kind":"質問・要望","question":"わかりました。ぜひまた迫ったら、いろいろ細かいところは伺っていきたいと思いますが、当然、その際は、チケット代などというのは、無償とか有償とかいろいろ判断はあるのでしょうけれども、区民にとって一番いい形で参加できる機会にしていっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6564#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":17749,"voices":59}},{"id":"r01-20191115-10","meetingId":"r01-cm11","date":"2019年11月15日","dateIso":"2019-11-15","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"東京都後期高齢者医療広域連合議会の報告","agenda":"東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"鈴木（真）委員","kind":"意見","question":"１１月８日に令和元年第２回東京都後期高齢者医療広域連合議会の定例会にかかわる議案説明会および保険料説明会が行われました。それから、平成３０年度決算が示されました。差し引き３,９６０億円ぐらいの黒字になっております。これもまた変わってくるのではないかということと、診療報酬がどう改定されるかによって保険料が変わってくるのではないかということの案内までは出ております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"確認というより意見ですけれども、後期高齢者医療の保険料の値上げについては、本会議で反対をしていただきたいと述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5334#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":7097,"voices":29}},{"id":"r01-20191127-10","meetingId":"r01-cm11","date":"2019年11月27日","dateIso":"2019-11-27","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"東京都後期高齢者医療広域連合議会の報告","agenda":"東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"１１月２１日に東京都後期高齢者医療広域連合議会、全員協議会と本会議がありました。全員協議会は事前の説明がありまして、本会議におきましては、一般質問が３人から、その後、副連合長の選任同意、これは全会一致です。その後に条例改正、これは会計年度任用職員の関係、それから地方公務員法および地方自治法の改正に伴う関係条例の整備ということで、この２件も全会一致で賛成でした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"前回、後期高齢者医療保険制度の保険料値上げには反対していただきたいと意見を述べさせていただきましたが、一般会計と特別会計についてどのような態度を示したのかということをお聞かせいただきたいのと、保険料値上げにはぜひ反対していただきたいと改めてお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5336#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":7564,"voices":29}},{"id":"r01-20191128-9","meetingId":"r01-cm11","date":"2019年11月28日","dateIso":"2019-11-28","committee":"文教委員会","time":"午後 ４時５０分～午後 ５時０８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"最初の確認で、労使の妥結はされたということでいいのかということです。","respondent":"工藤指導課長","answer":"労使の妥結はされたところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"先ほど、少し説明がありましたけれども、本年４月からの公民較差の相当分に関する調整措置は行わないということで妥結をされたということですが、その案といいますか、経緯などがありましたら伺えたらと思います。勧告と違うことになった理由を伺えればと思います。全体的に見ると、職員の方はプラスになるのか、マイナスになるのか、そこを伺いたいと思います。","respondent":"工藤指導課長","answer":"３点ご質問いただきました。妥結のところですが、労使交渉の部分で私どもが伺っているところで言えば、特別区長会では、昨年度も勧告を見送ってありますので、基本の考えの中には２年続けて見送るということについての議論はあったというふうに伺っているところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"塚本委員","kind":"質問","question":"１つだけ。公民較差というところで、幼稚園教育職員に関しては特別区人事委員会勧告によって公民較差が調整される。もう１つ、学校教育職員においては、東京都人事委員会勧告によって公民較差、これは極めて小さかった。この２つ、同じ公民較差と称しているけれども、出てくる数字が違うというところがなぜなのか、というところのご説明だけお願いします。","respondent":"工藤指導課長","answer":"つまり、とり方と、あとは給料表そのものが違っている、職層も違っている部分が合っていないために、仮に同じ民間事業者等を選んだとしても差が出てくるということになってあります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"塚本委員","kind":"意見","question":"そういう選び方の考え方みたいなものが、ちょっと所管を超えてしまうかもしれないですけれども、何かご答弁というか、何かコメントをいただければ、もう１回お願いしたいと思います。","respondent":"工藤指導課長","answer":"そういったことを今年は抜いている、抜いて調整した。公民較差で調べた結果が先ほど申し上げた引き下げの分だということになったと伺っています。そういう意味では、民間事業者をどうとるかというのも引き続き検討しながらというところで意見で伺っているところはあります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"筒井委員","kind":"質問","question":"ここだけパーセンテージの記載になっているのは、どういったことなのでしょうか。同じように合わせるとマイナス２,２３５円という……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"筒井委員","kind":"質問","question":"ほかの議員とか区長はマイナスの数字、マイナス５,０００円とか書いてあるのですけれども、ここだけマイナス０.５８％にした理由は何が。パーセンテージにした理由をお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"筒井委員","kind":"意見","question":"消費税が増税されまして、区民生活にも悪影響が及び始めている状況の中で、通常の給与がマイナス２,２３５円。下がったとはいえ、期末手当の分が増えている。トータルで平均２万２,０００円の増加が行われるということについては、やはり区民生活等々のことを考えれば、ふさわしくないということで、反対をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4984#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":5215,"voices":40}},{"id":"r01-20191128-5","meetingId":"r01-cm11","date":"2019年11月28日","dateIso":"2019-11-28","committee":"総務委員会","time":"午後 ４時５０分～午後 ５時３８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"時間その他の勤務条件に関する条例の一部を改正する条例、(4)第１０７号議案 品川区監査委員の給与等に関する条例の一部を改正する条例および(5)第１０８号議案","agenda":"時間その他の勤務条件に関する条例の一部を改正する条例、(4)第１０７号議案 品川区監査委員の給与等に関する条例の一部を改正する条例および(5)第１０８号議案","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"初めに、１０８号議案の職員の給与に関する条例、前回の総務委員会でも人事委員会勧告の報告でやりましたが、労使が妥結したということで、そこを尊重したいと思います。お伺いしたいのは、１０４号、１０５号、１０６号、１０７号、区議会議長、区長、副区長、教育長、監査委員ということになりますが、ベースは下げるものの期末手当の引き上げで年収ベースでは給与の引き上げという中身になると思います。","respondent":"立川総務課長","answer":"答申のみならず、当然、社会経済情勢、また他区の状況、国の状況、東京都の状況等を勘案いたしまして決定しているものです。今回の決定につきましては、それらを総合的に判断して決めたものです。","voiceIndex":6,"id":"exchange-001"},{"speaker":"中塚委員","kind":"意見","question":"改正には総合的な判断ということでありますが、この答申の「おわりに」の中でも、特別職の報酬は区民の理解を得られるものでなければならない。こうした背景や現在の社会情勢への配慮、また２３区も含めてということが書かれておりますけれども、やはり今の社会、そして経済状況を見るならば、年間ベースで引き上げを行うことはふさわしくないと意見を申し上げたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"１０８号議案のところでまず１点確認したいのですけれども、来年から始まる会計年度任用職員に、この条例が適用されるのか。適用される場合は、期末手当もこの条例に沿った形となるのか、その部分を確認させてください。","respondent":"黒田人事課長","answer":"今回は勤勉手当に割り振りをしておりますので、期末手当の月数は変わってございませんので、そういった意味でも会計年度任用職員の期末手当の支給月数は特に変更はないところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"確認したいのが、会計年度任用職員が連続して働いた場合に、１年間で見直しというか、あるではないですか。１２月の期末手当は半年分が適用されると思うのですが、会計年度任用職員が連続して働く場合に、１から３月に働いた分が６月の期末手当に反映されるのか、その部分を確認させていただきたいのですけれども。","respondent":"黒田人事課長","answer":"会計年度任用職員につきましては、この４月から新たな制度が始まることになりますので、来年の６月の期末手当の支給につきましては、４月、５月の勤務の実績に基づいて６月１日基準で支給されることになりますので、その前の分につきましては制度がございませんので。","voiceIndex":11,"id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"ありがとうございました。引き続き、第１０５号議案のことです。確認ですけれども、品川区長および副区長の給与および旅費条例の一部を改正する条例ですが、これは区議会議員の期末手当と連動をするのか確認をさせてください。連動するのであれば、その理由をお知らせください。","respondent":"立川総務課長","answer":"いわゆる条例のつくりとしまして、まず、区長、副区長、教育長を念頭に、期末手当の月数を具体的な数字として定めております。議員の報酬等の条例につきましては、期末手当については、区長等の期末手当の月数に合わせるという、そういった条例のつくりです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"田中委員","kind":"意見","question":"第１０４号議案、品川区議会議員の議員報酬、費用弁償及び期末手当に関する条例の中で、期末手当のことが記されていないです。条例を見たときに、期末手当が上がる仕組みというか、区長および副区長の期末手当と、連動しているのですよね。","respondent":"立川総務課長","answer":"品川区議会議員の議員報酬、費用弁償及び期末手当に関する条例の第６条第２項におきまして、期末手当の額は、それぞれの基準日現在における第２条に定める議員報酬の月額およびその議員報酬の月額に１００分の４５を乗じて得た額の合計額に。","voiceIndex":15,"id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"月額がこういうふうに下がる。それぞれ一生懸命働いている区の職員の方、それから教員の方、さまざまいらっしゃいますけれども、それはわかります、わかりますけれども、我々は区民から区政を任されて、各議員は監視しているという状況で、区内の経済の実態、区民の実態が悪い中で、トータルでこうやって上がっていくというのは、ちょっと問題があるのではないかと、我慢してほしいというのが私の気持ちです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"聞きたかったのは、なぜ期末手当がここに連動してしまうのか、そういうつくりになってしまうのかということを伺いたかったのです。そこをお知らせください。","respondent":"立川総務課長","answer":"議員の報酬に関しては、これまでいろいろな歴史的な展開の中で決められてきたというところだと思うのですけれども、期末手当の額について議員と区長、副区長等をどうするかといったところで、いろいろ職責であるとか、勤務実態であるとか、その辺を総合的に勘案したときに。","voiceIndex":19,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"その歴史的経緯という具体的なものが知りたくて、以前、２０１７年のときにも、生活者ネットワークは歴史の経過の中身を聞きたいということを言っています。歴史的経過が示されないというか、具体的にちゃんとお示しいただきたいと思うのですが、伺います。","respondent":"榎本総務部長","answer":"それで、職員の例によるではまずいので、区長の例によるという形での規定を定めたというものです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"区議会議員と区長、副区長は、特別職だとしても、また別物だと思うのです。ですので、区議会議員に対する条例があるので、今、改めて連動が必要か考えるべきなのではないかということは思うのですが、そのところはいかがでしょうか。言い方はあれですけれども、ですので、きちんと分けていただきたいというか、検討をいただきたいのですけれども、そこについてお答えいただければと思います。","respondent":"榎本総務部長","answer":"職員の例によるから区長の例によると変えたときも、議会のほうにお諮りした上でそういう形に変えていいかということをお聞きした上でやっていますので、これについてはまた今後、別のしかるべきときに検討していきたいと思います。","voiceIndex":23,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"特に３番と４番については、これは何だろうというところがあります。なので、本当は何ですか、何のために今回やるのかというのが、この答申を見ると、そういう疑問があります。５区だけが特別区人事委員会勧告に準拠するということになるのです。なぜ品川区は準拠しなければならないのかということです。だから、どこに根拠を持ってやっているのでしょうかということをお聞きしたいのです。","respondent":"立川総務課長","answer":"それで、報酬等審議会がなぜ開かれるのかということを説明しますと、昭和３９年５月に自治事務次官通知がございまして、このときに特別職等の報酬を決める場合は、それまでは、当然、各地方公共団体が議会の条例をもって定めていたのですけれども、どういったことかというと。","voiceIndex":25,"id":"exchange-011"},{"speaker":"西本委員","kind":"意見","question":"昭和３９年のということでありましたけれども、この後ろのほうに審議会のメンバー表があります。ほとんどが知っている方なのですが、別にその人それぞれを評価する必要はないと考えています。いろいろなご意見をいただき決めていただいているというふうに思いますが、ここには、専門的な方がいらっしゃるのか、それと、この人事委員会勧告に対しての考え方は、審議会としてどう捉えているのかというか。","respondent":"立川総務課長","answer":"審議会として、人事委員会勧告をどう捉えているのかですけれども、答申内容から推察いたしますと、やはり特別職の給料等を決定するときの指標としては大変に重要なものだというふうに考えているのではないかというふうに推察しています。","voiceIndex":27,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"そもそも人事委員会勧告でのもともとの計算式といいますか、調査といいますか、それがどうなのかという評価もあると思うのです。それを大もとのところがどうなのだといったところで、それを目安にしてこの審議会が議論するということになっても、それで右へならえみたいな状況になってしまうのかというふうに思うのです。区民の人たちは、よりちゃんと仕事をしてくれればいいと思うのです。意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-013"},{"speaker":"中塚委員","kind":"意見","question":"反対したいと思います。厳しい社会経済状況を見るならば、年収ベースで給与を引き上げるということは行うべきではないし、区民の理解も得られないと思うからです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-014"},{"speaker":"須貝委員","kind":"意見","question":"私も同様で、年収ベースで考えると、今回、トータルで上がるというと収入が増えるということなので、区民の生活実態等を考えますと、やっぱり区民の理解が得られないと思いますので、反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-015"},{"speaker":"西本委員","kind":"意見","question":"賛成です。先ほども申し上げたとおり、ただ単に金額が上がった下がったという議論にはあまりしたくないのです。なので、今回の改正はいろいろな状況を鑑みて賛成という形にしたいと思いますが、もっと深い意味で議論できたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-016"},{"speaker":"中塚委員","kind":"意見","question":"反対したいと思います。理由は、同じく厳しい社会状況、経済状況を見るならば、年収ベースで引き上げを行うことはすべきではないし、区民の理解も得られないと思うからです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-017"},{"speaker":"須貝委員","kind":"意見","question":"私も同様で、今、区内経済状況が悪かったり、それぞれ区民の年収が増えていない中で、年収ベースで引上げを、こういう条例が議案に出たのですが、区民の理解が得られないと思いまして、私も反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"反対します。そして、先ほども質問しましたが、連動が必要かどうか改めて検討していただくよう、強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-019"},{"speaker":"つる副委員長","kind":"質問・要望","question":"そういうところでは、公民較差の部分でしっかりと評価していくというのが一方でそれはそれで人材確保の観点でも、当然福祉サービスを低減させるわけにはいかないので、そういった部分でも大事なお給料というところでは、そういう視点の評価は必要だと思いますが、見合うということではなくて、それ以上の仕事をしていくという気概をしっかり持っていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-020"},{"speaker":"須貝委員","kind":"意見","question":"私は、やはり民間と公務員の皆さんとの所得格差が拡大する中、このたび年収ベースが上がるということ、これに対しては反対だということ。職員の皆さんには、一生懸命職務はやっていただいているのですが、私は我慢をしてほしいというふうに思います。今回、この議案に対しては反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2150#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":13395,"voices":77}},{"id":"r01-20191129-10","meetingId":"r01-cm11","date":"2019年11月29日","dateIso":"2019-11-29","committee":"議会運営委員会","time":"午前 ９時３０分～午前 ９時３５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5338#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":1880,"voices":8}},{"id":"r01-20191202-6","meetingId":"r01-cm12","date":"2019年12月2日","dateIso":"2019-12-02","committee":"区民委員会","time":"午前１０時００分～午前１１時５５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和元年請願第２１号 選択的夫婦別姓制度の国会審議を求める意見書を国に提出することを要望する請願","agenda":"令和元年請願第２１号 選択的夫婦別姓制度の国会審議を求める意見書を国に提出することを要望する請願","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"私はこの別氏制を導入していただきたいなという考え方に立っている者ですが、一つここに書いてあるとおり、この違憲としなかった、合憲だというふうにした、この２０１５年の判決自体が、国会で論じられ判断されるべきことにほかならないとしているにもかかわらず、国会での議論が進んでいないということで、この国会で議論を進めてほしいというふうに、この請願はなっているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-001"},{"speaker":"くにば委員","kind":"意見","question":"私自身がそれをしたいかどうかと言われれば、私はしたいとは思わないのですけれども、ただこれは、国民として選択をする権利というのはあってしかるべきだなとは思います。ですので、あくまでオプションというか、それぞれの方々が選ぶことが不自然ではないというのは、世界でのスタンダードの考え方ですので、私はそれに沿った形で、こちらの請願に関しては採択をしたいなというふうに考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"藤原委員","kind":"確認","question":"１点だけ確認したいのですが、この請願で下のほうで、東京都内では６区１４市が意見書の採択、ということと、全国自治体レベルでは合計３１件の意見書提出に至っています、という数字的なものは間違いないのでしょうか。","respondent":"提坂戸籍住民課長","answer":"全国でも１９議会で意見書を可決したり、請願が採択されたという内容でした。","voiceIndex":9,"id":"exchange-003"},{"speaker":"藤原委員","kind":"確認","question":"今、課長の答弁で、都議会と出ましたが、確認だけなのですけれども、東京都議会も採択をしているということで、確認。","respondent":"提坂戸籍住民課長","answer":"委員のご質問のとおりです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"こんの副委員長","kind":"意見","question":"我が会派も継続をお願いしたいと思います。国会で実は、公明党もこれを推進をしておりますので、品川区としてお受けするのであれば、全会一致を目指すということが一つ大事かなというふうに考えるところから、もう少しこれをやはり、議会で深めていく時間が必要ではないかと思うところから、継続をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-005"},{"speaker":"藤原委員","kind":"意見","question":"私のところも会派でこれは激論をしたのですけれども、継続でお願いいたします。理由としては、今、こんの副委員長がお話ししていただいたとおり、議論を深めていくという意味において、今回継続でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-006"},{"speaker":"くにば委員","kind":"質問","question":"今、こんの副委員長の話を聞いて、確かに私は、先ほどのそのお話を伺うまでは、その推進ということで採択を目指したいかなと思っていたのですけれども、なかなかやはり、それはなぜかというと、さまざまな党派によって考え方があって、なかなか全会一致というのは難しいのかなというふうに思っていた部分、なかなかやはり、どうして決まらないのかなと思った部分もあったのですけれども、ただ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"くにば委員","kind":"提案","question":"私のほうから幾つかお伺いしたいことと、あとはご提案したいことをお話しします。はその３言語というか、もちろん中国、韓国、香港、台湾、これが７５％を占めるわけですから、まずはこの４言語プラス英語という形でここに絞って、いかに多くの店にこの４言語それぞれのメニューを置いてもらうかというのを、区のほうで積極的にさらにその導入をしていただくための施策をしてはいかがかなと。は２点目。","respondent":"山崎商業・ものづくり課長","answer":"そうしたいろいろな手法を使って、まずは来ていただいて、来ていただいたら入りやすくする店頭の工夫というような、そういう段階的に対応してまいりたいなというふうには考えております。","voiceIndex":26,"id":"exchange-008"},{"speaker":"くにば委員","kind":"質問・要望","question":"１０４の商店街の中で実際に取り組まれているのが４０の商店街ということで、もちろんそこに関しても徐々に広がっているとは思うのですけれども、そこも本当に、まさに来年に向けてという、一気に加速をしなければいけない部分で、なかなか難しいとは思うのですけれども、どうやったらいわゆるその、旧態依然というふうな見方をしてはあれですけれども、なかなかそのインバウンドはうちは難しいよ、みたいな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"せっかくこのレコメンドメニューを書いてあるわけですから、為替があるから円でいいので、推薦するメニューぐらいは値段を書いてくださると、すごく安心してそのお店に入れると思うので、それはいかがかというのが１点。商店街の推薦かもしれませんし、どういう形でやったのか、教えていただけますか。","respondent":"山崎商業・ものづくり課長","answer":"今ご覧の冊子につきましては、３年計画の事業の当初でしたので、商連のほうに委託をして、いろいろ商連と区のほうで打ち合わせをするときに、全商店街の方々を対象にいろいろ、来年の事業の説明会などをしたときに、ちょうど平成２８年度の末に。","voiceIndex":29,"id":"exchange-010"},{"speaker":"藤原委員","kind":"質問・要望","question":"１０％ぐらいでいいのかな、今は２０％だろうとか、いろいろあるではないですか。ずっと海外の方から来ていただきたいという思いで仕事はしていると思うので、その辺のちょっと細かい話になってしまうのですけれども、やはり現場の方たちが一番接しているわけですから、そういうのはうまくやっているのですよ、ということであるならば、その辺についてはもう全然心配することはないと思いますので、１点です。","respondent":"山崎商業・ものづくり課長、遠藤協働・国際担当課長","answer":"そういう中の一つでいろいろ今後しっかり研究なり検討してまいりたいなというふうに考えてあります。私のほうから、英語少し通じます商店街のほうについてご説明します。","voiceIndex":31,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"最後に、東京オリンピック・パラリンピックが来年開催されますが、そのときに外国の方がたくさん多く来られるということは私も十分承知はしているのですけれども、それでいわゆる都市型観光といいますかインバウンドが終わるわけではないので、来年は開催の年かもしれませんけれども、でも海外のお客様をお迎えするという意味においては、私はずっと続くと思っていますし、この施策として海外の方への。","respondent":"古巻文化観光課長","answer":"今、委員からご指摘ありましたとおり、来年は東京オリンピック・パラリンピックの大会があるということで、それに向けたいろいろな取り組みをしているところではありますけれども、それはあくまでも来年だけのためではなくて、一つのきっかけとして、来年やはり。","voiceIndex":34,"id":"exchange-012"},{"speaker":"おくの委員","kind":"意見","question":"こういう働きかけを区のほうからやっていらして、商店街の方自身のお気持ちがそういうふうにどれほど傾いてきていらしたのかという、そこら辺のことを大ざっぱなご感想でもいいのですけれども、ちょっとお教えいただければと思います。","respondent":"山崎商業・ものづくり課長","answer":"外国の方が来るのであれば、外国の方というのはなかなか対応したこともないし、できるのであればそうしたことができるほうがいいよね、というような順番なのです。","voiceIndex":36,"id":"exchange-013"},{"speaker":"おくの委員","kind":"質問","question":"今、率直なお話として、売り上げが増えればいいのだ、儲かればいいのだ、という言い方はあれですけれども、たとえ相手が外国人であれ国内の人であれ、ということで、それは当然そういうことだろうと思うのですけれども、外国人にターゲットを絞った事業ということなのですが、その外国人にターゲットを絞った事業がその売り上げを伸ばすことにとってものすごく重点を置く価値があるのであれば。","respondent":"山崎商業・ものづくり課長","answer":"オリンピックなどを契機としまして、本件事業についてはまずコンセプトをつくってきたのは事実でございまして、そのターゲットを外国人の方に対してのおもてなしといいますのは、身近な区民の方々にとっても。","voiceIndex":38,"id":"exchange-014"},{"speaker":"湯澤委員","kind":"質問","question":"このおもてなしガイド、本当にすばらしいものだと思います。これはもう既に配られているものですか。","respondent":"古巻文化観光課長","answer":"こちらのおもてなしガイドにつきましては、既に各商店街に商連を通じて配っておりますので、なのでちょっと在庫がなくて、こういう資料の形になっております。","voiceIndex":40,"id":"exchange-015"},{"speaker":"湯澤委員","kind":"意見","question":"ぜひ、これからこういったものを必要とされる方、多々いると思うのですが、例えば全席禁煙ですと言われたときに、ではどこでたばこを吸えばいいんだとか、あと、店の前に自転車をばーっととめてしまうという方がいたときにとか、あとはお酒を飲むのも国によって何歳からとかというので、お店によってはいろいろな意見があると思いますので、そういった意見などというのを今後また、どういった意見があって。","respondent":"古巻文化観光課長","answer":"おもてなしガイドにつきましては、とりわけ改訂の案というところは今のところ具体的にはないのですけれども、こういったような形のもの、またいろいろ工夫をして出していきたいなというふうには考えておりますので、ここでいただいたご意見を参考にさせていただいて。","voiceIndex":44,"id":"exchange-016"},{"speaker":"湯澤委員","kind":"質問・要望","question":"もうおっしゃるとおりで、商店街の方々の意見でやっていることはもう重々承知なのですけれども、やはりそういった一部の方の意見もあるということは確認していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-017"},{"speaker":"木村委員","kind":"質問・要望","question":"それをいかにして、今回のこの受け入れのことに対してですけれども、それプラス、今度はそれを発信する。１人でも多くの海外の方々に、世界の方々にそれを、商品を発信、品川区ではこういう商品がありますよ、ということを発信していかなければいけないのではないかなと考えています。そういう考えというものはないかな、あるのかどうかということをお聞かせいただきたい。","respondent":"古巻文化観光課長","answer":"「品川達人」という形での冊子もつくっておりますが、そういった形の、そういった紙媒体での発信もどんどんやっていきたいなというふうに考えております。","voiceIndex":47,"id":"exchange-018"},{"speaker":"木村委員","kind":"質問・要望","question":"そのためにもぜひ、英語圏の方々ももちろんですけれども、本当に一番身近にある韓国や中国、そういうところとの絆をもっともっと今以上にしっかりと結ぶべきではないかなと思っています。そういう何か、韓国、中国に対しての品川区からの狙いというかＰＲの仕方、何かあれば教えていただきたいなと思います。","respondent":"古巻文化観光課長","answer":"インターネットだけではなくて、紙であったりとか、直接の、例えば観光案内所、東京都でありますとか国がやっている観光案内所、そういったところに冊子を置かせてもらったりといった形で、品川区をより知っていただくといった試みといいましょうか。","voiceIndex":49,"id":"exchange-019"},{"speaker":"松澤委員","kind":"質問","question":"答弁ありがとうあります。指さしで示せるフレーズや、英語がしゃべれない日本の方でもいろいろなそういう準備をされていて、すごくすばらしい取り組みだと考えています。ちょっとお聞きしたいのが、この謎解きウォークやえばら観光フェア、こういうものというのは、実際はどなたが中心でやられているのでしょうか。","respondent":"古巻文化観光課長","answer":"えばら観光フェアは、これは品川区の主催ですので品川区としながわ観光協会、そちらがメーンになって、今のところ組み立てをしているというようなところになります。","voiceIndex":51,"id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"そういった部分で、先ほどありました１０４の商店街のうち、こういうことに加盟してくれるのが４０ぐらいの商店街というのがあるのですけれども、やはりその４０の商店街をさらに増やすために、品川区としてはではどういうふうにやっていくのかという施策みたいなのというのは考えているのでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"それぞれの商店街の方は、商店街の属する賑わいイベントもかなり品川区は活発に行っておりますので、その商店街としてのイベントと、都市型観光のイベントと、やはり単一のものと複合的なエリアのものと。","voiceIndex":53,"id":"exchange-021"},{"speaker":"こんの副委員長","kind":"質問","question":"国際友好協会のこの日本語教室参加者アンケートというところをまず、参考までにお聞きしたいと思うのですけれども、外国人の方からの、その気づきの声というのはどんなお声があるのでしょうか。参考までにちょっとお聞きしたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"ということで、重複するのですけれども、何かしら判断をするきっかけになるようなこととは何なのだろうな、というようなことを、最初のそういった話し合いでヒアリングのときにはそこが１つと、やはりお店に入られると。","voiceIndex":55,"id":"exchange-022"},{"speaker":"こんの副委員長","kind":"意見","question":"その課題をどうするかという話と、その手前のところの課題というのは、どんなものが挙がっているかというのがもしあったら、想像するに、まずはその商店街に、観光資源として来ていただく、この動線、どんな感じの商店街の雰囲気にしておくと、外国人の方が喜ばれて、行ってみたいなと思われるのか。その辺の声は何かありますか。","respondent":"山崎商業・ものづくり課長","answer":"最近、いろいろ商連などと本件のようなことを検討するときに、周辺の商店街に加盟している、例えば安いビジネスホテルなどの方々も、やはり空港が近いので、大体午前中ぐらいの時間をどこかで、要は最後に使って羽田に行きたいという、ショートトリップというのですか。","voiceIndex":57,"id":"exchange-023"},{"speaker":"こんの副委員長","kind":"質問","question":"そうすると、その辺をどういうふうに、人を起用しながらそこに当てていくかというのは非常に課題だというふうには思うのです。そんなところで、いろいろなイベントをされているのですけれども、日本の歳時期に特化した何かイベントというのはこれまであったのでしょうか、されたのでしょうか。ないのであれば、こんな考え方、今言ったようなものはどうですかというところなのですけれど、いかがでしょうか。","respondent":"山崎商業・ものづくり課長、古巻文化観光課長","answer":"夏祭りから始まって秋のちょうどこのぐらいの時期までがすごくピークで、毎週いろいろな商店街のほうで大きなイベントが繰り広げられるというところでは、そうした四季の季節感に応じて、ということですが。例えばえばら観光フェアでは和文化体験でのイベントということもありますので、確かに四季折々という発想というのは日本の季節感を大事にする日本の文化の一つのあらわれかなというふうに思いますので。","voiceIndex":59,"id":"exchange-024"},{"speaker":"こんの副委員長","kind":"質問","question":"なので、その辺のところを、例えば品川区には企業がたくさん来てくださっておりますので、そうした企業がイベントで一緒に応援をいただくような、連携というのでしょうか、そうした協力といいましょうか、そうしたところは今現状、どうなっていますでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"企業の敷地、そこを利用する形でイベント会場に供するとか、商店街のイベントだけではありませんが、防災訓練などに資するような、地域に溶け込む企業の社会貢献の活動の一つとして、商店街と組まれて、というような事例は幾つかあります。","voiceIndex":62,"id":"exchange-025"},{"speaker":"こんの副委員長","kind":"質問","question":"商店街にそもそも位置する企業は確かに一緒にやろうという、そうした動きは考えられると思うのですけれども、あえてそういう商店街ではないところで起業されている企業たちには、あえてこういう品川のイベント、社会貢献というところで「企業さん、どうですか、やりたい人」みたいなお声がけというのもあってもいいのかなと思うのですけれど、その点はいかがですか。","respondent":"山崎商業・ものづくり課長","answer":"五反田のいろいろな新進気鋭の企業の中には、よく食べ物の飲食店も含めたサービスをアップするような、食べログとか何とかで、ああいったものに類した企業がすごくたくさんあって、そういうアイテムを使って。","voiceIndex":64,"id":"exchange-026"},{"speaker":"松澤委員","kind":"質問","question":"今副委員長からもありましたけれど、企業連携で一つあって、タクシー会社はどうなのかなと思っていまして、なぜなら、私は余り海外に行ったことがないのですけれど、よく地方に行くと、要はタクシーの運転手に聞けば何でもおいしいのを知っているし、情報が一番あるのがタクシーだ、みたいなことをよく言われる中で、タクシーはすごくいい情報伝達、何というのですか、そういうのがすごく。","respondent":"古巻文化観光課長","answer":"タクシー会社との連携は、というようなご提案だったと思いますが、直接今、すぐに何かやっているわけではありませんけれども、貴重なご意見ということで参考にします。","voiceIndex":66,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2852#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":35422,"voices":83}},{"id":"r01-20191202-7","meetingId":"r01-cm12","date":"2019年12月2日","dateIso":"2019-12-02","committee":"厚生委員会","time":"午前１０時００分～午後 ０時３９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和元年陳情第５０号 卒後の壁～障害者のいる家族が働き続けることができるよう支援を求める陳情","agenda":"令和元年陳情第５０号 卒後の壁～障害者のいる家族が働き続けることができるよう支援を求める陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この陳情では、品川区の障害者サービスでは、フルタイムで親が働き続けることができないという訴えです。９月の陳情でも、日中一時支援を障害者まで拡大してほしいという要望が出されていました。親が継続して就労し続けられるようにすることが必要だというところで、そういう考えでサービスを拡充することが必要だというところで考えられているのかということについて、まず伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"障害者のいるご家族が働き続けられるためのサービスというのが必要かどうかについての区の考え方ですけれども、当然ながら、ご本人やご家族を支えていくというのは、区として必要なことだと認識しております。","voiceIndex":6,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのときに、親御さんと当然話し合いをして、親御さんの状況とか、親御さんの要望というのはつかんでいらっしゃるのではないかと思うのですけれども、そういう点では、実態がどうなっているかというのは、アンケートをとるまでもなく、おおよそつかまれているのではないかと思うのですが、私は、やむなく仕事をやめざるを得ない、また。","respondent":"松山障害者福祉課長","answer":"品川区の現状というご質問です。品川区の現状につきましては、先ほど陳情の説明でも申しましたように、指定特定相談支援事業所の相談員が、ご本人とご家族から事情は十分にお伺いしております。","voiceIndex":8,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"就労継続Ｂでは、９月の陳情審査のときは、課長が、預かっている実態があると聞いているということで、この陳情にも書かれているのですが、そういう答弁だったのですけれども、今回の陳情で実態がないということで書かれているのですが、実態はないというふうに、障害者福祉課の職員に確認したところ、親の就労による延長サービスはないということでしたということで書かれているのですけれども。","respondent":"松山障害者福祉課長","answer":"したがいまして、何度か陳情者の方からご質問を受けているときに、こちらのほうのお答えが、各法人や各施設によってかなり個別性やばらつきがありますので、区として一律にやっているものではございませんので。","voiceIndex":10,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めて、実態がそういう状況で、少しずつ拡大されてきているというものもあるのかと思うのですけれども、実態がそこまで明らかになってよかったと思うのですが、そういう点では、拡大が各事業所で午後７時まで預かってくれるということになれば、かなり就労継続ということが保障されていくようになると思いますので、ぜひこれは区のほうからも働きかけていただいて、特に生活介護では加算がついて。","respondent":"松山障害者福祉課長","answer":"就労継続支援Ｂ型におきましては、就労継続ということは、実際に就労ということなので、就労後のお預かりの時間ということになりますと、働くということではないというふうにもなりますので。","voiceIndex":12,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、そういうところでは、今までの価値観等、年代によって随分変わってきているということに対しての対応というのがすごく求められるのではないかと思うのですけれども、そういうところで、就労というのは、障害を持つ子どもの親御さんの就労というところも、やはり親が働くことを権利として保障するという考え方でサービスを整えていくということはすごく大事なことなのではないかと思うのです。","respondent":"松山障害者福祉課長","answer":"そのため、本当に個別に対応が異なるものです。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私は、高齢者と同じような形で障害者もそこまでの仕組みにするべきではないかと思うのですけれども、その点は、仕組みとしてどうなっているのかについてもお聞かせください。","respondent":"松山障害者福祉課長","answer":"なかなか一人ひとりのご希望に沿って、ドア・トゥー・ドアまで行けるかというと、またそれはそれで合わせた車両、複数の車両を用意し、合わせたドライバーを複数用意しないと、なかなか難しい仕組みになるのではないかと、現実問題としてあります。","voiceIndex":16,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"もう一つなのですけれども、この陳情で言われているのが、品川区の移動支援が通所には利用できませんということで書かれていて、改めて厚労省の障害者等の移動支援についてという資料を見ましたら、各市町村の判断でかなり柔軟に実施してよいということで書かれていまして、通年かつ長期にわたる外出というのは、品川区の場合認めていないと思うのですけれども、そういう例も挙げられていて。","respondent":"松山障害者福祉課長","answer":"やはりどうしても利用者の状態にもよりますので、個別に柔軟に対応していきたいと考えています。","voiceIndex":18,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"実際に慣れるまで３カ月から６カ月可能ということで、実際に使われている方というのは結構いらっしゃるのでしょうか。それから、時間も……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"まとめますね。長くなってしまったので、まとめたいと思うのですけれども、この陳情には、卒業と同時に区外に引っ越さざるを得ませんと書かれているのです。それで、区外で就労が継続できる支援が進んでいるという区はどんな対策がとられているのか、地域生活支援事業で就労保障として移動支援を行っている区というのはあるのか、その点についてもお聞かせいただけたらと思います。","respondent":"松山障害者福祉課長","answer":"特別区の課長会におきましても、皆さん、できる限り、品川区と同様で、例えば、大人バージョンの日中一時支援をつくり始めた区、あるいは品川区のように、生活介護の延長で対応している区等々ありますけれども、情報交換した中では。","voiceIndex":22,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"何点か伺いたいと思いますが、この陳情中で、一度課のほうに問い合わせをしたら、対応していないというお答えがあったということで、そのことも、この陳情が出てくる背景にあるのかと思います。できれば、それを各事業所ではこういうサービスをしているということを、ホームページなのか、パンフレットなのか、わかる形にまずはしていくべきだと思うのですが、そのことについていかがでしょうか。","respondent":"松山障害者福祉課長","answer":"それぞれの延長対応につきましては、非常に個別性が高いという認識をしております。","voiceIndex":25,"id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"発信というのは、多分、２段階目だと思うのですけれども、その前の、課としての把握もできていないからこういうやりとりになっているわけですよね。だって、お問い合わせいただいたときには、これはお答えしていない。そういった意味では、やはり一定のことはしているということは、何らかの形で工夫して発信していただきたいと思います。その点はいかがでしょうか。","respondent":"松山障害者福祉課長","answer":"おそらく指定特定相談支援事業所の相談員のほうが状況を把握して、相談の中で丁寧に説明するというのがよろしいかとは思っております。","voiceIndex":27,"id":"exchange-011"},{"speaker":"あべ委員","kind":"質問・要望","question":"そこなのですけれども、理屈としてはとてもきれいなのですが、実態としてどのくらい本音の希望が出て、それが区まで伝わる形になっているか。ですので、こうした希望が現場の段階で潜ってしまわないように、課としてはもう一度ここはきちんと要望を把握しようということの働きかけをしてほしいのです。それについて、ご答弁をお願いします。","respondent":"松山障害者福祉課長","answer":"確かに委員ご指摘のとおり、最初から何もなければ、就労を諦めてしまうような方もいらっしゃるのではないかと推測されますので、再度、相談支援員の連絡会等を通じまして、周知徹底を図っていきたいと考えています。","voiceIndex":29,"id":"exchange-012"},{"speaker":"あべ委員","kind":"質問・要望","question":"今のお母さんたち、お子さんに障害があってもなくても、一定の就労の要望というのは、多分、これは少なくとも障害がない方と同じぐらいの希望を持っていらっしゃるということを前提に、今、どのくらいの方が就労されているのかということの相差というのが潜ったニーズ、潜在的なニーズだと思いますので、それをいかに掘り起こすかということをぜひやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほどから、預かれるのは毎日ということではないということをおっしゃっているのですけれども、平均で大体何日ぐらい預かれるということなのでしょうか。","respondent":"松山障害者福祉課長","answer":"こちらの延長対応が、就労保障という目的に特化しているものではないことから、確かに毎日働きたいという方につきましては、さきに説明をいたしました生活介護の延長サービスや訪問系サービス等を組み合わせて、できる限り支援をしているというのが実態です。","voiceIndex":33,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"結局、働き続けることが保障される受け皿というのが、本当に困難な状況というのが実態だと思うのです。そういう点では、やはり日中一時から、移動支援から、延長から、そういうところでこの陳情書に書かれていますけれども、そういうところを本当に充実、拡大していただいて、親も働くことが、就労が権利として保障されるというところまで、ぜひサービスを拡大していただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-015"},{"speaker":"若林委員","kind":"確認","question":"１つだけ。そこにいわゆるうちの子どもがとかということで当事者としてのご相談があったとき、生活介護とか就労継続Ｂとか、そういう中で、現状とか、具体的なご相談、それから、中学、高校を卒業してからのそういう仕事をしているところの保障というのか、そこら辺のご相談があったときには、窓口としてはどのような返答、相談に乗るという形なのでしょうか。","respondent":"松山障害者福祉課長","answer":"障害者福祉課としては、基幹相談支援センターという位置づけですけれども、まず、障害者福祉課のほうでもご相談はお受けしますが、地域の拠点相談支援センターでもご相談はお受けしております。","voiceIndex":37,"id":"exchange-016"},{"speaker":"渡部委員","kind":"質問","question":"といいますのが、障害の種類も違いますし、程度も違いますし、家庭におけるニーズも違うという中で、どういう形が一番いいのか。ですから、できる範囲の中でしっかり、障害を持っているか持っていないかだけではないではないですか。ですから、限られたものの中でどのようにできるのか、どういうサービスがあるのかというのは、しっかりやっていただかなければならないのだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-017"},{"speaker":"渡辺委員","kind":"質問・要望","question":"結論を出すで、考えは不採択です。ただいまのやりとりからも確認できたのですが、まず、そもそも論ですが、表題にある、家族が働き続けることができるよう支援を求めるということで、個別性が高いこと、２つ目が、一律のサービス設計では難しいというのが、先ほどもご説明がありました。３番目は、かといって、悲観的に見るのではなく、現状の中でも再三、個別案件に対して柔軟に対応という言葉が出ました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"特にこの９月にも出ましたけれども、重ねて日中一時支援等について、団体の方からのさまざまなご希望の声があるというのは、当然、私ども公明党としても承知をしていることです。その中で、９月と同様、ニーズの把握に努めて、第６期の計画が今進められていると。ぜひいい障害福祉計画、また、障害児福祉計画を策定して、ニーズに寄り添って応えていただきたいという思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"結論を出すということで、採択でお願いしたいと思います。私は、障害者の問題研究の雑誌を読みまして、それはある母親にとっての親亡き後のテーマの問題で、児玉真美さんが書かれた論文だったのですが、この方自身が、ちょうど心身障害者の娘さんを持つ当事者でもある方ですが、書かれたことが本当に胸に響きました。私は、改めて親の就労を保障するためのサービスの拡充を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-020"},{"speaker":"あべ委員","kind":"質問・要望","question":"本日、結論を出すということで、不採択でお願いしたいと思います。これは今行っている調査ならびに今後の福祉計画の中でもぜひ活かして実行していただきたいと考えています。今回、不採択としますが、ここで陳情者の方がおっしゃっていることは区も十分把握されていると思うので、ぜひ実現に向けて頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-021"}]},{"id":"topic-02","title":"令和元年陳情第５１号 移動支援サービス事業者を増やす研修の実施を求める陳情","agenda":"令和元年陳情第５１号 移動支援サービス事業者を増やす研修の実施を求める陳情","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"２つだけありますけれども、１つは、前半に出ている、委託しているしていないということで、先ほどからあったのですが、特段何か問題があるわけではないですよねという確認が１点。要は、従事者を増やすことができる研修の実施ということが求められているのだけれども、問題はそこではないような気がするのです。すみません、その２点。","respondent":"松山障害者福祉課長","answer":"委員お尋ねの、区との契約については、問題はございませんということです。２点目の研修の実施、研修の中身や研修の仕組みというよりは、全体的にヘルパーの確保というのが区としては非常に課題として認識しております。","voiceIndex":54,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"仕組みのことで伺いたいのですが、ガイドヘルパーの資格なのですけれども、区の要綱では、ヘルパー２級、それから、品川区実施のガイドヘルパー養成研修を修了した者、または、品川区長が同等の要件を備えた者と認めた者となっているのですが、区内にヘルパーステーションはたくさんあると思うのですけれども、そのうち移動支援は１８カ所しかないのですよね。","respondent":"松山障害者福祉課長","answer":"ヘルパー２級の方でもガイドヘルパーになれるのかですけれども、確かにそのとおりですが、ただし、例えば、高齢者のヘルパー事業所ですと、やはりこちらのほうの知的障害者の方への支援ですので、できるだけ受けていただくようにはしておりますが、必須の要件ではございません。","voiceIndex":57,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"普通の訪問介護とまた移動支援というのは中身が違うので、やはり研修を受けたほうが、移動支援も、ヘルパー自身としてもやりやすいということはあると思うのですけれども、その点では、研修の内容なのですが、講義と実習ということになっているのでしょうか。この研修というのは何時間くらい受ければ資格が取れるのかということについてもお聞かせいただきたいと思います。","respondent":"松山障害者福祉課長","answer":"あるいは歩く速度ですとか、突発的に行動を起こしてしまうような方もいらっしゃるということでは、事業者から聞いているのは、マッチングに苦労するということは非常に大きな課題として認識しております。ですから、やはり人の課題というのが一番多いと認識しています。","voiceIndex":59,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ただ、移動支援がなぜ増えないのかというと、やはり事業所として成り立つのが大変だというところも聞いていますし、言われているところではないかと思うのです。その点では、それを改善させるには、報酬の引き上げが必要なのではないかと思うのですけれども、報酬というのは、国で決められている報酬というのがあると思うのですが、それにのっとってやるということになるのでしょうか。","respondent":"松山障害者福祉課長","answer":"したがいまして、移動支援のほかに給付がとれる事業所を併設して経営しているというところはあります。２つ目なのですけれども、区内においては、東京都の指定を受けた移動支援従事者の研修ができる事業者というのは、指定を受けたところはございません。","voiceIndex":61,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３０人なので、５,０００円だったとしても、１５万円という程度ですよね。そういうことであれば、区のほうとして援助して、無料またはもっと低額で受けられるようにしてもいいのかと思うのですけれども、そういうことで受講者を増やすということにするというふうにしていただいたらいいのではないかと思うのですが、その点についてもお聞かせいただきたいと思います。","respondent":"松山障害者福祉課長","answer":"そのため、受講者を増やすというよりは、本当に移動支援サービスの事業者を増やすためにどうしたらいいかという方法については、さまざまな方法が考えられると思いますので、模索はしていくです。","voiceIndex":63,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"でも、実際にほかの区がほとんど無料でしているということですから、これは料金が安ければ、やはり受けやすいということにはなると思いますので、ぜひこれは引き下げというか、無料にということで、しかもそんなに人数が多いわけではないので、品川区としてできない支援ではないと思うのです。そういう点では、３０人募集しても、５人から７人の応募しかないというところでは、ぜひ受講料は。","respondent":"松山障害者福祉課長","answer":"今後の具体的な取り組みですけれども、今、実際に移動支援をやっていらっしゃる事業者、あるいは研修をしていらっしゃるＮＰＯ法人みらいのほうから、具体的に情報を集めている段階です。","voiceIndex":65,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"昨日今日出てきた問題でなくて、障害者福祉そのものがさまざまな問題をたくさん抱えていて、どう改善させていくかという取り組みがいろいろな分野にわたって、多岐にわたって取り組まれているところなので、そういう状況もやむを得ないのかと思うのですけれども、これはずっと言われ続けてきているところなので、ぜひ具体的なところで対応していただきたいということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-028"},{"speaker":"あべ委員","kind":"質問・要望","question":"ごめんなさい、確認したいのです。品川区もそうした積極的な手法もとってはいいのではないかと思いますが、いかがでしょうかというのが２つ目の質問です。それから、みらいがやっている以上は、みらいの広報というのもとても大切だと思うのですけれども、ここ数年、みらいのホームページでも、受講のご案内が出ていないように見えるのですが、ここはぜひ改善すべきではないかと思いますが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"ＮＰＯ法人みらいというのは、東京都の指定は受けてはおりませんが、みらいの実施計画の中で、ほかのＮＰＯ法人と協力してこの事業を実施していくという旨の報告は区のほうにいただいています。クローバーのほうは、東京都のほうで指定を受けているということです。","voiceIndex":69,"id":"exchange-029"},{"speaker":"あべ委員","kind":"質問・要望","question":"区としても、受講生がなぜ毎年定員を大きく割り込んでいる状況なのかということは、もっと積極的に関心を持って改善策を一緒に考えていく、そして、実行していくという姿勢で、今年や去年の話ではないですから、それはしっかり監督と言ったらいいのでしょうか、委託をしている者の責任としてやっていただきたいと思います。全部課の中で抱え込んでしまったら、かえって進まないではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ヘルパーの２級とか１級とかの養成というのは、昔、介護福祉専門学校でやっていたような気がするのですけれども、そういう点では、介護福祉専門学校でガイドヘルパーの養成をするというのはできないものなのかと思ったのですが、その点はいかがでしょうか。","respondent":"松山障害者福祉課長","answer":"品川介護福祉専門学校のほうで研修ができないのかということについてですが、指定をとれば、可能性としてはあると思いますけれども、ほかのカリキュラムとの兼ね合いですとか、学校側としても。","voiceIndex":73,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ヘルパーを養成するというところでは、区の仕組みとして、そのように過去に取り組んだという経緯もあったという思いがしたので、ガイドヘルパーも、これだけ足りないという、養成しなければならないということですので、やはり区が主導でやって、介護福祉専門学校もぜひ活かしてやっていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-032"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"１点だけ。今、お話等々伺っている中で、そうすると、区内でこの研修をできるのはみらいしかないということですよね。それで、今年度は実習をまだ実施していないと陳情にも書かれていますけれども、この間というのは、どれぐらい研修の実施ができてきたのか。ずっとできていないのか、できていたものが今回は、どんな理由があってなのか、できていない理由なども伺えたらと思うのですけれども、お願いします。","respondent":"松山障害者福祉課長","answer":"みらいの研修の実績という確認についてです。平成２８年ぐらいから平成３０年度まで、３年間に春と秋ということで、年に２回継続して実施してきております。３年間では、４０人の方が受講を修了しているです。今年につきましては、みらいと調整しているところです。","voiceIndex":77,"id":"exchange-033"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"品川でも、先ほど話の中でも、そもそも移動支援が増えない、人の課題があるというところでは、今後、方策は明らかにしていきたいということだったと思うのですけれども、以前に世田谷区に話を伺いに行ったときには、今後区がやることは、やはり人材育成をやっていくということだと伺いました。やはり先ほどもお話にも出ていましたけれども、指定を受けて、区が人材を育成していくと確かに書かれていたのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-034"},{"speaker":"渡部委員","kind":"確認","question":"今日結論を出して、不採択でお願いします。先ほど質問で確認することは確認させていただきました。これはどういう形かで、そういう方が増えるようになっていけばいいと思いますので、それについては進めてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-035"},{"speaker":"西村委員","kind":"質問・要望","question":"結論を出すということで、不採択でお願いいたします。移動支援従事者研修を受ける方の応募ですとか、人材不足は全国的な課題ではありますので、引き続き創意工夫をしていただきたいと思うのですけれども、陳情の内容に関しましては、事実と異なる点もありますので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-036"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。区の次に向かっての姿勢は、質疑の中で確認をさせていただきました。いずれにしても、今、唯一の事業所、研修をやっているみらいの、受講料もあえて含めた原因の分析を、きちんとやるということがまずスタート、課長のお考えの中にもあったと思うのですけれども、そこはしっかり進めていただきたいということで、不採択で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"結論を出すということで、採択でお願いします。本当に希望する人がいるのに、提供するサービスが不足しているために、提供できないという状況が長い間続いているので、この事態は改善が必要だということです。地域生活支援事業だけに、自治体で大きく差が生じるところです。区として当事者の声に応えて対策をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-038"},{"speaker":"あべ委員","kind":"質問","question":"本日結論を出すということで、採択でお願いします。先ほどからもいろいろ質問もさせていただきましたけれども、やはりヘルパーが足りないという区の認識はわかるのですけれども、ただ、それをどう増やしていくかというところでは、やはりこの陳情にあるような事業者を、研修を増やしていくということもぜひ必要だと思いますので、これは採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-039"}]},{"id":"topic-03","title":"令和元年陳情第５７号 品川区旅館業施行条例を、常駐者を義務付けた内容に改正することを求める陳情","agenda":"令和元年陳情第５７号 品川区旅館業施行条例を、常駐者を義務付けた内容に改正することを求める陳情","exchanges":[{"speaker":"西村委員","kind":"質問","question":"先ほど課長がおっしゃられました、東京都内では多くの区が常駐者を置くことを義務づけた条例になっていると書かれているところで、不正確な情報だとありましたが、いま一度この点、ご説明をお願いできますでしょうか。","respondent":"鈴木生活衛生課長","answer":"ほかの５区につきましては、宿泊者がいる時間内のみ、もしくは駆けつけられる、すぐに到着できる場合であれば、無人でもオーケーという限定的、部分的な規制となっているのが現状です。","voiceIndex":94,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは９月の陳情審査のときに、課長のほうから私が聞いたところで、このような、今回、南品川に建てられるような常駐の管理者のいない旅館の建設というところでは、手元に最近のものを持ち合わせておりませんということで、ご答弁がなかったのですけれども、フロントの常駐者のいない無人ホテルというのが、現在の段階でどれくらいできているのか、改めて何件新たにできたのか。","respondent":"鈴木生活衛生課長","answer":"現在、区内で無人の状況で営業しているホテルが、旅館業のほうの許可が２４件、それから簡易宿所が１件の合計２５件になります。そのうち品川地区が１３件、大崎地区が２件、大井地区が５件、荏原地区が５件です。荏原地区の５件のうち１件は、簡易宿所になります。","voiceIndex":97,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここのところで、大きな苦情、トラブルは来ていないというご答弁だったのですが、荏原警察の生活安全課長から話を聞く機会がありまして、荏原地域の民泊か旅館業なのかわからないのですが、騒音やごみ出しの問題で、かなり警察のほうにも苦情が既に何件も来ているということでお聞きしたのですけれども、警察に苦情がどれくらい来ているのかというのは、それぞれの警察に確認して。","respondent":"鈴木生活衛生課長","answer":"件数としましては、直接警察や消防に苦情などが行って対応したという報告は、特に各署から受けておりませんが、連携するときはほぼ区からの要請、保健所からの要請で協力をいただいている件数ということですが、旅館業に関しては、今年度は６件です。","voiceIndex":99,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これは保健所に行ったものを警察に知らせたという件数なのか、直接警察に行っているというのもあるのではないかと思うのですけれども、その点についてどうでしょうか。","respondent":"鈴木生活衛生課長","answer":"ただ、警察に直接行ったものについては、今のところ区のほうに何件とかという報告をいただくようになっていないので、それについては、今後また情報共有の意味で警察と協議したいと思います。","voiceIndex":101,"id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先日の石田ちひろ議員の一般質問で、近隣住民からの意見や疑問などについてはホテル設置者に伝え、説明会の開催や近隣への配慮などを指導しているというご答弁だったのですけれども、近隣住民からの意見や疑問は、どのような内容を設置者に対して伝えていただいたのか、また、近隣への配慮の具体的な中身は、どのような中身で指導されたのかについてもお聞かせください。","respondent":"鈴木生活衛生課長","answer":"指導としては、まずは住民の方対象の説明会を開催して、しっかりと説明をするということ、それから特に無人のところについてやはり皆さんご不安をお持ちのようですので、そこについて何か対応する方法がないかということも検討してもらうように依頼をしたところです。","voiceIndex":103,"id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"無人のところについて、常駐者を午前１０時から午後６時ということで置くということは、一歩前進ということは言えるのかと思うのですけれども、でも、地域の方が一番不安に思っているのは、昼間のところではなくて夜の、これ以外のところが一番不安になっているところなので、そこのところをしっかりと対応してほしいということでのご要望なので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"この条例が義務づけられていないというところから発した問題なので、そこのところの不安や疑問に対してどう応えていくかというところなので、この陳情の中身に沿わない質問をしているということではないと思います。それから、前のところで、既に建築確認はおりて、建築が始まろうとしているわけですよね。","respondent":"鈴木生活衛生課長","answer":"手続きについてのスケジュールですが、既に住民説明会の後、申請の手続きにはいらっしゃいまして、受理をしております。それから、あわせて近隣施設で意見照会が必要な場所、今回、２カ所の公園がありますが、そこへの意見照会も終了したところです。","voiceIndex":109,"id":"exchange-046"},{"speaker":"あべ委員","kind":"意見","question":"私自身は、あまり条例を指導で現実的に要件を変えていくというのは、手法としては必ずしも望ましいことではないと思うのですけれども、さはさりながら、やはり住民を守るという観点からいうと、あるいは住民の不安を和らげるという観点からいくと、この件に関してはこれまでもさまざまな陳情で議論をしてまいりましたけれども、やはりもう少し地域を守る、住民の不安を和らげる。","respondent":"鈴木生活衛生課長","answer":"先ほどご説明したように、委員からもご指摘あったように、区としての独自の状況に合わせた規制の仕方、もしくは対応の仕方というのはあると考えています。よその区の条例に関しても一通り調べてありますが、やはり区の状況が、実が違います。","voiceIndex":112,"id":"exchange-047"},{"speaker":"あべ委員","kind":"意見","question":"品川区というのは、宿泊事業が比較的多くて、特に潜在的な需要が非常に多くて、利便性が高くて、かつ駅の近くにすぐに住宅地が広がっているような場所が多いと考えています。ですので、そうしたものが無秩序に増えていかないような区の施策というのは、他区の一般に比べても強いのではないかと理解しておりますが、区の考え方は違いますか。","respondent":"鈴木生活衛生課長","answer":"ただし、先ほど申し上げたように、そこで懸念される環境への影響についてですが、先ほどは法の考え方だったので細かく言いませんでしたが、品川区の現状を見ると、やはり一番多いのは、ご指摘のとおり、住宅に近接するところに宿泊施設があるです。","voiceIndex":114,"id":"exchange-048"},{"speaker":"あべ委員","kind":"意見","question":"そうしたときに、さらに質が落ちていく可能性もある。歯どめのない、あるいは指導を伴わないような形で、ただ条例で認めてしまうと、そこのコントロールも今後さらにつきにくくなるのではないかということも、あわせて懸念をしております。こうしたことを条例で認めているから、何でもこうスルーというのではなくて、一件一件、その事業を審査するという姿勢は今もありますか。","respondent":"鈴木生活衛生課長","answer":"逆に言うと、それ以外の、規定がない、権限が与えられていないところについては、指導という形でしか現在対応できないのが実情ですが、それでも区民の方の不満や疑問、それから困ったというような声に対応するために、指導の形で今まで対応してきておりまして。","voiceIndex":116,"id":"exchange-049"},{"speaker":"石田（ち）副委員長","kind":"確認","question":"今回、南品川６丁目のホテル建設計画、陳情が出されたわけですけれども、この陳情の代表、陳情者のところにも名前があるように、南品川子供の安全と住環境を守る会というふうに、住民の皆さんが会を立ち上げたわけです。区の状況は違いますので、だから品川区でもとはならないと先ほど課長がおっしゃっていましたけれども、条例に書き込むことはできるということですよね。そこを確認させてください。","respondent":"鈴木生活衛生課長","answer":"先ほど申し上げた３つの要件を満たすことが、条例で法を超える規制をかける要件ですので、ほかの区がどういう内容の課題なり影響なりに着目をして、その重要度や必要性を勘案したかというのは公開されていませんし、そこまでは私も把握しておりませんが、品川区に関しては。","voiceIndex":119,"id":"exchange-050"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それでやはり災害時だったり、急なことが起きたとき、この間の台風もそうだったそうですけれども、常駐者がいないと、宿泊者がどうしていいのかわからないということと、あと急病が出たときに、室内に緊急ボタンがあったとしても、それを押せなかったときどうなのかとか、そういった適正な旅館業の運営をしてもらうために、国の法律では、置かなくてもいいですという規制緩和がされましたが。","respondent":"鈴木生活衛生課長","answer":"ただし、実際には、やはり規定に沿ってやる中で、一定程度、できること、できないことの境ができてしまうというのは事実だと考えております。","voiceIndex":121,"id":"exchange-051"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それで、いろいろ先ほどの指導等、注意等をしていくという立場ではできるということでしたけれども、もうそこにもとどまらないほどの不安がこの地域には、このホテル建設計画によって生まれてきてしまっているのですが、そうした適正な管理によって不安を取り除けるというお考えはお持ちですか。","respondent":"鈴木生活衛生課長","answer":"今、南品川の計画を例にとって、区としてそれにオーケーを出すのかというご質問ですが、区は、あくまで法令、それから区の条例に基づいた基準に適合するかどうかを判断する権限しかありませんので、それを満たしている場合は、それ以外の部分については。","voiceIndex":123,"id":"exchange-052"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今、お聞きしたのは、管理・運営が適正にされていれば、外国人が泊まるホテルでも、不安ではなく、歓迎という思いで迎え入れることができるという考えは区にもありますかということです。管理がしっかりしていればということです。","respondent":"鈴木生活衛生課長","answer":"区としては、もちろんしっかりとした管理が事業者にできるかどうかという審査をした上で、不足な部分は指導していますので、当然、しっかりとした管理は重要だと考えております。","voiceIndex":126,"id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ニーズを伺って、中間訪問をして、それから商店街での買い物とかの要望があれば、それに応える、それから夜には皿を洗いに行くということで、無人であっても、３回から４回、そこの民泊のところに事業者が伺って、どんな方が泊まられているのか、そして、その方のニーズがどんなニーズなのかということを把握しながら管理をされているということなのです。","respondent":"鈴木生活衛生課長","answer":"営業者側が管理をして安全を確保するための方法論ですが、これについては、営業の自由もありますし、また、採算性の話とかもありますので、区として強制できるものではありません。そういう意味でも、やはり条例での規制は難しいと考えております。","voiceIndex":128,"id":"exchange-054"},{"speaker":"渡部委員","kind":"質問","question":"もうやりとりを聞いていてわかりましたし、そもそも残念ながら、文章に間違いもある中でなのですが、法令と条例というところの考え方でもって、保健所はしっかりと指導はこれからも続けていくことだと思いますので、何か不都合等があれば対応するし、品川区が持っている旅館業法の条例の中でも、というか、法令の中で１０分で駆けつけるルールがたしかあるはずなので、だから、それはいる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-055"},{"speaker":"西村委員","kind":"質問・要望","question":"結論を出すということで、不採択でお願いをいたします。質問をさせていただきまして、課長のご説明にもありましたように、法と条例の関係につきましても一定の理解をいたしました。一方で、住民の方々のご不安はわかりますので、引き続き区のほうには丁寧にやりとりをしていただきたいとお願いをいたしたいと思いますので、本件に関しましては、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"結論を出すということで、採択でお願いしたいと思います。そういう中で、緩やかな内容で目的が達成できない場合というところに私は当たるのではないかと思いますので、そういう不安、疑問を解消するためには、やはり他区で義務づけているような、条例でしっかりと常駐者を義務づけるという条例の改正が必要だと強く主張したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":134,"id":"exchange-057"},{"speaker":"あべ委員","kind":"質問・要望","question":"本日結論を出すということで、これについては不採択と考えております。１つには、やはり安全面ですので、先ほども話が出ました。非常に小規模なのか、あるいは１００人単位で人が泊まれるようなものなのかによっても判断、あるいは求める基準というのは変わってくると思いますので、そこは住民の方々に実質的な負担がないように、地域に負担がないように、今後も指導をよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-058"}]},{"id":"topic-04","title":"令和元年陳情第５９号 「品川区障害福祉計画・障害児福祉計画策定のための基礎調査」の選択肢の偏りに関する陳情","agenda":"令和元年陳情第５９号 「品川区障害福祉計画・障害児福祉計画策定のための基礎調査」の選択肢の偏りに関する陳情","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"それは普通にそういうものですから、それがまず１点。そもそも担当課にこういう説明もない中で、こういう陳情を議会にあげてきているのですか。それを確認したい。だって、担当課に説明というのは、担当課に個人で聞いてわかるのだったら、議会に陳情まであげてくる内容ではないと思うのだけれども、担当課がきちんとした答えをしないからこういう陳情が来たのか、教えてほしい。","respondent":"築山障害者施策推進担当課長","answer":"本件に関するご質問は、直接障害者福祉課にはございませんでした。","voiceIndex":143,"id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点で、変えられなかったということなのですけれども、これは今回、平成２９年度も同じ設問にしているので、そういう点では推移を比較していきたいということで、今回もそういう設問にしたという今のご説明だったと思うのですが、そういうことでいうと、そもそものあり方で、これから先もずっと多分、障害福祉計画・障害児福祉計画をつくるに当たって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"「暮らしやすい」といったら「暮らしにくい」ということの設問になってくるということではないかと思うのです。対する設問ですから、それは同じ形で聞くというのが、アンケートの普通のとり方だと思うのですけれども、そういうことでいうと、これからもずっとこういう形で聞いていくということになるのか。私はどこかで改めることが必要なのではないかと思うのですけれども、いかがでしょうかということです。","respondent":"築山障害者施策推進担当課長","answer":"障害者計画および障害福祉計画という計画策定に向けたアンケート調査となりますので、改めて設問等については検討したいと思っているところです。","voiceIndex":148,"id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうことで、設問を検討するということであるとしたならば、今回のような形で、「とても」ということを片方につけるとかということでなく、これからは対する設問のあり方ということで、改善していただくということでよろしいでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"現在、まだアンケートの結果のほうも集計中です。いろいろな意見があるかと思いますので、次回、基礎調査の設問等を考える際には、また改めて検討したいと考えています。","voiceIndex":150,"id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひやはり恣意的にこちらにつけるということではなく、バランスを考えた形での設問の仕方ということで検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-063"},{"speaker":"あべ委員","kind":"質問","question":"この基礎調査なのですけれども、これを受け取った方々から、非常に答えにくい調査だったという声を、いろいろな障害種の方にいただいておりまして、逆に陳情でこの問題だけが出てくることがむしろ不思議なぐらいに、多岐にわたっていろいろなご指摘をいただいております。今回の基礎調査の内容と表記の仕方、あるいはその伝え方について、区として考えていることがあれば教えて下さい。","respondent":"築山障害者施策推進担当課長","answer":"ただ、その反面、項目が多くなることによって、回答するのが大変だということで、回答率の低下につながるという課題もあります。ですので、そのあたりのバランスをとりながら、次回考える際は、また新たに検討したいと考えています。","voiceIndex":154,"id":"exchange-064"},{"speaker":"あべ委員","kind":"提案","question":"この調査の内容が、一度、厚生委員会で示していただいたときに、でき上がった時点で当事者の方々に目を通してもらったらどうでしょうというようなことを提案したのですけれども、それはやっていただけたのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"当事者等につきましては、障害者団体等と事前のヒアリング等も行っておりますし、また、自立支援協議会等でも諮って、ご意見を踏まえて総合的に決定をしたという流れをとらせていただきました。","voiceIndex":156,"id":"exchange-065"},{"speaker":"あべ委員","kind":"質問・要望","question":"そうした全体のチェックも含めて、やはり当事者でないと、見落としというのはあるので、そこは障害福祉のプロだからこそ、当事者の人に最後に見てもらうということをぜひやってほしくて、そういうことをお願いしたのであって、事前にご意見を聞くというのは、それはわかっているわけだし、それはそれでいいことなのですけれども、目に触れる段階で一度見てもらうというのは、本当に必要なことだと思うので。","respondent":"築山障害者施策推進担当課長","answer":"今回、基礎調査を実施しまして、いろいろなご意見もいただいておりますし、また、これからも出てくるかと思いますので、そういう区民の方々、当事者の方々の意見を踏まえながら、また次回の検討に活かしていきたいと考えています。","voiceIndex":158,"id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"業者も変わったというところもあると思うのですけれども、そういう点では、今回のアンケートに関しては、ぜひ当事者の方々のご意見も改めて伺っていただいて、それで、この次にはぜひ同じ轍を踏まないということで、当事者の実態を把握するためのアンケートですから、答えられないのだったら何にもならないので、そういう当事者の意見を聞いて、アンケートの用紙をつくるということで。","respondent":"築山障害者施策推進担当課長","answer":"当事者のほうから出てくる意見等を踏まえまして、また次回の設問設定、アンケート調査項目の検討の際に活かしていきたいと考えています。","voiceIndex":160,"id":"exchange-067"},{"speaker":"渡部委員","kind":"意見","question":"本日結論を出して、不採択でお願いいたします。だから、これで行くのだったら、これでいいので、もし「暮らしやすい」を入れるのだったら、どこかに突っ込んでしまえばいい話であって、ただ、それが必要かどうかというのは、私はわからない。それはしっかり行政で考えてやっていただければいいと、不採択なのでもういいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":163,"id":"exchange-068"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"結論を出すで、採択でお願いしたいと思います。やはりバランスということからしても、そういう方向でぜひ今度の、これから来るアンケートには活かしていただきたいと思います。そして、また改めて当事者から聞き取りを行って、当事者の意見を反映したアンケートにしていただくよう、求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-069"},{"speaker":"あべ委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いいたします。これはこの基礎調査を用意した障害者福祉課がレベルが高いとか低いとか、そういう話ではなくて、やはり当事者でなければ見落としてしまうものというのは、これは障害福祉に限ってではなく、どの分野にもあると思いますので、そこを何とか埋めていくような手順というのをぜひ今後前向きに検討していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":167,"id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3550#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":45384,"voices":173}},{"id":"r01-20191202-8","meetingId":"r01-cm12","date":"2019年12月2日","dateIso":"2019-12-02","committee":"建設委員会","time":"午前１０時００分～午後 １時５７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を76件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第９０号議案、品川区災害弔慰金の支給等に関する条例の一部を改正する条例","agenda":"第９０号議案、品川区災害弔慰金の支給等に関する条例の一部を改正する条例","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"ありがとうございました。１２月１３日までに規則で定めるということなので、本当だとこの委員会で明確にある程度パーセンテージを出してもらったほうがよかったかなとは思うのですけれども、要望として、今１.５％や１.０％などの例示、また他区の状況等を見てということでしたけれども、なるべく低金利でお願いしたいなと。これは要望でとどめします。","respondent":"中島防災課長","answer":"周知に関しましては、一般的に広報というところではなかなか届きにくいので、そのような対象の方にお伝えしていく、やはりこの制度に該当される方にお伝えしていくことが一番確実な周知なのかというふうに考えているところです。","voiceIndex":7,"id":"exchange-001"},{"speaker":"たけうち委員","kind":"確認","question":"生活福祉資金ということで、その一部として災害援護資金の貸し付けということで、低所得者の方を対象にして云々とあるので、その辺のことでいいのかという確認と、この制度をもし使う場合の申し込みは窓口が社会福祉協議会になるのかということと、今回の台風第１５号、第１９号で、品川区でもそういった被害に遭われた方は、この条件に合えばこれが使えるのかということを教えてください。","respondent":"中島防災課長","answer":"社会福祉協議会のところにつきましては、そのような制度が東京都の社会福祉協議会のほうが各区市町村の社会福祉協議会のほうに受付等を委任というか、委託しているような形で、基本的に今回国のほうの制度が利用できる方についてはそちらをまず使って、それが利用できない方が。","voiceIndex":9,"id":"exchange-002"},{"speaker":"たけうち委員","kind":"意見","question":"今回の台風第１５号、第１９号は、対象になるのかどうか。","respondent":"中島防災課長","answer":"台風第１５号、第１９号に関しましても、対象になります。","voiceIndex":11,"id":"exchange-003"},{"speaker":"たけうち委員","kind":"確認","question":"そのような方に対して、先ほど課長がおっしゃったように、個別に案内するというのであれば、被災証明書が出た方、罹災証明ですか、そのような方で条件が合致しそうな方がいるのだったら積極的にＰＲしてもらいたいから、そこが大事だから確認したので、自信を持って答えてもらいたいのです。建物の一部だけが損害を受けても対象にならないというようになっているのです。","respondent":"中島防災課長","answer":"ご指摘のとおり、今回この災害援護資金の対象は、家財の３分の１以上の損害や、住宅の半壊・全壊というものになっております。一部損壊は対象になっていないところです。","voiceIndex":13,"id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問・要望","question":"最後になりますけれども、ぜひ先ほどあったように、今回品川区でも対象になるということなので、被害に遭われた方にこのようなものがありますよと。残念ながら合致しない場合もあるかもしれませんけれども、このようなものがありますよという情報が届くように、周知啓発をしっかり行っていただきたいと思います。これは要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-005"},{"speaker":"安藤委員","kind":"提案","question":"先ほど質疑ありましたけれども、利率のところは３％以内でということなので、現行よりは低くなり、それは前進というか、素直にいいことと思うのですが、やはり先ほどもあったように、条例審査までに利率も含めた提案というものをぜひお願いしたいと、これは要望です。あるとしたらどれぐらいあったのかということを確認させてください。","respondent":"中島防災課長","answer":"いずれも基本的には台風第１５号によるものということで聞いているところです。一部、台風第１９号の影響もあった、重なってあったということでもありますが、そのようなことを聞いているところです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"実際に半壊が３件あったということですので、ぜひこのような制度改正が行われたということですから、当然行うと思うのですけれども、漏れなく制度のご案内するようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"松本委員","kind":"質問","question":"今、貸付利率の話が出たのですけれども、この貸付原資の負担は国が３分の２で、都道府県、政令指定都市が３分の１だったかと思うのですが、このような場合には、品川区のほうで利率というものはある程度決められるのか、あるいはやはり通知が来て、それに従わざるを得ないのか、そのあたりはどうなのでしょうか。","respondent":"中島防災課長","answer":"ただ、やはり自治体のほうでも決めるのに、目安がないとということで、国のほうから、東日本大震災のときの１.５％や母子寡婦福祉資金貸付金の利率が１.０％という例示があり、あとはそれを参考に自治体のほうで決めるというような形かと考えています。","voiceIndex":21,"id":"exchange-008"},{"speaker":"松本委員","kind":"質問","question":"この利率のほうなのですが、今調べるとたしか所得制限がついていて、特別区の場合は特例があるからわからないのですけれども、今見ている範囲だと所得制限が、例えば２人世帯だと４３０万円、結構低目にされていると思うのですが、そのあたりの所得制限というものは、今回改正するに当たって何か検討などということはあったのでしょうか。","respondent":"中島防災課長","answer":"基本的には今回自治体のほうで改正できるところは、法律の改正に基づきまして行っているところでございまして、所得制限の改正について検討ということは特に考えてございません。","voiceIndex":23,"id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"重なるところがあるのですけれども、やはりこの貸付利率なのですが、これが施行されるまでには定められるということなのですけれども、定められる前に、例えば議会の委員会の中で報告されるなどという機会はあるのでしょうか。ぜひ定められる前に報告していただきたいなと思うのですが、その辺いかがでしょうか。","respondent":"中島防災課長","answer":"貸付利率につきましては委員会等の場でご説明をできるような機会が、時間的にも難しいのかなと思っているところです。何らか、別の形でお伝えできるように考えてまいりたいと思っています。よろしくお願いします。","voiceIndex":26,"id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"それはできるだけお知らせいただきたいということと、それから先ほどよく聞き取れなかったのですけれども、ご答弁の中でその利率を、今後規則で定めるに当たって、近隣区といった他自治体のことも勘案しながらとおっしゃっていたのですが、そもそもこの制度全体として災害障害見舞金の支給や災害弔慰金の支給なども、あわせて、他区が参考になるのかなと思うのですけれども。","respondent":"中島防災課長","answer":"他区において、まだ全ての区が改正できていないのですが、調べたところですと、いずれの区も保証人がいる場合は無利子となっております。保証人がいない場合につきましては、１％が１５区で、１.５％が４区と聞いているところです。","voiceIndex":28,"id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"制度全体というか、その利率以外にも、災害障害見舞金や災害弔慰金なども、そのようなことをあわせて、ほかの区の状況などは調べていらっしゃらないのでしょうか。","respondent":"中島防災課長","answer":"失礼いたしました。災害障害見舞金、災害弔慰金のところにつきましては、ほかの区についても基本的に、特に改正はしていないと。今回は、あくまで災害援護資金の貸付利率のところと、あと保証人のところとか、そういうところの改正であると認識しています。","voiceIndex":30,"id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"すみません。重ならないように１点、２点ぐらい教えてください。それから先ほど来、貸付利率の話がたくさん出ているのだけれども、今調べていただくと、１９区はもうそれを出ているのだよと。品川区が別に４区の方でもいいのだけれども、それを１２月中旬に定めようとしたのはどのような理由があったのかということだけ教えてください。","respondent":"中島防災課長","answer":"この貸付限度額というものが３５０万円というふうに決められていますのは、法律でもう決められておりまして、それに基づきまして対応しています。","voiceIndex":33,"id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"確認","question":"貸付利率のところはいいです。そうなったときに、この３５０万円を特別区で、ではこれを４００万円にしてくれとか、４５０万円にしてくれとか、そのような動きは全くなかったというか、先ほど言った国のお金も入るから、これはもう最初から３５０万円が上限だよということで何の動かしようもなかったのか、全国一律そうなっているかというところだけ確認させてください。","respondent":"中島防災課長","answer":"以前あったかどうかまではちょっと調べてはいないのですが、少なくともここ１年についてはなかったと認識しております。","voiceIndex":35,"id":"exchange-014"},{"speaker":"大沢委員","kind":"質問","question":"そこのところはどのようにお考えになっているのか。聞くところによると、国のほうでなぜ改正をしなければいけなかったのかというところで、非常に自治体の債権にかかわる費用が大きくなってきてしまった部分があったということですけれども、その辺のところ、品川区では、他の自治体も含めた債権管理の仕方というようなものはどのようにお考えなのでしょうか。","respondent":"中島防災課長","answer":"高齢化に伴う返済のところにつきましては、しっかり用途をお聞きするなど、用途に合った最適な貸付けというか、借りていただくというところと、あとしっかり返済ができる、保証人も含めまして相談を受ける中で、貸付けをしっかり行い。","voiceIndex":38,"id":"exchange-015"},{"speaker":"大沢委員","kind":"質問・要望","question":"災害ですから、皆さんお困りの中で融資申請をするわけです。間違いなく、これは債権管理に関するコストというものは、状況が状況なだけにかさんでいくと思いますので、その辺のところの管理をしっかりしていただきたいと思うのですけれども、最後にそのことをお願いします。","respondent":"中島防災課長","answer":"やはりほかの震災で経験されている自治体でも、債権管理というものが結構長期化していたり、延ばしたりというところもあるようなので、コストも含めまして適正になるように努めてまいりたいと考えています。","voiceIndex":42,"id":"exchange-016"}]},{"id":"topic-02","title":"令和元年請願第１８号、武蔵小山駅周辺再開発の環境調査実施と計画見直しを求める請願","agenda":"令和元年請願第１８号、武蔵小山駅周辺再開発の環境調査実施と計画見直しを求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今の報告にありますように、かなりいろいろな影響が出てくるのが超高層だと思いますので、それぞれについてある程度お伺いしたいのですけれども、まず、この資料に「武蔵小山賑わい軸地区（街並み再生地区）」とありますが、これは９月の建設委員会でこの再生地区の指定を申請するという報告がありましたけれども、その後申請し、指定されたということなのでしょうか。伺いたいと思います。","respondent":"稲田都市開発課長","answer":"９月の当委員会で地域での説明会を実施したこと等を報告させていただきましたところです。基本的にこれは再生方針、方針づくりです。そのような中で、再開発にかかる、今後進んでいくであろうと思われる再開発の意見等に反対というところでございました。","voiceIndex":57,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"何なんだと、私は思いますので、この辺は気をつけたほうがいいのではないでしょうかという意味です。伺いたいと思いますし、あわせて、請願には複合被害のことが書いてありましたけれども、これは多分、ここは風洞実験で既に建てられている武蔵小山パルム駅前地区のほうも考慮して、ここの複合被害については一応考慮されているという理解でよろしいのか、その辺ちょっとお伺いします。","respondent":"稲田都市開発課長","answer":"そのようなところに対しては樹木を植えるなどしながらカバーしており、このシミュレーションに従って実施後の調査も行いながら対応するということで、このような考えで今やっているところです。","voiceIndex":59,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"予測しているところです。ただ問題は、いくら実験をして出したとしても、住んでいる方の実感としては、先ほどおっしゃったように確実に大風が吹く日が増えるということですから、それは現状より悪くなるということですから、それは風害そのものなのではないですかと伺ったので、全然質問に答えていないのです。ところが、品川区はそれを認めるのか、認めないのかということを伺ったので、答えていただきたい。","respondent":"稲田都市開発課長","answer":"ただ、実際やってみて、先ほども言いましたけれども、１年間はかる中においては、いろいろと出てくる。そのポイント以外でも、地域の人がここは風が強いのではないかなどという話、これはきちんとお聞きしまして、その対応策も考えるです。","voiceIndex":61,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと大崎のほうは、植栽をやって今現在どうなっているのですかということも伺ったので、改善されたのですかということも伺いたいと思います。どのような危機感を持っているのか、その認識を伺いたい。なぜ令和４年度から増便、増車といいますか、８両編成への増強になるのか、何で令和４年度からなのかということ、そして、８両編成でその状態は解消されるとお考えなのかどうか伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"やはり計画的に予測もして、まちづくり、超高層をどんどん建てていくことでいいのかどうかということも含めて検討するのが行政の役割ではないでしょうか。武蔵小山パルム駅前地区のほうは６２８戸、武蔵小山駅前通り地区は５０６戸という数の住居ができます。全体で想定しているお子さんの数、保育園や幼稚園、学校に通う人数などを予測しておられるのかどうか、伺いたいと思います。","respondent":"稲田都市開発課長","answer":"人数の想定ですけれども、両地区合わせた人数の想定というように聞いておりまして、保育園規模が３０名程度ですので、それに見合った検討でやっていくと。３０名規模の保育園を設置して対応できるというところでやっております。","voiceIndex":66,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"今お伺いしたのは予測をしているのかどうかということだったので、では予測はしているということでよろしいのか、また３点伺います。かなりさまざまな分野で超高層が建つことにより、しかも１棟ではないわけです。住民と意見を交換しながら、やはり高さ制限というものを検討すべきだと思うのですけれども、この請願に書いてある、検討すべきというところに関して、区の考えはいかがでしょうか。","respondent":"稲田都市開発課長","answer":"やはり武蔵小山、西の品川区の玄関口です。さらなるまちの活性化はやはり必要でございまして、それをやっていくためには、居住者も増やしながら、そしてまちのにぎわいもさらに継続して、活力を生み出していくというところは非常に大事な部分です。","voiceIndex":68,"id":"exchange-022"},{"speaker":"松本委員","kind":"質問","question":"このラッシュの件なのですけれども、先ほどの安藤委員からの質問に対して少し疑問に思ったのが、なぜ令和４年度からというところで、これはもう報道などで出ていて、相鉄線の関係だと思うのです。","respondent":"稲田都市開発課長","answer":"これは確かに相鉄線との直通が関係しているというところだとは思いますが、東急に私どもが聞く中におきましては、いろいろと調整が必要だという、このような回答を受けているです。それ以外の鉄道につきましては、現在詳しい状況について承知していないところです。","voiceIndex":71,"id":"exchange-023"},{"speaker":"松本委員","kind":"質問・要望","question":"それはやはりどうかなと思うのですけれども、東京メトロも三田線も入っていて、これも調べたら、どちらも２０２２年、令和４年度に８両化に向けてという情報が出てくるのです。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ確認をさせてください。再開発は地元の発意であるということが１つある。","respondent":"稲田都市開発課長、鈴木都市計画課長","answer":"それが再開発だけでなく、それ以外の用途地域の変更についてもですが、このところにつきましては、都市計画課長よりお答えします。委員ご紹介いただいたように、市街地再開発事業の前段階の中でも、どう目標を立てて進めていくかということは、その前提として地区計画がありますし、木密整備地域などで進めている地区計画、大きいものから小さいもの、さまざまです。","voiceIndex":75,"id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"それからそのときに、例えばどう風を感じるかということは、その人の状況によって随分違うと思うのです。私は余りこのような調査には詳しくないのですが、例えば、体重７０kg程度の成人男子が基準になっていたりするのです。このような実験では、どのような人たちを基準にして考えておられるのか、一定基準がないと調査できないと思うので、その辺のことをぜひ教えていただきたいと思います。","respondent":"稲田都市開発課長","answer":"高齢者や子どもなど、そのようなところにおいては、基本的にはこの数値を出すに当たっては考えてはいないところですが、１年間実施をする中において、そのような風の強い部分、高齢者の話や子どもの話なども出てくるかもしれませんけれども。","voiceIndex":79,"id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"その辺はぜひ考慮すべきだと思います。それで、先ほど大崎のほうでは、建てた後やはり風が強いということで対策を打って、まだその結果はきちんと把握しておられないようなのですけれども、そのような先行した事例というものは、マイナス面も含めてぜひ参考にすべきだと思うのですが、その辺をこれから参考にしていこうというような計画があるのかどうか、その辺について伺いたいと思います。","respondent":"稲田都市開発課長","answer":"先行事例もありますし、もちろんそのようなところも考える。ただ、風はその場所ごとで非常に変わってきますので、参考にはしながらも、実際にはかっていく、今も武蔵小山パルム駅前地区が建ちましたので、１年間計測しながら検討していきたいと考えています。","voiceIndex":81,"id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"最後に１点だけ、防災備蓄倉庫は防災協定を結ぶということですけれども、現実それがどう機能するかというところまでは、例えば、日ごろの防災訓練などというところで、今後も話し合いなど、具体的に言えば本当に地域に開放するだけの余力があるのかとか、そのようなこともきちんと話し合われていくということでしょうか。その点、１点だけ伺います。","respondent":"稲田都市開発課長","answer":"防災協定を結んでやっておるというところは、地域に、還元するというのですか、地域に資さなければいけないですので、その辺はしっかりやっていきたいと考えています。","voiceIndex":83,"id":"exchange-028"},{"speaker":"大沢委員","kind":"質問","question":"本日結論を出してください。不採択でお願いします。理由を一言だけ述べます。先ほど来の課長と委員との話の中で、請願項目については鋭意行政側で対応していると思います。これについて改めて対応をする必要がないので、今後とも継続したまちづくり、武蔵小山のまちづくりについてやっていただければ十分であります。よって、この本請願は不採択、繰り返しますけれども、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"意見","question":"本日結論を出すで、不採択でお願いをいたします。理由は、今と大分似ていますけれども、再開発は地元の発意でありまして、それに伴って、環境対策等も出てきておりましたが、品川区でもその環境対策等は行われていると私は理解をしています。そのような意味からも、この請願は不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-030"},{"speaker":"たけうち委員","kind":"意見","question":"本日結論を出す。結論は不採択で。３番の高層化ありきということで言っておりますけれども、今、高層化ではない形での再開発をしている地域も品川区内にはあると思いますので、そういった面では高層化ありきということは当てはまらないのかなと考えていますので不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択を求めたいと思います。やはり超高層の林立により、周辺地区環境への負荷は多大なものがありまして、区の予測や対策なども不十分です。高層化ありきというようにこちらに書かれておりますように、先ほど質疑の中でも、武蔵小山は西の玄関口で、このような高さも必要だというようなご答弁もありました。ですので、こうしたまちづくりを見直すべきだという立場から、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-032"},{"speaker":"吉田委員","kind":"意見","question":"請願項目の最初のビル風被害ですけれども、先ほどのご答弁からも、やはり基本的な、平均的なデータはきちんととっているということですが、ここの住民にとって具体的にどうなのかというところはまだまだ不十分だと思います。区としての調査研究ということですし、やはりその辺は風工学研究所などのデータ任せにせず、区として、そのような個別の状況もきちんと勘案した調査もすべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-033"},{"speaker":"松本委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。理由はこれまでの皆さんと重複しているところですが、ただ、やはり先ほどの要望を、もう１回繰り返しますが、通勤のラッシュに関してはやはり相当、私も使っている線ですから、本当に負荷はかかっていますので、できるだけ解消できるように、いろいろと調査はしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-034"}]},{"id":"topic-03","title":"令和元年請願第１９号、住民の合意が得られない放射２号線道路計画の中止を求める請願","agenda":"令和元年請願第１９号、住民の合意が得られない放射２号線道路計画の中止を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"この請願に「放射２号線道路の計画を都に求めたのは濱野区長です」とありますけれども、これはどういうことなのか、説明をいただきたいと思います。あわせまして、請願項目４にかかわることなのですけれども、特定整備路線で買収された用地の暫定利用に関しては、さまざまな会派からこの間要望も出されていたと思うのですが、現在の都との交渉状況がどうなっているのか伺います。","respondent":"鈴木都市計画課長","answer":"ご質問としての放射２号線を含めた特定整備路線の実施を都に求めたですが、基本的には当時東京都が大地震、他都市での災害の状況を受けて、やはり市街地の防災性の向上を喫緊に図っていかなければいけないというところの取り組みの１つとして、木密地域が多く広がる地域において。","voiceIndex":99,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり品川区として問い合わせを受けて、しっかり、当時は放射２号線と補助２９号線だったと思いますけれども、続けて早期に整備をということを求めたということですね。問い合わせに対して答えたということですので、まさに今課長が答弁したように、品川区がこの道路を求めたということなのです。整備推進の理由を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"基本的に特定整備路線を、決定して進めていくというところは、東京都がさまざまな調査や検討を加えて決定し、今現在進められているわけですが、補助２９号線を含めて、やはり阪神・淡路大震災で非常に地震後の延焼火災で被害が大きかったというところを受けて。","voiceIndex":101,"id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"ここ大事なところなのでもう一度お伺いしますけれども、交通量調査で、まさにこの地域の交通量、中原街道では４分の１も減っているのに、円滑化という理由は成り立つのでしょうか。シミュレーションをやったと言いますけれども、何棟の建物の延焼を防ぐとか、そのような具体的なものを出されているのでしょうか。だって火災危険度が２なのですから。総合危険度が１なのですから。","respondent":"鈴木都市計画課長、高梨木密整備推進課長","answer":"不燃領域率、一定程度の目標値がありますので、そうしたところまでしっかり目指していかなければいけないというところは、当然ながらこの特定整備路線の整備とあわせて進めていくべきというふうに理解しているものです。放射２号線が通る町丁目を含む地域につきましては、東京都の防災都市づくり推進計画上の木密地域の中でも、より甚大な被害が想定され、整備が要求される整備地域としての位置づけを持っておりまして、その地域の安全性。","voiceIndex":103,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"かなり苦しいといいますか、非常に納得いかないですね。ですからもう、そのような口実で、地域の人が反対している、しかも財産を脅かすような道路を莫大な税金をかけて整備していくというやり方は、私は見直すべきだと思います。最後にこの請願にかかわってお伺いしたいのですけれども、共産党は、この放射２号線は必要ない道路だと考えております。これはこの委員会に対する要望であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-038"},{"speaker":"吉田委員","kind":"提案","question":"今の安藤委員からの提案といいますか、私もこのような懇談会というものは、議会として開催する必要があるのではないかと思います。この当初の経緯などのこともよくわからないし、この説明会自体が、すべて私が議員になる前なのです。続いて質問してもいいですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":108,"id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"説明会の開催を求めるということは、本当にごく自然の要望ではないかなと思います。今、ここの委員会で質疑をすれば、きちんとご答弁もあるわけですし、その辺について説明会を開かない理由がないと思うのですけれども、その説明会を開く意思といいますか、そのようなものがあるのかどうか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"その後も当事者の方には、補償や今後のスケジュールを、用地説明会でしっかり、これも説明会の場を設け実施しているというところでは、区の認識としてはしっかり地域の方への説明の場を設けて進めて、今事業が進められているという認識です。","voiceIndex":111,"id":"exchange-040"},{"speaker":"吉田委員","kind":"質問","question":"責任は都にあるということはそのとおりだと思いますけれども、やはりこれ、区民の方たちの声ですので、一番身近に寄り添うべき自治体である区が、きちんと説明会を開く責任というものはあるのではないかと思います。やはり説明会というものは、個別の対応以外に有用なチャンスではないかと思うのですが、その辺について見解を伺います。","respondent":"鈴木都市計画課長","answer":"そうした中で、繰り返しになりますが、説明会を今後区として都に説明会という場を設けて再度行っていただきたいと求める考えはございませんが、地域の声が区に寄せられれば、あるいは東京都に直接届いても、そうした声には個別に。","voiceIndex":113,"id":"exchange-041"},{"speaker":"吉田委員","kind":"意見","question":"最後になります。そのようなご答弁ですけれども、やはり説明というものは非常に必要だと思います。説明だけに限らず、もう少し意見交換というものが必要だと思いますが、説明というのは最低限の区の責任ではないかと思います。たとえ都の事業であっても、区としての説明会の開催は必要ではないかと主張させていただいて、最後にいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-042"},{"speaker":"石田（秀）委員","kind":"質問","question":"結論を出すで、不採択でお願いをいたします。理由は、特定整備路線、これはここにもありますように、平成２５年からこのような話があって、議論をさまざましてきました。だから私としては、事業認可もおりてしっかりやっているわけでありますから、その前にさまざまな議論はあって、それに基づいて行っているわけですから、早急に整備をしていく、これが大切だと考えています。そのような考えで不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-043"},{"speaker":"たけうち委員","kind":"質問・要望","question":"本日結論を出すでお願いします。不採択でお願いします。理由ですけれども、まず請願の表題が「計画の中止を求める請願」という形になっております。いろいろ項目としては１から４まで、意見交換などいろいろなご意見もありますけれども、基本は中止を求めるというように読み取れます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択なのですが、やはりこの道路そのものを私は見直すべきだと。必要ないということです。そのように思いますし、説明会の開催や、あるいは議会として実際今現場がどうなっているのかということをしっかり把握することも必要だと思います。つまり、認可はおりたといっても、この事業に正当性がないと私は思います。そういった意味からも採択を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-045"},{"speaker":"吉田委員","kind":"質問・要望","question":"本日結論を出すということで、採択を求めたいと思います。この事業に対しては、生活者ネットワークとしても決して賛成できない。これは本当に必要なのだろうかと大変疑問に思っております。その中で、そこの地域の人たちが説明会の実施などを求めてきているということは、当然理解できる心情だと思います。採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-046"}]},{"id":"topic-04","title":"令和元年請願第２０号、品川区Ｃ地区の生活権に関する請願","agenda":"令和元年請願第２０号、品川区Ｃ地区の生活権に関する請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"勉強会には区も参加をされていると思うのですけれども、区の役割について伺いたいのですが、どのような肩書で参加しているのか、毎回参加しておられるのか、あとその具体的な支援、指導、援助、助言などを行うということもあると思うのですけれども、どういった支援、援助を行っているのか。こちらについては出ているのかどうかも伺います。","respondent":"稲田都市開発課長","answer":"ただ、勉強会には最初から参加しておりまして、やはり大井町のまちづくりということで、区の中心核であるということも考え、まちづくりの動向を把握するために同席させているところです。","voiceIndex":131,"id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。請願の一番下の段落になるかと思うのですけれども、ここに地権者の方々の思いが出ているかなと思うのです。一般論ですが、超高層になりますと、なかなか人と人とのつながりがつくりづらくなると。そういったところで、こうしたところに書かれている方々の思いとは矛盾してくるのではないか、区としてはこの書かれている願いにどう応える考えがあるのか、それともないのか、伺います。","respondent":"稲田都市開発課長","answer":"現在もさまざまな機能が入っているところですが、中心核というところもありますけれども、地域の方々が住みよいまちというところも考えております。","voiceIndex":133,"id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"ですから、結局再開発になってしまう、超高層になってしまうのではないかということが、資料からは私は読み取れてしまったのですけれども、伺いたいことは２つなのです。１つは、この勉強会で、そのＱ＆Ａのようにいいところも悪いところも勉強したと。何が起こるのか、どのようなデメリット、メリット、特に区からいうとメリットだと思うのですけれども、メリットが出てくるのか、その２点お伺いします。","respondent":"稲田都市開発課長","answer":"再開発等促進区を定める地区計画、再開発等促進区ですが、これは第一種市街地再開発事業をやるというような話ではございませんで、文面を読ませていただきますと、再開発等促進区を定める地区計画は、まとまった規模を有する低未利用地の土地利用転換を図り。","voiceIndex":135,"id":"exchange-049"},{"speaker":"安藤委員","kind":"確認","question":"１点だけ、再開発促進等の地区なのですけれども、確認なのですが、現在はＣ地区はこの再開発促進区に位置づけられているということは事実で、その位置づけられているということでどのような条件が発生するのかということだけちょっと、それは大事なところだと思うので、お答えいただければ、確認させていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-050"},{"speaker":"たけうち委員","kind":"質問","question":"先ほどのお話では、２４０超の権利者がおり郵送していく中で、やはり権利が細分化されていたり、住所が古くなったりして戻ってくるものもあると。その中でできる限り、今努力されているというお話ですけれども、当然そうだと思うのですが、そこに区が、ぜひお願いしますぐらいは言えるかもしれないけれども、区が責任を持つことではないのかなとは思うのですが、そこの見解はいかがでしょうか。","respondent":"稲田都市開発課長","answer":"ただ、区のほうにも開催通知が届いていないという声も聞こえてきますので、事務局のほうにはなるべく届けて、できる限り届けるようにしてくださいというふうに伝えておりまして、事務局のほうもできる限りやっていくというところの話は聞いております。","voiceIndex":142,"id":"exchange-051"},{"speaker":"たけうち委員","kind":"意見","question":"わかりました。そのようにやっていただいているということで、またぜひ、それはそれでやっていただければいいと思うのですけれども。そもそも区が責任持ってやるのは、ちょっと限度があるのかなと思います。感想です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":144,"id":"exchange-052"},{"speaker":"松本委員","kind":"質問・要望","question":"今ちょっと出ていましたけれども、誰に責任があるのかというところで、これはまだ勉強会だということは本当におっしゃるとおりだと思います。国のほうでも、今年の５月ですか、表題部所有者不明土地の登記及び管理の適正化に関する法律というものも成立して、届かないとか、所在の不明ということは大きな問題だと思っていますので、これは区としてもできることはやっていただきたいと思います。","respondent":"稲田都市開発課長","answer":"事務局に確認したところですが、対象の権利者は２４５あります。郵送数は２２０、なぜ差があるかというと、登記簿のほうに住所が載っていなかったというようなことのようです。それから戻ってきたのが５２というように聞いております。","voiceIndex":145,"id":"exchange-053"},{"speaker":"松本委員","kind":"質問・要望","question":"かなりの数が戻ってきているような状態だと思いますので、これは質問というより、要望で、できる限りご協力いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-054"},{"speaker":"吉田委員","kind":"質問","question":"区として責任を負うというところまではあれですけれども、先ほどのご答弁だと、できる限りの調査を事務局に要請しているという範囲なのです。そこはもう少し何かできることがあるのではないかと思うのですが、あくまでその姿勢、それだと結局参加されている方たちが事務局に要請するのと同じなのではないかと思うのですけれども、区としてはその辺どのようにお考えか伺いたいと思います。","respondent":"稲田都市開発課長","answer":"要するに権利者の方々が自主的にやっている勉強会ですので、区は今のスタンスでやっていきたいと考えています。","voiceIndex":149,"id":"exchange-055"},{"speaker":"吉田委員","kind":"質問・要望","question":"この請願者が一番危惧されているのは、この方自身は勉強会に参加しているわけですよね。勉強会に参加している方の意見ばかりが反映されるということを、すごく危惧されているのではないかと思います。今後またこの請願代表者の方や勉強会に参加されている方たちと話し合いの上、何かできる方策はぜひ考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-056"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほど来話が出ていますが、開催通知が地権者全員の方に、届かないのはあれだけれども、今、昭和６３年に市街地再開発準備組合が設立されたわけですよね。それ以上進んでいるわけではない。その辺のところはしっかり答弁をしていただいて、そこはきちんと分けておかないと、何のための勉強会かわからなくなってしまうから、その辺のところは明確にお答えいただきたいと思います。","respondent":"稲田都市開発課長","answer":"区といたしましては、この勉強会、権利者の方々がやるというところにおきましては、区のほうは現在のところ、区の意見を勉強会に申し入れるというところはやっていないところです。","voiceIndex":153,"id":"exchange-057"},{"speaker":"石田（秀）委員","kind":"意見","question":"最後がよくわからなかったのだけれども、地権者に届いていませんと、区民から話が来ますと。今は勉強しましょうという段階なのだから、区がそこの携わり方をきちんと言っていただかないと、最後の語尾がよくわからなかったので、もう１回よろしくお願いします。","respondent":"稲田都市開発課長","answer":"届いていない方へ、区が届けるようにどうのこうのしろというところではございませんで、区としては届いていないところには事務局等がしっかりと届けるようにしてくださいと言うところまでです。","voiceIndex":155,"id":"exchange-058"},{"speaker":"大沢委員","kind":"確認","question":"そのような立ち位置でいいということですよね。そこを確認させてください。","respondent":"稲田都市開発課長","answer":"その考え方でやっております。","voiceIndex":157,"id":"exchange-059"},{"speaker":"たけうち委員","kind":"質問","question":"結論を出すで、不採択でお願いします。理由については先ほど述べたとおり、開催通知が届くことは大事ですけれども、これは一元的には区ではなく、この事務局、またこのまちづくりの世話人の方でお願いしたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"ですから少なくとも、最終的には決めるのはもちろんその地権者の方々、地域の方々の勉強会の結果のわけですけれども、そういった意味では、私は品川区がやはり行政として、少なくともこの地権者の方々に勉強会の案内を届くような状況をつくるために努力するということは必要なことだと思いますので、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-061"},{"speaker":"吉田委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張したいと思います。この請願は、まちづくり勉強会開催通知がきちんと手元に届くようにということを請願しているものであって、別にこれに反対する理由はないのではないかと思います。一元的には自主的な勉強会ということですが、結論次第によっては区にもいろいろな影響もあることですし、ぜひその辺については検討をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":164,"id":"exchange-062"},{"speaker":"松本委員","kind":"質問・要望","question":"本日結論を出すで、趣旨採択を主張いたします。ただ、先ほども少し申し上げましたけれども、これ不動産登記が全くきちんと管理されていない、２００幾つあるうちの５０に届かないということは、これは制度上もやはり、本来は考えていかないといけないところだと思います。なので、可能な限り、民民の中でも区としてはできる限りのことをやっていただきたいというところで、趣旨採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":165,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"私は、趣旨採択に、変えることを私はやぶさかではありません。１人でも多くの方が、こういった請願者の方々の意を酌んで意思を示すということは大事だと思います。私は趣旨採択に変えてもいいという立場です。吉田委員はいかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-064"}]},{"id":"topic-05","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"公園の事故のほうなのですけれども、着地マットが破損しているとか、とげが出ている、ささくれということですか。今回はけがをされたのでお申し出があったということだと思うのですが、それ以前にこのようなことになっているよというような情報は寄せられたりはしていなかったのでしょうか。その辺ちょっと伺いたいと思います。","respondent":"溝口公園課長","answer":"今回起きた西八丁公園での事故の件です。破損していた着地マットが少しわかりづらかったのかもしれません。もう一度改めてご説明します。滑り台をおりた際に、地面が掘れないように敷いていたもので、また、着地したときの衝撃を吸収するためにつけていたものです。","voiceIndex":176,"id":"exchange-065"},{"speaker":"吉田委員","kind":"確認","question":"わかりました。それで、前の点検のときから少しえぐれているかなというようなことはあったのだけれども、それほどではないということでそのままにされた結果、そのようになったのだと思いますけれども、このようなことは結構、今回はけがに至ったということで、その方のお申し出があったというふうに理解していいでしょうか。ごめんなさい、もう１回確認させてください。","respondent":"溝口公園課長","answer":"申しわけありませんでした。今回はけがされた親御さんのほうから、今回滑り台でけがをしたということで申し出があって、けがをしたという事実を確認したということです。","voiceIndex":178,"id":"exchange-066"},{"speaker":"吉田委員","kind":"質問","question":"結構このようなものというのは、１つよく言われるのが、事故があったときにその周辺ではヒヤリハットが幾つかあるとか、すりむいた程度だったら余り気になさらない親御さんなど、いろいろあると思うのですけれども、ちょっとその辺の対応が、明確にけががあって訴えてこられたというようなことで和解に至ったのだと思うのですが、その辺の扱いというもの、ごめんなさい、答弁難しいかと思いますけれども。","respondent":"溝口公園課長","answer":"今回の件です。先ほども年１回の遊具点検の中で少し、やはり滑り台からおりて着地するところになりますので、どうしても着地が多いところについてはだんだん土が、地面がへこんできてくぼむ、そういった状態が昨年の遊具点検の中で実際に見られたところです。","voiceIndex":180,"id":"exchange-067"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ事前の点検というものをまずはしっかりしていただきたいということと、今回はもうけがをされてしまって、ある意味有無を言わせぬ事実というものがあったと思うのですけれども、やはり中には、これ本当に危ないのではないか、うちの子は転んだと。別にけがというほどではないけれども、公園課としてはどうなのかということを言ってこられる方が、いるのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-068"},{"speaker":"安藤委員","kind":"質問・要望","question":"改めて確認させていただきたいのですが、年に１回の点検と日常点検があるということですけれども、具体的に誰がどのように行っているのかということをそれぞれ教えていただきたいのと、この当該公園での直近の点検というものはいつだったのか伺います。そして現在、滑り台は具体的にどのような補修がされたのか伺います。","respondent":"溝口公園課長","answer":"より安全な形で子どもたちに楽しんでいただけるような遊具にしようと考えて、補修をしたところです。","voiceIndex":184,"id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"今の説明ですと、かなり丁寧にというか、点検をしているのだなとは思いました。ぜひこのように補修した、もうお伝えしているかもしれないのですけれども、これに限らず、対応したり補修したりした後には、実際に事故に遭った方には、このようにしましたよということを具体的に報告していただきたいと思いますし、その徹底をお願いしたいと思います。","respondent":"溝口公園課長","answer":"区の中でもこれまでさまざまな、こういった専決処分に至るような事故、またはそうではない軽い事故を含めて、さまざま事故がやむを得ず起きているところもありますので、そういったものについてはしっかり公園課の中でデータとして残していくとともに。","voiceIndex":186,"id":"exchange-070"},{"speaker":"たけうち委員","kind":"質問","question":"余り聞かないので、もしかしたらなくなってしまったのか、それならそれはなぜなのかということと、それからこの専決処分２つに関係するのですけれども、相手方のお名前がこのような形で議会に出る、公開されるものは黒塗りがされる形になりますが、これに関しては、一応この相手先には、このような形で議会に報告しますなどという了解はとられているかどうか、そこを教えてください。","respondent":"溝口公園課長","answer":"今回、相手方には、こういった形で報告するということの確認をとりながら、専決処分の報告をさせていただいているものです。","voiceIndex":189,"id":"exchange-071"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。１週間に１回、または２週間に１回点検されているということで、非常に入念にやっていらっしゃるのですけれども、やはり利用している人でないとわからない部分が、先ほど吉田委員からもありましたので、そのような仕組みをぜひまたご活用いただきながら、安全な公園の管理に努めていただければと思います。それは要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-072"},{"speaker":"石田（秀）委員","kind":"意見","question":"そのようなことも含めて、子どもたちの環境づくりには遊具は必要だと思うので、ぜひ維持をしていただく形で、安全を確保していただいて、子どもたちが危なく使っているのもしようがないかなというような、それは本当にあってはならないけれども、そのような使い方をしている子どもたちがいるのは事実だから、この例がどうということではなくて、そうではなくてそのような形で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":192,"id":"exchange-073"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２９日の須貝行宏議員の質問で、災害時・停電時の中高層マンション対策についての質問なのですが、ご答弁で非常用エレベーターや照明用の発電機の設置は義務づけているということでしたけれども、具体的に何基のエレベーターが何時間動かせるものなのかというところや、あるいは照明についても共用部分のみなのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-074"},{"speaker":"安藤委員","kind":"質問","question":"どこまで義務づけているのかということと、その義務づけたことによって、どのような活動までができるのかということもお伺いさせていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-075"},{"speaker":"安藤委員","kind":"質問・要望","question":"何時間使えて、一方で在宅避難用の設置は義務づけていないという答弁もあったので、では結局その義務づけられた発電機で、どのような救援活動ができるのか。何人の方が何時間、何日滞在できるのかとか、そのようなところまで伺わせていただきたいと思ったということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":199,"id":"exchange-076"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4278#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":52162,"voices":204}}]);
